import { useEffect, useState, useCallback } from 'react';
import { BrowserRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';

import PublicHomePage from './features/public/pages/PublicHomePage';
import PublicApplyPage from './features/public/pages/PublicApplyPage';
import LoginPage from './features/auth/login';
// RegisterPage is REMOVED
import CustomerDashboardPage from './features/dashboard/pages/customer/CustomerDashboardPage';
import AdminDashboardPage from './features/dashboard/pages/admin/AdminDashboardPage';
import BranchManagerDashboardPage from './features/dashboard/pages/bankManager/BankManagerDashboardPage';
import BankLoanManagerPage from './features/dashboard/pages/bankManager/loan/BankLoanManagerPage';
import HrDashboardPage from './features/dashboard/pages/hr/HrDashboardPage';
import KycOfficerDashboard from './features/dashboard/pages/kycOfficer/KycOfficerDashboard';
import KycApplicationDetail from './features/dashboard/pages/kycOfficer/KycApplicationDetail';

import { getCurrentUser, logout } from './services/authService';


// ---- Role helpers ----
function normalizeRoles(user) {
  const raw = Array.isArray(user?.roles) ? user.roles : [];
  return raw.map((r) => String(r).toUpperCase().replace(/^ROLE_/, ''));
}

function hasRole(user, ...allowed) {
  const roles = normalizeRoles(user);
  return allowed.some((r) => roles.includes(r));
}

// ---- Route guard ----
function ProtectedRoute({ user, roles, children }) {
  if (!user) return <Navigate to="/login" replace />;
  if (roles && !hasRole(user, ...roles)) return <Navigate to="/dashboard" replace />;
  return children;
}

// ---- Dashboard router ----
function DashboardForUser({ currentUser, onSignOut, onNavigate }) {
  if (hasRole(currentUser, 'ADMIN')) {
    return <AdminDashboardPage user={currentUser} onSignOut={onSignOut} />;
  }
  if (hasRole(currentUser, 'KYC_OFFICER')) {
    return <Navigate to="/kyc-officer/dashboard" replace />;
  }
  if (hasRole(currentUser, 'BRANCH_MANAGER')) {
    return (
      <BranchManagerDashboardPage
        user={currentUser}
        onNavigate={onNavigate}
        onSignOut={onSignOut}
      />
    );
  }
  if (hasRole(currentUser, 'LOAN_OFFICER')) {
    return (
      <BankLoanManagerPage
        standalone
        canManageProducts
        canProcessApplications
        currentUser={currentUser}
        onSignOut={onSignOut}
      />
    );
  }
  if (hasRole(currentUser, 'HR', 'HR_MANAGER')) {
    return <HrDashboardPage onSignOut={onSignOut} />;
  }
  return <CustomerDashboardPage customer={currentUser} onSignOut={onSignOut} />;
}

function AppRoutes() {
  const [user, setUser] = useState(null);
  const [sessionMessage, setSessionMessage] = useState('');
  const [authReady, setAuthReady] = useState(false);
  const [authError, setAuthError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const currentUser = await getCurrentUser();
        if (active) setUser(currentUser);
      } catch {
        if (active) setUser(null);
      } finally {
        if (active) setAuthReady(true);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const handleSessionExpired = () => {
      setUser(null);
      setSessionMessage('Your session expired. Sign in again to continue.');
      navigate('/login', { replace: true });
    };
    window.addEventListener('nova:session-expired', handleSessionExpired);
    return () => window.removeEventListener('nova:session-expired', handleSessionExpired);
  }, [navigate]);

  const handleSignOut = useCallback(async () => {
    try {
      await logout();
    } catch (err) {
      console.warn('Logout failed:', err);
    }
    setUser(null);
    setSessionMessage('');
    navigate('/', { replace: true });
  }, [navigate]);

  const handleSignIn = useCallback(
    (u) => {
      setSessionMessage('');
      setUser(u);
      navigate('/dashboard', { replace: true });
    },
    [navigate]
  );

  if (!authReady) {
    return (
      <main className="login-app">
        <div className="auth-loading">Preparing your secure Nova experience…</div>
      </main>
    );
  }

  const errorBanner = authError ? (
    <div className="auth-error" role="alert">
      {authError}
      <button type="button" onClick={() => setAuthError('')}>
        Dismiss
      </button>
    </div>
  ) : null;

  return (
    <>
      {errorBanner}
      <Routes>
        {/* Public home */}
        <Route
          path="/"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <PublicHomePage
                onLogin={() => navigate('/login')}
                onOpenAccount={() => navigate('/apply')}
              />
            )
          }
        />

        {/* Public account application — no login required */}
        <Route
          path="/apply"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <PublicApplyPage />
            )
          }
        />

        <Route
          path="/login"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <LoginPage
                onSignIn={handleSignIn}
                onNavigate={navigate}
                sessionMessage={sessionMessage}
              />
            )
          }
        />

        {/* Register route intentionally removed */}

        <Route
          path="/dashboard"
          element={
            <ProtectedRoute user={user}>
              <DashboardForUser
                currentUser={user}
                onSignOut={handleSignOut}
                onNavigate={navigate}
              />
            </ProtectedRoute>
          }
        />

        <Route
          path="/kyc-officer/dashboard"
          element={
            <ProtectedRoute user={user} roles={['KYC_OFFICER']}>
              <KycOfficerDashboard onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />
        <Route
          path="/kyc-officer/application/:kycId"
          element={
            <ProtectedRoute user={user} roles={['KYC_OFFICER']}>
              <KycApplicationDetail />
            </ProtectedRoute>
          }
        />

        <Route
          path="/hr/dashboard"
          element={
            <ProtectedRoute user={user} roles={['HR', 'HR_MANAGER']}>
              <HrDashboardPage onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />

        <Route
          path="/branch-manager/dashboard"
          element={
            <ProtectedRoute user={user} roles={['BRANCH_MANAGER']}>
              <BranchManagerDashboardPage
                user={user}
                onNavigate={navigate}
                onSignOut={handleSignOut}
              />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/dashboard"
          element={
            <ProtectedRoute user={user} roles={['ADMIN']}>
              <AdminDashboardPage user={user} onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AppRoutes />
    </BrowserRouter>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { BrowserRouter, Routes, Route, Navigate, useNavigate } from 'react-router-dom';

import PublicHomePage from './features/public/pages/PublicHomePage';
import PublicApplyPage from './features/public/pages/PublicApplyPage';
import LoginPage from './features/auth/login';
// RegisterPage is REMOVED
import CustomerDashboardPage from './features/dashboard/pages/customer/CustomerDashboardPage';
import AdminDashboardPage from './features/dashboard/pages/admin/AdminDashboardPage';
import BranchManagerDashboardPage from './features/dashboard/pages/bankManager/BankManagerDashboardPage';
import BankLoanManagerPage from './features/dashboard/pages/bankManager/loan/BankLoanManagerPage';
import HrDashboardPage from './features/dashboard/pages/hr/HrDashboardPage';
import KycOfficerDashboard from './features/dashboard/pages/kycOfficer/KycOfficerDashboard';
import KycApplicationDetail from './features/dashboard/pages/kycOfficer/KycApplicationDetail';

import { getCurrentUser, logout } from './services/authService';


// ---- Role helpers ----
function normalizeRoles(user) {
  const raw = Array.isArray(user?.roles) ? user.roles : [];
  return raw.map((r) => String(r).toUpperCase().replace(/^ROLE_/, ''));
}

function hasRole(user, ...allowed) {
  const roles = normalizeRoles(user);
  return allowed.some((r) => roles.includes(r));
}

// ---- Route guard ----
function ProtectedRoute({ user, roles, children }) {
  if (!user) return <Navigate to="/login" replace />;
  if (roles && !hasRole(user, ...roles)) return <Navigate to="/dashboard" replace />;
  return children;
}

// ---- Dashboard router ----
function DashboardForUser({ currentUser, onSignOut, onNavigate }) {
  if (hasRole(currentUser, 'ADMIN')) {
    return <AdminDashboardPage user={currentUser} onSignOut={onSignOut} />;
  }
  if (hasRole(currentUser, 'KYC_OFFICER')) {
    return <Navigate to="/kyc-officer/dashboard" replace />;
  }
  if (hasRole(currentUser, 'BRANCH_MANAGER')) {
    return (
      <BranchManagerDashboardPage
        user={currentUser}
        onNavigate={onNavigate}
        onSignOut={onSignOut}
      />
    );
  }
  if (hasRole(currentUser, 'LOAN_OFFICER')) {
    return (
      <BankLoanManagerPage
        standalone
        canManageProducts={false}
        canProcessApplications
        currentUser={currentUser}
        onSignOut={onSignOut}
      />
    );
  }
  if (hasRole(currentUser, 'HR', 'HR_MANAGER')) {
    return <HrDashboardPage onSignOut={onSignOut} />;
  }
  return <CustomerDashboardPage customer={currentUser} onSignOut={onSignOut} />;
}

function AppRoutes() {
  const [user, setUser] = useState(null);
  const [sessionMessage, setSessionMessage] = useState('');
  const [authReady, setAuthReady] = useState(false);
  const [authError, setAuthError] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const currentUser = await getCurrentUser();
        if (active) setUser(currentUser);
      } catch {
        if (active) setUser(null);
      } finally {
        if (active) setAuthReady(true);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    const handleSessionExpired = () => {
      setUser(null);
      setSessionMessage('Your session expired. Sign in again to continue.');
      navigate('/login', { replace: true });
    };
    window.addEventListener('nova:session-expired', handleSessionExpired);
    return () => window.removeEventListener('nova:session-expired', handleSessionExpired);
  }, [navigate]);

  const handleSignOut = useCallback(async () => {
    try {
      await logout();
    } catch (err) {
      console.warn('Logout failed:', err);
    }
    setUser(null);
    setSessionMessage('');
    navigate('/', { replace: true });
  }, [navigate]);

  const handleSignIn = useCallback(
    (u) => {
      setSessionMessage('');
      setUser(u);
      navigate('/dashboard', { replace: true });
    },
    [navigate]
  );

  if (!authReady) {
    return (
      <main className="login-app">
        <div className="auth-loading">Preparing your secure Nova experience…</div>
      </main>
    );
  }

  const errorBanner = authError ? (
    <div className="auth-error" role="alert">
      {authError}
      <button type="button" onClick={() => setAuthError('')}>
        Dismiss
      </button>
    </div>
  ) : null;

  return (
    <>
      {errorBanner}
      <Routes>
        {/* Public home */}
        <Route
          path="/"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <PublicHomePage
                onLogin={() => navigate('/login')}
                onOpenAccount={() => navigate('/apply')}
              />
            )
          }
        />

        {/* Public account application — no login required */}
        <Route
          path="/apply"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <PublicApplyPage />
            )
          }
        />

        <Route
          path="/login"
          element={
            user ? (
              <Navigate to="/dashboard" replace />
            ) : (
              <LoginPage
                onSignIn={handleSignIn}
                onNavigate={navigate}
                sessionMessage={sessionMessage}
              />
            )
          }
        />

        {/* Register route intentionally removed */}

        <Route
          path="/dashboard"
          element={
            <ProtectedRoute user={user}>
              <DashboardForUser
                currentUser={user}
                onSignOut={handleSignOut}
                onNavigate={navigate}
              />
            </ProtectedRoute>
          }
        />

        <Route
          path="/kyc-officer/dashboard"
          element={
            <ProtectedRoute user={user} roles={['KYC_OFFICER']}>
              <KycOfficerDashboard onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />
        <Route
          path="/kyc-officer/application/:kycId"
          element={
            <ProtectedRoute user={user} roles={['KYC_OFFICER']}>
              <KycApplicationDetail />
            </ProtectedRoute>
          }
        />

        <Route
          path="/hr/dashboard"
          element={
            <ProtectedRoute user={user} roles={['HR', 'HR_MANAGER']}>
              <HrDashboardPage onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />

        <Route
          path="/branch-manager/dashboard"
          element={
            <ProtectedRoute user={user} roles={['BRANCH_MANAGER']}>
              <BranchManagerDashboardPage
                user={user}
                onNavigate={navigate}
                onSignOut={handleSignOut}
              />
            </ProtectedRoute>
          }
        />

        <Route
          path="/admin/dashboard"
          element={
            <ProtectedRoute user={user} roles={['ADMIN']}>
              <AdminDashboardPage user={user} onSignOut={handleSignOut} />
            </ProtectedRoute>
          }
        />

        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AppRoutes />
    </BrowserRouter>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { clearAuthSession, getSavedAuthUser } from '../../../../services/apiClient';
import adminService from '../../../../services/adminService';
import CustomerManagementPage from './CustomerManagementPage';
import BranchManagementPage from './BranchManagementPage';
import AccountManagementPage from './AccountManagementPage';
import KycManagementPage from './KycManagementPage';
import TransactionManagementPage from './TransactionManagementPage';
import ReportsAnalyticsPage from './ReportsAnalyticsPage';
import EmployeeManagementPage from './EmployeeManagementPage';
import BranchDetailsPage from './BranchDetailsPage';
import BankLoanManagerPage from '../bankManager/loan/BankLoanManagerPage';
import './AdminDashboard.css';

const { normalizeList, pageTotal } = adminService;

const initials = (name) =>
  String(name || 'Admin').trim().split(/\s+/).slice(0, 2).map((p) => p[0]?.toUpperCase() ?? '').join('') || 'AD';

const formatMoney = (v) => {
  if (v == null || v === '') return '—';
  const n = Number(v);
  return Number.isNaN(n) ? String(v) : new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(n);
};

const formatDate = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
};

const formatTime = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
};

const shortId = (id, len = 14) => (id ? String(id).slice(0, len) : '—');

const statusTone = (s) => {
  const v = String(s || '').toUpperCase();
  if (['SUCCESS', 'COMPLETED', 'APPROVED', 'ACTIVE'].includes(v)) return 'ok';
  if (['PENDING', 'UNDER_REVIEW', 'PROCESSING', 'IN_PROGRESS'].includes(v)) return 'warn';
  if (['FAILED', 'REJECTED', 'CLOSED', 'DECLINED'].includes(v)) return 'bad';
  return 'neutral';
};

const NAV_ITEMS = [
  { label: 'Dashboard', icon: '▦', id: 'Dashboard' },
  { label: 'Customer Management', icon: '', id: 'Customers' },
  { label: 'Employee Management', icon: '', id: 'Employees' },
  { label: 'Branch Management', icon: '', id: 'Branches' },
  { label: 'Account Management', icon: '▣', id: 'Accounts' },
  { label: 'KYC Oversight', icon: '', id: 'KYC' },
  { label: 'Transaction Monitoring', icon: '⇄', id: 'Transactions' },
  { label: 'Reports & Analytics', icon: '▤', id: 'Reports' },
  { label: 'Loan Products', icon: '₹', id: 'Loans' },
  { label: 'Settings', icon: '⚙', id: 'Settings' },
];

export default function AdminDashboardPage({ user, onSignOut }) {
  const navigate = useNavigate();

  const [activePage, setActivePage] = useState('Dashboard');
  const [selectedBranch, setSelectedBranch] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);

  //  State for the Logout Confirmation Modal
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  const [customers, setCustomers] = useState([]);
  const [customerTotal, setCustomerTotal] = useState(0);
  const [accounts, setAccounts] = useState([]);
  const [accountTotal, setAccountTotal] = useState(0);
  const [transactions, setTransactions] = useState([]);
  const [transactionTotal, setTransactionTotal] = useState(0);
  const [branches, setBranches] = useState([]);
  const [kyc, setKyc] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const identity = useMemo(() => {
    const saved = getSavedAuthUser();
    const merged = { ...(saved || {}), ...(user || {}) };
    return {
      name: merged.fullName ?? merged.name ?? merged.email ?? 'Administrator',
      email: merged.email ?? '',
      roles: merged.roles || [],
    };
  }, [user]);

  const load = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    setError('');

    const tasks = [
      { label: 'Customers', run: () => adminService.getAllCustomers({ page: 0, size: 100 }), apply: (v) => { setCustomers(normalizeList(v)); setCustomerTotal(pageTotal(v)); } },
      { label: 'Accounts', run: () => adminService.getAllAccounts({ page: 0, size: 100 }), apply: (v) => { setAccounts(normalizeList(v)); setAccountTotal(pageTotal(v)); } },
      { label: 'Transactions', run: () => adminService.getAllTransactions({ page: 0, size: 100 }), apply: (v) => { setTransactions(normalizeList(v)); setTransactionTotal(pageTotal(v)); } },
      { label: 'Branches', run: () => adminService.searchBranches({ page: 0, size: 100 }), apply: (v) => setBranches(normalizeList(v)) },
      { label: 'KYC', run: () => adminService.getAllKyc(), apply: (v) => setKyc(normalizeList(v)) },
    ];

    const results = await Promise.allSettled(tasks.map((t) => t.run()));
    const failures = [];
    results.forEach((r, i) => {
      if (r.status === 'fulfilled') tasks[i].apply(r.value);
      else failures.push(`${tasks[i].label}: ${r.reason?.message || 'failed'}`);
    });

    if (failures.length === tasks.length) {
      setError(`Could not load any data. ${failures.join(' · ')}`);
    } else if (failures.length) {
      setError(`Some sections failed: ${failures.join(' · ')}`);
    }

    setLoading(false);
    setRefreshing(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const stats = useMemo(() => {
    const today = new Date().toDateString();
    const txnsToday = transactions.filter((t) => { const d = t.createdAt ?? t.transactionDate; return d && new Date(d).toDateString() === today; }).length;
    const txnsFailed = transactions.filter((t) => String(t.transactionStatus ?? t.status ?? '').toUpperCase() === 'FAILED').length;
    const pendingKyc = kyc.filter((k) => ['PENDING', 'UNDER_REVIEW'].includes(String(k.verificationStatus ?? k.kycVerificationStatus ?? '').toUpperCase())).length;
    const approvedKyc = kyc.filter((k) => String(k.verificationStatus ?? k.kycVerificationStatus ?? '').toUpperCase() === 'APPROVED').length;
    const activeAccounts = accounts.filter((a) => String(a.accountStatus ?? a.status ?? '').toUpperCase() === 'ACTIVE').length;
    const activeBranches = branches.filter((b) => String(b.status ?? '').toUpperCase() === 'ACTIVE').length;

    return {
      customers: customerTotal || customers.length, accounts: accountTotal || accounts.length, activeAccounts,
      branches: branches.length, activeBranches, kycTotal: kyc.length, pendingKyc, approvedKyc,
      txnsToday, txnsFailed, txnsTotal: transactionTotal || transactions.length,
    };
  }, [customerTotal, customers, accountTotal, accounts, transactions, transactionTotal, kyc, branches]);

  const recentActivity = useMemo(() => {
    const txns = transactions.slice(0, 8).map((t) => ({
      id: t.transactionId ?? t.id, time: t.createdAt ?? t.transactionDate, type: t.transactionType ?? t.type ?? 'Transaction',
      ref: t.accountNumber ?? t.fromAccountNumber ?? t.toAccountNumber ?? '—', detail: t.description ?? formatMoney(t.amount), status: t.transactionStatus ?? t.status ?? '—',
    }));

    const kycRows = kyc.slice(0, 4).map((k) => ({
      id: k.kycId ?? k.id, time: k.createdAt ?? k.updatedAt, type: 'KYC', ref: shortId(k.customerId), detail: `${k.kycType ?? 'KYC'} review`, status: k.verificationStatus ?? k.kycVerificationStatus ?? '—',
    }));

    return [...txns, ...kycRows].sort((a, b) => new Date(b.time ?? 0) - new Date(a.time ?? 0)).slice(0, 8);
  }, [transactions, kyc]);

  const handleLogout = () => {
    clearAuthSession();
    if (typeof onSignOut === 'function') onSignOut();
    else navigate('/login', { replace: true });
  };

  return (
    <div className="ad-shell">
      <aside className="ad-sidebar">
        <a className="ad-brand" href="#dashboard" onClick={(e) => e.preventDefault()}>
          <span className="ad-brand-mark">N</span>
          <span className="ad-brand-text">
            <strong>NOVA BANK</strong>
            <small>Your Trust. Our Priority.</small>
          </span>
        </a>

        <div className="ad-user">
          <span className="ad-avatar">{initials(identity.name)}</span>
          <div className="ad-user-info">
            <b>{identity.name}</b>
            <small>Super Admin</small>
            <span className="ad-online"><i />Online</span>
          </div>
        </div>

        <div className="ad-nav-label">Workspace</div>
        <nav className="ad-nav">
          {NAV_ITEMS.map((item) => (
            <button key={item.id} className={activePage === item.id ? 'active' : ''} onClick={() => { setActivePage(item.id); setSelectedBranch(null); }}>
              <span className="ad-nav-icon">{item.icon}</span>
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="ad-sidebar-bottom">
          {/*  Trigger the confirmation modal here */}
          <button className="ad-logout" onClick={() => setShowLogoutModal(true)}>
            <span className="ad-nav-icon">⏻</span>
            <span>Logout</span>
          </button>
          <div className="ad-secure">
            <span className="ad-secure-dot" /> Signed in securely
          </div>
        </div>
      </aside>

      <div className="ad-main">
        <header className="ad-topbar">
          <div className="ad-topbar-left">
            <div className="ad-topbar-title">
              <strong>Super Admin Dashboard</strong>
              <span>Bank-wide operations &amp; oversight</span>
            </div>
          </div>

          <div className="ad-topbar-right" style={{ position: 'relative' }}>
            <button className="ad-icon-btn" aria-label="Notifications">

              <span className="ad-badge">{stats.pendingKyc + stats.txnsFailed}</span>
            </button>

            <button className="ad-profile" onClick={() => setProfileOpen(!profileOpen)} title="View Profile">
              <span className="ad-avatar-sm">{initials(identity.name)}</span>
              <span className="ad-profile-name">{identity.name}</span>
              <span className="ad-chevron"></span>
            </button>

            {profileOpen && (
              <div className="ad-profile-popover">
                <div className="ad-popover-header">
                  <span className="ad-avatar-lg">{initials(identity.name)}</span>
                  <div><b>{identity.name}</b><small>{identity.email}</small></div>
                </div>
                <div className="ad-popover-body">
                  <div className="ad-popover-row"><span>Role</span><b>{identity.roles[0] || 'ADMIN'}</b></div>
                  <div className="ad-popover-row"><span>Status</span><span className="ad-status ad-status-ok">Active</span></div>
                </div>
                <div className="ad-popover-footer">
                  {/*  Trigger the confirmation modal here too */}
                  <button onClick={() => { setProfileOpen(false); setShowLogoutModal(true); }} className="ad-logout-btn">
                    Logout
                  </button>
                </div>
              </div>
            )}
          </div>
        </header>

        <div className="ad-content">
          {selectedBranch ? (
            <BranchDetailsPage branch={selectedBranch} onBack={() => setSelectedBranch(null)} />
          ) : (
            <>
              {activePage === 'Customers' && <CustomerManagementPage />}
              {activePage === 'Employees' && <EmployeeManagementPage />}
              {activePage === 'Branches' && <BranchManagementPage onViewBranch={(branch) => setSelectedBranch(branch)} />}
              {activePage === 'Accounts' && <AccountManagementPage />}
              {activePage === 'KYC' && <KycManagementPage />}
              {activePage === 'Transactions' && <TransactionManagementPage />}
              {activePage === 'Reports' && <ReportsAnalyticsPage />}
              {activePage === 'Loans' && (
                <BankLoanManagerPage canManageProducts canProcessApplications />
              )}

              {!['Dashboard', 'Customers', 'Employees', 'Branches', 'Accounts', 'KYC', 'Transactions', 'Reports', 'Loans'].includes(activePage) && (
                <div className="ad-panel" style={{ padding: '40px', textAlign: 'center', color: '#7c879a' }}>
                  <h2>{activePage} Module</h2>
                  <p>This section is currently under construction.</p>
                </div>
              )}

              {activePage === 'Dashboard' && (
                <>
                  <div className="ad-welcome">
                    <div>
                      <h1>Welcome back, {identity.name.split(' ')[0]}!</h1>
                      <p>Monitor bank-wide operations, review activity, and oversee customer, branch, and compliance workflows.</p>
                    </div>
                    <div className="ad-welcome-side">
                      <div className="ad-chip">
                        <span className="ad-chip-icon"></span>
                        <div><b>{stats.branches} branches</b><small>{stats.activeBranches} active</small></div>
                      </div>
                      <div className="ad-chip">
                        <span className="ad-chip-icon"></span>
                        <div>
                          <b>{new Intl.DateTimeFormat('en-IN', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }).format(new Date())}</b>
                          <small>{new Intl.DateTimeFormat('en-IN', { hour: '2-digit', minute: '2-digit' }).format(new Date())}</small>
                        </div>
                      </div>
                    </div>
                  </div>

                  {error && (
                    <div className="ad-alert" role="alert">
                      {error}
                      <button onClick={load} disabled={refreshing}>{refreshing ? 'Retrying…' : 'Retry'}</button>
                    </div>
                  )}

                  <section className="ad-kpis">
                    <Kpi icon="" label="Total customers" value={stats.customers} tone="blue" loading={loading} />
                    <Kpi icon="▣" label="Total accounts" value={stats.accounts} tone="violet" loading={loading} />
                    <Kpi icon="" label="Total branches" value={stats.branches} tone="green" loading={loading} />
                    <Kpi icon="" label="Pending KYC" value={stats.pendingKyc} tone="amber" loading={loading} />
                    <Kpi icon="⇄" label="Today's transactions" value={stats.txnsToday} tone="teal" loading={loading} />
                    <Kpi icon="⚠" label="Failed transactions" value={stats.txnsFailed} tone="red" loading={loading} />
                    <Kpi icon="✓" label="Approved KYC" value={stats.approvedKyc} tone="green" loading={loading} />
                    <Kpi icon="◆" label="Active accounts" value={stats.activeAccounts} tone="blue" loading={loading} />
                  </section>

                  <section className="ad-grid">
                    <div className="ad-panel">
                      <div className="ad-panel-head">
                        <div><h2>Recent system activity</h2><p>Latest transactions and KYC events</p></div>
                        <button className="ad-ghost" onClick={() => setActivePage('Transactions')}>View all →</button>
                      </div>

                      <div className="ad-table-wrap">
                        <table className="ad-table">
                          <thead>
                            <tr><th>Time</th><th>Type</th><th>Reference</th><th>Details</th><th>Status</th></tr>
                          </thead>
                          <tbody>
                            {loading ? (
                              <tr><td colSpan="5" className="ad-empty">Loading activity…</td></tr>
                            ) : recentActivity.length === 0 ? (
                              <tr><td colSpan="5" className="ad-empty">No recent activity.</td></tr>
                            ) : (
                              recentActivity.map((row, i) => (
                                <tr key={`${row.id || i}`}>
                                  <td className="ad-cell-time">{formatDate(row.time)} · {formatTime(row.time)}</td>
                                  <td>{row.type}</td>
                                  <td className="ad-cell-ref">{row.ref}</td>
                                  <td>{row.detail}</td>
                                  <td><StatusPill tone={statusTone(row.status)}>{String(row.status).replaceAll('_', ' ')}</StatusPill></td>
                                </tr>
                              ))
                            )}
                          </tbody>
                        </table>
                      </div>
                    </div>

                    <div className="ad-panel">
                      <div className="ad-panel-head">
                        <div><h2>Quick actions</h2><p>Common administrative tasks</p></div>
                      </div>

                      <ul className="ad-actions">
                        <ActionRow icon="" label="Search customers" hint={`${stats.customers} records`} onClick={() => setActivePage('Customers')} />
                        <ActionRow icon="" label="Manage employees" hint="HR & Roles" onClick={() => setActivePage('Employees')} />
                        <ActionRow icon="" label="Manage branches" hint={`${stats.branches} branches`} onClick={() => setActivePage('Branches')} />
                        <ActionRow icon="" label="Review KYC queue" hint={`${stats.pendingKyc} pending`} onClick={() => setActivePage('KYC')} />
                        <ActionRow icon="⇄" label="Monitor transactions" hint={`${stats.txnsTotal} total`} onClick={() => setActivePage('Transactions')} />
                        <ActionRow icon="▣" label="Manage accounts" hint={`${stats.accounts} accounts`} onClick={() => setActivePage('Accounts')} />
                      </ul>
                    </div>
                  </section>

                  <footer className="ad-footer">
                    © 2026 Nova Bank · Super Admin
                    <span>{refreshing ? 'Refreshing…' : 'Live data'}</span>
                  </footer>
                </>
              )}
            </>
          )}
        </div>
      </div>

      {/*  LOGOUT CONFIRMATION MODAL */}
      {showLogoutModal && (
        <div 
          style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(15, 23, 42, 0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 9999 }}
          onClick={() => setShowLogoutModal(false)}
        >
          <div 
            style={{ background: '#fff', padding: '24px', borderRadius: '12px', width: '100%', maxWidth: '400px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)' }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>Log out of Nova Bank?</h3>
            <p style={{ color: '#64748b', fontSize: '14px', margin: '0 0 24px 0', lineHeight: 1.5 }}>
              Are you sure you want to securely log out of your account? You will need to sign in again to continue.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button onClick={() => setShowLogoutModal(false)} style={{ padding: '8px 16px', background: 'transparent', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer', fontWeight: 600, color: '#475569' }}>
                Cancel
              </button>
              <button onClick={handleLogout} style={{ padding: '8px 16px', background: '#e11d48', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600, color: 'white' }}>
                Yes, log out
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Kpi({ icon, label, value, tone = 'blue', loading }) {
  return (
    <article className={`ad-kpi ad-kpi-${tone}`}>
      <span className="ad-kpi-icon">{icon}</span>
      <div className="ad-kpi-body">
        <span className="ad-kpi-label">{label}</span>
        <strong className="ad-kpi-value">{loading ? '—' : value}</strong>
      </div>
    </article>
  );
}

function StatusPill({ tone = 'neutral', children }) {
  return <span className={`ad-status ad-status-${tone}`}>{children}</span>;
}

function ActionRow({ icon, label, hint, onClick }) {
  return (
    <li>
      <button type="button" className="ad-action" onClick={onClick}>
        <span className="ad-action-icon">{icon}</span>
        <span className="ad-action-text">
          <b>{label}</b>
          <small>{hint}</small>
        </span>
        <span className="ad-action-arrow">›</span>
      </button>
    </li>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { clearAuthSession, getSavedAuthUser } from '../../../../services/apiClient';
import adminService from '../../../../services/adminService';
import CustomerManagementPage from './CustomerManagementPage';
import BranchManagementPage from './BranchManagementPage';
import AccountManagementPage from './AccountManagementPage';
import KycManagementPage from './KycManagementPage';
import TransactionManagementPage from './TransactionManagementPage';
import ReportsAnalyticsPage from './ReportsAnalyticsPage';
import EmployeeManagementPage from './EmployeeManagementPage';
import BranchDetailsPage from './BranchDetailsPage';
import BankLoanManagerPage from '../bankManager/loan/BankLoanManagerPage';
import './AdminDashboard.css';

const { normalizeList, pageTotal } = adminService;

const initials = (name) =>
  String(name || 'Admin').trim().split(/\s+/).slice(0, 2).map((p) => p[0]?.toUpperCase() ?? '').join('') || 'AD';

const formatMoney = (v) => {
  if (v == null || v === '') return '—';
  const n = Number(v);
  return Number.isNaN(n) ? String(v) : new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(n);
};

const formatDate = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
};

const formatTime = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? String(v) : d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
};

const shortId = (id, len = 14) => (id ? String(id).slice(0, len) : '—');

const statusTone = (s) => {
  const v = String(s || '').toUpperCase();
  if (['SUCCESS', 'COMPLETED', 'APPROVED', 'ACTIVE'].includes(v)) return 'ok';
  if (['PENDING', 'UNDER_REVIEW', 'PROCESSING', 'IN_PROGRESS'].includes(v)) return 'warn';
  if (['FAILED', 'REJECTED', 'CLOSED', 'DECLINED'].includes(v)) return 'bad';
  return 'neutral';
};

const NAV_ITEMS = [
  { label: 'Dashboard', icon: '▦', id: 'Dashboard' },
  { label: 'Customer Management', icon: '', id: 'Customers' },
  { label: 'Employee Management', icon: '', id: 'Employees' },
  { label: 'Branch Management', icon: '', id: 'Branches' },
  { label: 'Account Management', icon: '▣', id: 'Accounts' },
  { label: 'KYC Oversight', icon: '', id: 'KYC' },
  { label: 'Transaction Monitoring', icon: '⇄', id: 'Transactions' },
  { label: 'Reports & Analytics', icon: '▤', id: 'Reports' },
  { label: 'Loan Products', icon: '₹', id: 'Loans' },
  { label: 'Settings', icon: '⚙', id: 'Settings' },
];

export default function AdminDashboardPage({ user, onSignOut }) {
  const navigate = useNavigate();

  const [activePage, setActivePage] = useState('Dashboard');
  const [selectedBranch, setSelectedBranch] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);
  
  //  State for the Logout Confirmation Modal
  const [showLogoutModal, setShowLogoutModal] = useState(false);

  const [customers, setCustomers] = useState([]);
  const [customerTotal, setCustomerTotal] = useState(0);
  const [accounts, setAccounts] = useState([]);
  const [accountTotal, setAccountTotal] = useState(0);
  const [transactions, setTransactions] = useState([]);
  const [transactionTotal, setTransactionTotal] = useState(0);
  const [branches, setBranches] = useState([]);
  const [kyc, setKyc] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const identity = useMemo(() => {
    const saved = getSavedAuthUser();
    const merged = { ...(saved || {}), ...(user || {}) };
    return {
      name: merged.fullName ?? merged.name ?? merged.email ?? 'Administrator',
      email: merged.email ?? '',
      roles: merged.roles || [],
    };
  }, [user]);

  const load = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    setError('');

    const tasks = [
      { label: 'Customers', run: () => adminService.getAllCustomers({ page: 0, size: 100 }), apply: (v) => { setCustomers(normalizeList(v)); setCustomerTotal(pageTotal(v)); } },
      { label: 'Accounts', run: () => adminService.getAllAccounts({ page: 0, size: 100 }), apply: (v) => { setAccounts(normalizeList(v)); setAccountTotal(pageTotal(v)); } },
      { label: 'Transactions', run: () => adminService.getAllTransactions({ page: 0, size: 100 }), apply: (v) => { setTransactions(normalizeList(v)); setTransactionTotal(pageTotal(v)); } },
      { label: 'Branches', run: () => adminService.searchBranches({ page: 0, size: 100 }), apply: (v) => setBranches(normalizeList(v)) },
      { label: 'KYC', run: () => adminService.getAllKyc(), apply: (v) => setKyc(normalizeList(v)) },
    ];

    const results = await Promise.allSettled(tasks.map((t) => t.run()));
    const failures = [];
    results.forEach((r, i) => {
      if (r.status === 'fulfilled') tasks[i].apply(r.value);
      else failures.push(`${tasks[i].label}: ${r.reason?.message || 'failed'}`);
    });

    if (failures.length === tasks.length) {
      setError(`Could not load any data. ${failures.join(' · ')}`);
    } else if (failures.length) {
      setError(`Some sections failed: ${failures.join(' · ')}`);
    }

    setLoading(false);
    setRefreshing(false);
  }, []);

  useEffect(() => { load(); }, [load]);

  const stats = useMemo(() => {
    const today = new Date().toDateString();
    const txnsToday = transactions.filter((t) => { const d = t.createdAt ?? t.transactionDate; return d && new Date(d).toDateString() === today; }).length;
    const txnsFailed = transactions.filter((t) => String(t.transactionStatus ?? t.status ?? '').toUpperCase() === 'FAILED').length;
    const pendingKyc = kyc.filter((k) => ['PENDING', 'UNDER_REVIEW'].includes(String(k.verificationStatus ?? k.kycVerificationStatus ?? '').toUpperCase())).length;
    const approvedKyc = kyc.filter((k) => String(k.verificationStatus ?? k.kycVerificationStatus ?? '').toUpperCase() === 'APPROVED').length;
    const activeAccounts = accounts.filter((a) => String(a.accountStatus ?? a.status ?? '').toUpperCase() === 'ACTIVE').length;
    const activeBranches = branches.filter((b) => String(b.status ?? '').toUpperCase() === 'ACTIVE').length;

    return {
      customers: customerTotal || customers.length, accounts: accountTotal || accounts.length, activeAccounts,
      branches: branches.length, activeBranches, kycTotal: kyc.length, pendingKyc, approvedKyc,
      txnsToday, txnsFailed, txnsTotal: transactionTotal || transactions.length,
    };
  }, [customerTotal, customers, accountTotal, accounts, transactions, transactionTotal, kyc, branches]);

  const recentActivity = useMemo(() => {
    const txns = transactions.slice(0, 8).map((t) => ({
      id: t.transactionId ?? t.id, time: t.createdAt ?? t.transactionDate, type: t.transactionType ?? t.type ?? 'Transaction',
      ref: t.accountNumber ?? t.fromAccountNumber ?? t.toAccountNumber ?? '—', detail: t.description ?? formatMoney(t.amount), status: t.transactionStatus ?? t.status ?? '—',
    }));

    const kycRows = kyc.slice(0, 4).map((k) => ({
      id: k.kycId ?? k.id, time: k.createdAt ?? k.updatedAt, type: 'KYC', ref: shortId(k.customerId), detail: `${k.kycType ?? 'KYC'} review`, status: k.verificationStatus ?? k.kycVerificationStatus ?? '—',
    }));

    return [...txns, ...kycRows].sort((a, b) => new Date(b.time ?? 0) - new Date(a.time ?? 0)).slice(0, 8);
  }, [transactions, kyc]);

  const handleLogout = () => {
    clearAuthSession();
    if (typeof onSignOut === 'function') onSignOut();
    else navigate('/login', { replace: true });
  };

  return (
    <div className="ad-shell">
      <aside className="ad-sidebar">
        <a className="ad-brand" href="#dashboard" onClick={(e) => e.preventDefault()}>
          <span className="ad-brand-mark">N</span>
          <span className="ad-brand-text">
            <strong>NOVA BANK</strong>
            <small>Your Trust. Our Priority.</small>
          </span>
        </a>

        <div className="ad-user">
          <span className="ad-avatar">{initials(identity.name)}</span>
          <div className="ad-user-info">
            <b>{identity.name}</b>
            <small>Super Admin</small>
            <span className="ad-online"><i />Online</span>
          </div>
        </div>

        <div className="ad-nav-label">Workspace</div>
        <nav className="ad-nav">
          {NAV_ITEMS.map((item) => (
            <button key={item.id} className={activePage === item.id ? 'active' : ''} onClick={() => { setActivePage(item.id); setSelectedBranch(null); }}>
              <span className="ad-nav-icon">{item.icon}</span>
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="ad-sidebar-bottom">
          {/*  Trigger the confirmation modal here */}
          <button className="ad-logout" onClick={() => setShowLogoutModal(true)}>
            <span className="ad-nav-icon">⏻</span>
            <span>Logout</span>
          </button>
          <div className="ad-secure">
            <span className="ad-secure-dot" /> Signed in securely
          </div>
        </div>
      </aside>

      <div className="ad-main">
        <header className="ad-topbar">
          <div className="ad-topbar-left">
            <div className="ad-topbar-title">
              <strong>Super Admin Dashboard</strong>
              <span>Bank-wide operations &amp; oversight</span>
            </div>
          </div>
          
          <div className="ad-topbar-right" style={{ position: 'relative' }}>
            <button className="ad-icon-btn" aria-label="Notifications">
              
              <span className="ad-badge">{stats.pendingKyc + stats.txnsFailed}</span>
            </button>

            <button className="ad-profile" onClick={() => setProfileOpen(!profileOpen)} title="View Profile">
              <span className="ad-avatar-sm">{initials(identity.name)}</span>
              <span className="ad-profile-name">{identity.name}</span>
              <span className="ad-chevron"></span>
            </button>

            {profileOpen && (
              <div className="ad-profile-popover">
                <div className="ad-popover-header">
                  <span className="ad-avatar-lg">{initials(identity.name)}</span>
                  <div><b>{identity.name}</b><small>{identity.email}</small></div>
                </div>
                <div className="ad-popover-body">
                  <div className="ad-popover-row"><span>Role</span><b>{identity.roles[0] || 'ADMIN'}</b></div>
                  <div className="ad-popover-row"><span>Status</span><span className="ad-status ad-status-ok">Active</span></div>
                </div>
                <div className="ad-popover-footer">
                  {/*  Trigger the confirmation modal here too */}
                  <button onClick={() => { setProfileOpen(false); setShowLogoutModal(true); }} className="ad-logout-btn">
                    Logout
                  </button>
                </div>
              </div>
            )}
          </div>
        </header>

        <div className="ad-content">
          {selectedBranch ? (
            <BranchDetailsPage branch={selectedBranch} onBack={() => setSelectedBranch(null)} />
          ) : (
            <>
              {activePage === 'Customers' && <CustomerManagementPage />}
              {activePage === 'Employees' && <EmployeeManagementPage />}
              {activePage === 'Branches' && <BranchManagementPage onViewBranch={(branch) => setSelectedBranch(branch)} />}
              {activePage === 'Accounts' && <AccountManagementPage />}
              {activePage === 'KYC' && <KycManagementPage />}
              {activePage === 'Transactions' && <TransactionManagementPage />}
              {activePage === 'Reports' && <ReportsAnalyticsPage />}
              {activePage === 'Loans' && (
                <BankLoanManagerPage
                  canManageProducts
                  canProcessApplications
                  isBranchManager
                  currentUser={user}
                  onSignOut={onSignOut}
                />
              )}

              {!['Dashboard', 'Customers', 'Employees', 'Branches', 'Accounts', 'KYC', 'Transactions', 'Reports', 'Loans'].includes(activePage) && (
                <div className="ad-panel" style={{ padding: '40px', textAlign: 'center', color: '#7c879a' }}>
                  <h2>{activePage} Module</h2>
                  <p>This section is currently under construction.</p>
                </div>
              )}

              {activePage === 'Dashboard' && (
                <>
                  <div className="ad-welcome">
                    <div>
                      <h1>Welcome back, {identity.name.split(' ')[0]}!</h1>
                      <p>Monitor bank-wide operations, review activity, and oversee customer, branch, and compliance workflows.</p>
                    </div>
                    <div className="ad-welcome-side">
                      <div className="ad-chip">
                        <span className="ad-chip-icon"></span>
                        <div><b>{stats.branches} branches</b><small>{stats.activeBranches} active</small></div>
                      </div>
                      <div className="ad-chip">
                        <span className="ad-chip-icon"></span>
                        <div>
                          <b>{new Intl.DateTimeFormat('en-IN', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }).format(new Date())}</b>
                          <small>{new Intl.DateTimeFormat('en-IN', { hour: '2-digit', minute: '2-digit' }).format(new Date())}</small>
                        </div>
                      </div>
                    </div>
                  </div>

                  {error && (
                    <div className="ad-alert" role="alert">
                      {error}
                      <button onClick={load} disabled={refreshing}>{refreshing ? 'Retrying…' : 'Retry'}</button>
                    </div>
                  )}

                  <section className="ad-kpis">
                    <Kpi icon="" label="Total customers" value={stats.customers} tone="blue" loading={loading} />
                    <Kpi icon="▣" label="Total accounts" value={stats.accounts} tone="violet" loading={loading} />
                    <Kpi icon="" label="Total branches" value={stats.branches} tone="green" loading={loading} />
                    <Kpi icon="" label="Pending KYC" value={stats.pendingKyc} tone="amber" loading={loading} />
                    <Kpi icon="⇄" label="Today's transactions" value={stats.txnsToday} tone="teal" loading={loading} />
                    <Kpi icon="⚠" label="Failed transactions" value={stats.txnsFailed} tone="red" loading={loading} />
                    <Kpi icon="✓" label="Approved KYC" value={stats.approvedKyc} tone="green" loading={loading} />
                    <Kpi icon="◆" label="Active accounts" value={stats.activeAccounts} tone="blue" loading={loading} />
                  </section>

                  <section className="ad-grid">
                    <div className="ad-panel">
                      <div className="ad-panel-head">
                        <div><h2>Recent system activity</h2><p>Latest transactions and KYC events</p></div>
                        <button className="ad-ghost" onClick={() => setActivePage('Transactions')}>View all →</button>
                      </div>

                      <div className="ad-table-wrap">
                        <table className="ad-table">
                          <thead>
                            <tr><th>Time</th><th>Type</th><th>Reference</th><th>Details</th><th>Status</th></tr>
                          </thead>
                          <tbody>
                            {loading ? (
                              <tr><td colSpan="5" className="ad-empty">Loading activity…</td></tr>
                            ) : recentActivity.length === 0 ? (
                              <tr><td colSpan="5" className="ad-empty">No recent activity.</td></tr>
                            ) : (
                              recentActivity.map((row, i) => (
                                <tr key={`${row.id || i}`}>
                                  <td className="ad-cell-time">{formatDate(row.time)} · {formatTime(row.time)}</td>
                                  <td>{row.type}</td>
                                  <td className="ad-cell-ref">{row.ref}</td>
                                  <td>{row.detail}</td>
                                  <td><StatusPill tone={statusTone(row.status)}>{String(row.status).replaceAll('_', ' ')}</StatusPill></td>
                                </tr>
                              ))
                            )}
                          </tbody>
                        </table>
                      </div>
                    </div>

                    <div className="ad-panel">
                      <div className="ad-panel-head">
                        <div><h2>Quick actions</h2><p>Common administrative tasks</p></div>
                      </div>

                      <ul className="ad-actions">
                        <ActionRow icon="" label="Search customers" hint={`${stats.customers} records`} onClick={() => setActivePage('Customers')} />
                        <ActionRow icon="" label="Manage employees" hint="HR & Roles" onClick={() => setActivePage('Employees')} />
                        <ActionRow icon="" label="Manage branches" hint={`${stats.branches} branches`} onClick={() => setActivePage('Branches')} />
                        <ActionRow icon="" label="Review KYC queue" hint={`${stats.pendingKyc} pending`} onClick={() => setActivePage('KYC')} />
                        <ActionRow icon="⇄" label="Monitor transactions" hint={`${stats.txnsTotal} total`} onClick={() => setActivePage('Transactions')} />
                        <ActionRow icon="▣" label="Manage accounts" hint={`${stats.accounts} accounts`} onClick={() => setActivePage('Accounts')} />
                      </ul>
                    </div>
                  </section>

                  <footer className="ad-footer">
                    © 2026 Nova Bank · Super Admin
                    <span>{refreshing ? 'Refreshing…' : 'Live data'}</span>
                  </footer>
                </>
              )}
            </>
          )}
        </div>
      </div>

      {/*  LOGOUT CONFIRMATION MODAL */}
      {showLogoutModal && (
        <div 
          style={{ position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(15, 23, 42, 0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 9999 }}
          onClick={() => setShowLogoutModal(false)}
        >
          <div 
            style={{ background: '#fff', padding: '24px', borderRadius: '12px', width: '100%', maxWidth: '400px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)' }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>Log out of Nova Bank?</h3>
            <p style={{ color: '#64748b', fontSize: '14px', margin: '0 0 24px 0', lineHeight: 1.5 }}>
              Are you sure you want to securely log out of your account? You will need to sign in again to continue.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button onClick={() => setShowLogoutModal(false)} style={{ padding: '8px 16px', background: 'transparent', border: '1px solid #cbd5e1', borderRadius: '6px', cursor: 'pointer', fontWeight: 600, color: '#475569' }}>
                Cancel
              </button>
              <button onClick={handleLogout} style={{ padding: '8px 16px', background: '#e11d48', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600, color: 'white' }}>
                Yes, log out
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function Kpi({ icon, label, value, tone = 'blue', loading }) {
  return (
    <article className={`ad-kpi ad-kpi-${tone}`}>
      <span className="ad-kpi-icon">{icon}</span>
      <div className="ad-kpi-body">
        <span className="ad-kpi-label">{label}</span>
        <strong className="ad-kpi-value">{loading ? '—' : value}</strong>
      </div>
    </article>
  );
}

function StatusPill({ tone = 'neutral', children }) {
  return <span className={`ad-status ad-status-${tone}`}>{children}</span>;
}

function ActionRow({ icon, label, hint, onClick }) {
  return (
    <li>
      <button type="button" className="ad-action" onClick={onClick}>
        <span className="ad-action-icon">{icon}</span>
        <span className="ad-action-text">
          <b>{label}</b>
          <small>{hint}</small>
        </span>
        <span className="ad-action-arrow">›</span>
      </button>
    </li>
  );
}

import { useCallback, useEffect, useMemo, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import branchManagerService from '../../../../services/branchManagerService';
import './BankManagerDashboard.css';
import ChangePasswordModal from '../../../profile/ChangePasswordModal';
import KycApplicationDetail from '../kycOfficer/KycApplicationDetail';

import BranchCustomersPage from './BranchCustomersPage';
import BranchAccountsPage from './BranchAccountsPage';
import BranchTransactionsPage from './BranchTransactionsPage';
import BranchKycPage from './BranchKycPage';
import BranchEmployeesPage from './BranchEmployeesPage';
import BranchReportsPage from './BranchReportsPage';
import BranchSettingsPage from './BranchSettingsPage';
import BankLoanManagerPage from './loan/BankLoanManagerPage'

const { normalizeList } = branchManagerService;

const initials = (name) =>
  String(name || '')
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase() ?? '')
    .join('') || 'BM';

const formatMoney = (v) => {
  if (v == null || v === '') return '—';
  const n = Number(v);
  return Number.isNaN(n)
    ? String(v)
    : new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 0,
      }).format(n);
};

const formatDate = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime())
    ? String(v)
    : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
};

const formatTime = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime())
    ? String(v)
    : d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
};

const statusTone = (status) => {
  const s = String(status || '').toUpperCase();
  if (['SUCCESS', 'COMPLETED', 'APPROVED', 'ACTIVE'].includes(s)) return 'ok';
  if (['PENDING', 'IN_PROGRESS', 'UNDER_REVIEW', 'PROCESSING'].includes(s)) return 'warn';
  if (['FAILED', 'REJECTED', 'CLOSED', 'DECLINED'].includes(s)) return 'bad';
  return 'neutral';
};

const shortId = (id) => (id ? String(id).slice(0, 14) : '—');

const NAV_ITEMS = [
  { label: 'Dashboard', icon: '▦', id: 'Dashboard' },
  { label: 'Customers', icon: '', id: 'Customers' },
  { label: 'Accounts', icon: '▣', id: 'Accounts' },
  { label: 'KYC Oversight', icon: '', id: 'KYC' },
  { label: 'Transactions', icon: '⇄', id: 'Transactions' },
  { label: 'Loans', icon: '', id: 'Loans' },  
  { label: 'Employees', icon: '♧', id: 'Employees' },
  { label: 'Reports', icon: '▤', id: 'Reports' },
  { label: 'Settings', icon: '⚙', id: 'Settings' },
];

/* =========================================================
   Inline Modal Components (To avoid creating extra files)
   ========================================================= */

function DetailBlock({ label, value }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
      <span
        style={{
          fontSize: '10px',
          color: '#64748b',
          fontWeight: 700,
          textTransform: 'uppercase',
          letterSpacing: '0.5px',
        }}
      >
        {label}
      </span>
      <span style={{ fontSize: '13px', color: '#0f172a', fontWeight: 600, wordBreak: 'break-word' }}>
        {value}
      </span>
    </div>
  );
}

function TransactionModal({ transaction, onClose }) {
  if (!transaction) return null;
  return (
    <div className="kyc-modal-backdrop" onClick={onClose}>
      <div
        className="kyc-modal"
        onClick={(e) => e.stopPropagation()}
        style={{
          maxWidth: '720px',
          width: '100%',
          padding: '0',
          overflow: 'hidden',
          borderRadius: '14px',
        }}
      >
        <div
          style={{
            padding: '20px 24px',
            borderBottom: '1px solid #e2e8f0',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: '#f8fafc',
          }}
        >
          <div>
            <h2 style={{ margin: 0, fontSize: '16px', fontWeight: 800, color: '#0f172a' }}>
              {transaction.transactionType} Transaction
            </h2>
            <p style={{ margin: '4px 0 0', fontSize: '12px', color: '#64748b', fontWeight: 500 }}>
              ID: {transaction.transactionId}
            </p>
          </div>
          <button
            onClick={onClose}
            style={{
              background: '#fff',
              border: '1px solid #e2e8f0',
              borderRadius: '50%',
              width: '32px',
              height: '32px',
              display: 'grid',
              placeItems: 'center',
              cursor: 'pointer',
              boxShadow: '0 1px 2px rgba(0,0,0,0.05)',
            }}
          >
            ✕
          </button>
        </div>
        <div style={{ padding: '24px' }}>
          <div style={{ textAlign: 'center', marginBottom: '24px' }}>
            <div style={{ fontSize: '28px', fontWeight: 800, color: '#158456', letterSpacing: '-1px' }}>
              {formatMoney(transaction.amount)}
            </div>
            <span
              className={`bm-status bm-status-${statusTone(transaction.transactionStatus)}`}
              style={{
                marginTop: '8px',
                fontSize: '11px',
                padding: '4px 12px',
                borderRadius: '20px',
                textTransform: 'uppercase',
                display: 'inline-block',
              }}
            >
              {transaction.transactionStatus}
            </span>
          </div>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, 1fr)',
              gap: '16px',
              background: '#f8fafc',
              padding: '20px',
              borderRadius: '12px',
              border: '1px solid #e2e8f0',
            }}
          >
            <DetailBlock label="Transaction Type" value={transaction.transactionType} />
            <DetailBlock label="Reference ID" value={transaction.reference || '—'} />
            <DetailBlock label="Description" value={transaction.description || '—'} />
            <div
              style={{
                gridColumn: '1 / -1',
                borderTop: '1px dashed #cbd5e1',
                margin: '4px 0',
              }}
            />
            {transaction.fromAccountNumber && (
              <DetailBlock label="From Account" value={transaction.fromAccountNumber} />
            )}
            {transaction.toAccountNumber && (
              <DetailBlock label="To Account" value={transaction.toAccountNumber} />
            )}
            {transaction.accountNumber && (
              <DetailBlock label="Account" value={transaction.accountNumber} />
            )}
            <DetailBlock label="Customer ID" value={transaction.customerId || '—'} />
            <div
              style={{
                gridColumn: '1 / -1',
                borderTop: '1px dashed #cbd5e1',
                margin: '4px 0',
              }}
            />
            <DetailBlock
              label="Created At"
              value={`${formatDate(transaction.createdAt)} · ${formatTime(transaction.createdAt)}`}
            />
            <DetailBlock
              label="Performed By"
              value={
                transaction.performedBy
                  ? `${transaction.performedBy} (${transaction.performedByRole})`
                  : 'System'
              }
            />
          </div>
        </div>
        <div style={{ padding: '0 24px 24px 24px' }}>
          <button
            type="button"
            className="bt-btn-secondary"
            onClick={onClose}
            style={{ width: '100%', padding: '12px', fontSize: '13px', fontWeight: 700 }}
          >
            Close Details
          </button>
        </div>
      </div>
    </div>
  );
}

/* =========================================================
   Main Dashboard Component
   ========================================================= */

export default function BankManagerDashboardPage({ user, onSignOut }) {
  const navigate = useNavigate();
  const [activePage, setActivePage] = useState('Dashboard');

  const [branch, setBranch] = useState(null);
  const [customers, setCustomers] = useState([]);
  const [accounts, setAccounts] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [kyc, setKyc] = useState([]);
  const [employees, setEmployees] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [showIdleWarning, setShowIdleWarning] = useState(false);
  const [idleCountdown, setIdleCountdown] = useState(60);

  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  // State for Dashboard Modals
  const [selectedTx, setSelectedTx] = useState(null);
  const [selectedKycId, setSelectedKycId] = useState(null); // Stores ID to open the full page

  const identity = useMemo(() => {
    const fromService = branchManagerService.getManagerIdentity?.();
    if (fromService && (fromService.name || fromService.email)) return fromService;
    return { name: user?.name || user?.fullName || 'Branch Manager', email: user?.email || '' };
  }, [user]);

  const idleTimerRef = useRef(null);
  const countdownTimerRef = useRef(null);
  const profileMenuRef = useRef(null);

  const load = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    setError('');

    const tasks = [
      {
        label: 'Branch',
        run: () => branchManagerService.getMyBranch(),
        apply: (v) => setBranch(v?.data ?? v ?? null),
      },
      {
        label: 'Customers',
        run: () => branchManagerService.getCustomers({ page: 0, size: 100 }),
        apply: (v) => setCustomers(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Accounts',
        run: () => branchManagerService.getAccounts({ page: 0, size: 100 }),
        apply: (v) => setAccounts(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Transactions',
        run: () => branchManagerService.getTransactions({ page: 0, size: 100 }),
        apply: (v) => setTransactions(normalizeList(v?.data ?? v)),
      },
      {
        label: 'KYC',
        run: () => branchManagerService.getKycRequests(),
        apply: (v) => setKyc(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Employees',
        run: () => branchManagerService.getBranchEmployees(),
        apply: (v) => setEmployees(normalizeList(v?.data ?? v)),
      },
    ];

    const results = await Promise.allSettled(tasks.map((t) => t.run()));
    const failures = [];
    results.forEach((r, i) => {
      if (r.status === 'fulfilled') tasks[i].apply(r.value);
      else failures.push(`${tasks[i].label}: ${r.reason?.message || 'failed'}`);
    });

    if (failures.length === tasks.length)
      setError(`Could not load any data. ${failures.join(' · ')}`);
    else if (failures.length) setError(`Some sections failed: ${failures.join(' · ')}`);

    setLoading(false);
    setRefreshing(false);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (profileMenuRef.current && !profileMenuRef.current.contains(event.target)) {
        setShowProfileMenu(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const IDLE_TIME = 10 * 60 * 1000;

    const resetTimer = () => {
      if (showIdleWarning) return;
      clearTimeout(idleTimerRef.current);
      idleTimerRef.current = setTimeout(() => {
        setShowIdleWarning(true);
        startCountdown();
      }, IDLE_TIME);
    };

    const startCountdown = () => {
      setIdleCountdown(60);
      countdownTimerRef.current = setInterval(() => {
        setIdleCountdown((prev) => {
          if (prev <= 1) {
            clearInterval(countdownTimerRef.current);
            if (typeof onSignOut === 'function') onSignOut();
            else navigate('/login', { replace: true });
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    };

    const handleActivity = () => resetTimer();
    const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];
    events.forEach((e) => window.addEventListener(e, handleActivity));
    resetTimer();

    return () => {
      events.forEach((e) => window.removeEventListener(e, handleActivity));
      clearTimeout(idleTimerRef.current);
      clearInterval(countdownTimerRef.current);
    };
  }, [navigate, onSignOut, showIdleWarning]);

  const handleStayActive = () => {
    setShowIdleWarning(false);
    setIdleCountdown(60);
    clearInterval(countdownTimerRef.current);
  };

  const stats = useMemo(() => {
    const activeAccounts = accounts.filter(
      (a) => String(a.accountStatus || a.status || '').toUpperCase() === 'ACTIVE'
    ).length;
    const pendingKyc = kyc.filter((k) =>
      ['PENDING', 'UNDER_REVIEW'].includes(
        String(k.verificationStatus || k.kycVerificationStatus || '').toUpperCase()
      )
    ).length;
    const today = new Date().toDateString();
    const todayTxns = transactions.filter(
      (t) => new Date(t.createdAt || t.transactionDate).toDateString() === today
    ).length;

    return {
      customers: customers.length,
      accounts: activeAccounts || accounts.length,
      pendingKyc,
      todayTxns,
      totalEmployees: employees.length,
    };
  }, [customers, accounts, kyc, transactions, employees]);

  const recentActivity = useMemo(() => {
    const txnRows = transactions.slice(0, 8).map((t) => ({
      id: t.transactionId ?? t.id,
      time: t.createdAt ?? t.transactionDate,
      type: t.transactionType ?? t.type ?? 'Transaction',
      ref: t.accountNumber ?? t.fromAccountNumber ?? t.toAccountNumber ?? '—',
      detail: t.description ?? `${formatMoney(t.amount)}`,
      status: t.transactionStatus ?? t.status ?? '—',
      isKyc: false,
      originalData: t,
    }));

    const kycRows = kyc.slice(0, 4).map((k) => ({
      id: k.kycId ?? k.id,
      time: k.createdAt ?? k.updatedAt,
      type: 'KYC',
      ref: shortId(k.customerId),
      detail: `${k.kycType ?? 'KYC'} review`,
      status: k.verificationStatus ?? k.kycVerificationStatus ?? '—',
      isKyc: true,
      originalData: k,
    }));

    return [...txnRows, ...kycRows]
      .sort((a, b) => new Date(b.time ?? 0) - new Date(a.time ?? 0))
      .slice(0, 8);
  }, [transactions, kyc]);

  const confirmLogout = () => {
    setShowLogoutModal(false);
    if (typeof onSignOut === 'function') onSignOut();
    else navigate('/login', { replace: true });
  };

  // Helper to handle sidebar navigation and clear KYC view
  const handleNavClick = (pageId) => {
    setActivePage(pageId);
    setSelectedKycId(null);
  };

  return (
    <div className="bm-shell">
      <aside className="bm-sidebar">
        <a className="bm-brand" href="#dashboard" onClick={(e) => e.preventDefault()}>
          <span className="bm-brand-mark">N</span>
          <span className="bm-brand-text">
            <strong>NOVA BANK</strong>
            <small>Your Trust. Our Priority.</small>
          </span>
        </a>

        <div className="bm-user">
          <span className="bm-avatar">{initials(identity.name)}</span>
          <div className="bm-user-info">
            <b>{identity.name}</b>
            <small>Branch Manager</small>
            <span className="bm-online">
              <i />
              Online
            </span>
          </div>
        </div>

        <div className="bm-nav-label">Workspace</div>
        <nav className="bm-nav">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              className={activePage === item.id && !selectedKycId ? 'active' : ''}
              onClick={() => handleNavClick(item.id)}
            >
              <span className="bm-nav-icon">{item.icon}</span>
              <span className="bm-nav-label-text">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="bm-sidebar-bottom">
          <button className="bm-logout" onClick={() => setShowLogoutModal(true)}>
            <span className="bm-nav-icon">⏻</span>
            <span>Logout</span>
          </button>
          <div className="bm-secure">
            <span className="bm-secure-dot" />
            Signed in securely
          </div>
        </div>
      </aside>

      <div className="bm-main">
        <header className="bm-topbar">
          <div className="bm-topbar-left">
            <div className="bm-topbar-title">
              <strong>Branch Manager Dashboard</strong>
              <span>Branch operations &amp; team management</span>
            </div>
          </div>
          <div className="bm-topbar-right">
            <button className="bm-icon-btn" aria-label="Notifications">
              <span className="bm-badge">{stats.pendingKyc}</span>
            </button>

            <div style={{ position: 'relative' }} ref={profileMenuRef}>
              <button
                className="bm-profile"
                onClick={() => setShowProfileMenu(!showProfileMenu)}
                style={{ cursor: 'pointer' }}
              >
                <span className="bm-avatar-sm">{initials(identity.name)}</span>
                <span className="bm-profile-name">{identity.name}</span>
              </button>

              {showProfileMenu && (
                <div
                  style={{
                    position: 'absolute',
                    top: '100%',
                    right: 0,
                    marginTop: '8px',
                    background: '#fff',
                    border: '1px solid #e2e8f0',
                    borderRadius: '8px',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                    minWidth: '200px',
                    zIndex: 50,
                    overflow: 'hidden',
                  }}
                >
                  <button
                    onClick={() => {
                      setShowProfileMenu(false);
                      navigate('/profile');
                    }}
                    style={{
                      width: '100%',
                      textAlign: 'left',
                      padding: '12px 16px',
                      background: 'transparent',
                      border: 'none',
                      borderBottom: '1px solid #f1f5f9',
                      cursor: 'pointer',
                      fontSize: '13px',
                      color: '#1e293b',
                    }}
                  >
                     View Profile
                  </button>
                  <button
                    onClick={() => {
                      setShowProfileMenu(false);
                      setShowPasswordModal(true);
                    }}
                    style={{
                      width: '100%',
                      textAlign: 'left',
                      padding: '12px 16px',
                      background: 'transparent',
                      border: 'none',
                      cursor: 'pointer',
                      fontSize: '13px',
                      color: '#1e293b',
                    }}
                  >
                     Change Password
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="bm-content">

          {/* IF A KYC ID IS SELECTED, SHOW THE KYC DETAIL PAGE INSIDE THE MAIN CONTENT */}
          {selectedKycId ? (
             <div style={{ background: '#fff', borderRadius: '14px', border: '1px solid #e1e7f0', padding: '20px', minHeight: '500px' }}>
                <KycApplicationDetail
                  kycId={selectedKycId}
                  onBack={() => setSelectedKycId(null)}
                  onUpdate={load}
                />
             </div>
          ) : (
            /* OTHERWISE, SHOW THE NORMAL DASHBOARD PAGES */
            <>
              {activePage === 'Customers' && (
                <BranchCustomersPage customers={customers} loading={loading} />
              )}
              {activePage === 'Accounts' && (
                <BranchAccountsPage
                  accounts={accounts}
                  customers={customers}
                  loading={loading}
                  onRefresh={load}
                />
              )}
              {activePage === 'Transactions' && (
                <BranchTransactionsPage
                  transactions={transactions}
                  loading={loading}
                  onRefresh={load}
                />
              )}
              {activePage === 'KYC' && (
                <BranchKycPage kycList={kyc} loading={loading} onRefresh={load} />
              )}
              {activePage === 'Loans' && (
               <BankLoanManagerPage
                 onBack={() => setActivePage('Dashboard')}
                 isBranchManager
               />
              )}

              {activePage === 'Employees' && (
                <BranchEmployeesPage
                  employees={employees}
                  loading={loading}
                  onRefresh={() => load(true)}
                  currentBranchId={branch?.branchCode}
                />
              )}

              {activePage === 'Reports' && (
                <BranchReportsPage
                  accounts={accounts}
                  transactions={transactions}
                  customers={customers}
                />
              )}
              {activePage === 'Settings' && (
                <BranchSettingsPage branch={branch} identity={identity} />
              )}

              {activePage === 'Dashboard' && (
                <>
                  <div className="bm-welcome">
                    <div>
                      <h1>Welcome back, {identity.name.split(' ')[0] || 'Manager'}!</h1>
                      <p>
                        Manage your branch operations, monitor customers, and keep the team on track.
                      </p>
                    </div>
                    <div className="bm-welcome-side">
                      <div className="bm-branch-chip">
                        <span className="bm-branch-icon"></span>
                        <div>
                          <b>{branch?.branchName || 'Assigned branch'}</b>
                          <small>
                            {branch?.branchCode
                              ? `Branch Code · ${branch.branchCode}`
                              : 'Branch Code · —'}
                            {branch?.city ? ` · ${branch.city}` : ''}
                          </small>
                        </div>
                      </div>
                      <div className="bm-date-chip">
                        <span></span>
                        <div>
                          <b>
                            {new Intl.DateTimeFormat('en-IN', {
                              weekday: 'short',
                              day: '2-digit',
                              month: 'short',
                              year: 'numeric',
                            }).format(new Date())}
                          </b>
                          <small>
                            {new Intl.DateTimeFormat('en-IN', {
                              hour: '2-digit',
                              minute: '2-digit',
                            }).format(new Date())}
                          </small>
                        </div>
                      </div>
                    </div>
                  </div>

                  {error && (
                    <div className="bm-alert" role="alert">
                      {error}
                      <button onClick={load} disabled={refreshing}>
                        {refreshing ? 'Retrying…' : 'Retry'}
                      </button>
                    </div>
                  )}

                  <section
                    className="bm-kpis"
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
                      gap: '16px',
                      marginBottom: '24px',
                    }}
                  >
                    <KpiCard icon="" label="Total customers" value={stats.customers} tone="blue" loading={loading} />
                    <KpiCard icon="▣" label="Active accounts" value={stats.accounts} tone="violet" loading={loading} />
                    <KpiCard icon="" label="Pending KYC" value={stats.pendingKyc} tone="amber" loading={loading} />
                    <KpiCard icon="⇄" label="Today's transactions" value={stats.todayTxns} tone="green" loading={loading} />
                    <KpiCard icon="" label="Total employees" value={stats.totalEmployees} tone="blue" loading={loading} />
                  </section>

                  <section
                    className="bm-grid"
                    style={{
                      display: 'grid',
                      gridTemplateColumns: '1fr',
                      gap: '24px',
                      alignItems: 'start',
                    }}
                  >
                    <div className="bm-panel" style={{ overflow: 'visible' }}>
                      <div className="bm-panel-head">
                        <div>
                          <h2>Recent branch activity</h2>
                          <p>Latest transactions and KYC actions</p>
                        </div>
                        <button className="bm-ghost" onClick={() => setActivePage('Transactions')}>
                          View all →
                        </button>
                      </div>
                      <div className="bm-table-wrap" style={{ overflowX: 'auto' }}>
                        <table className="bm-table" style={{ width: '100%', tableLayout: 'auto' }}>
                          <thead>
                            <tr>
                              <th style={{ width: '20%' }}>Time</th>
                              <th style={{ width: '15%' }}>Type</th>
                              <th style={{ width: '25%' }}>Reference</th>
                              <th style={{ width: '25%' }}>Details</th>
                              <th style={{ width: '15%' }}>Status</th>
                            </tr>
                          </thead>
                          <tbody>
                            {loading ? (
                              <tr>
                                <td colSpan="5" className="bm-empty">
                                  Loading activity…
                                </td>
                              </tr>
                            ) : recentActivity.length === 0 ? (
                              <tr>
                                <td colSpan="5" className="bm-empty">
                                  No recent activity.
                                </td>
                              </tr>
                            ) : (
                              recentActivity.map((row, i) => (
                                <tr
                                  key={`${row.id || i}`}
                                  onClick={() => {
                                    if (row.isKyc) {
                                      setSelectedKycId(row.id);
                                    } else {
                                      setSelectedTx(row.originalData);
                                    }
                                  }}
                                  style={{ cursor: 'pointer' }}
                                  className="bm-row-hover"
                                >
                                  <td className="bm-cell-time">
                                    {formatDate(row.time)} · {formatTime(row.time)}
                                  </td>
                                  <td>{row.type}</td>
                                  <td className="bm-cell-ref">{row.ref}</td>
                                  <td>{row.detail}</td>
                                  <td>
                                    <StatusPill tone={statusTone(row.status)}>
                                      {String(row.status).replaceAll('_', ' ')}
                                    </StatusPill>
                                  </td>
                                </tr>
                              ))
                            )}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>

                  <footer className="bm-footer">
                    © 2026 Nova Bank · Branch Operations
                    <span>{refreshing ? 'Refreshing…' : 'Live data'}</span>
                  </footer>
                </>
              )}
            </>
          )}
        </div>
      </div>

      {showLogoutModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 9999,
          }}
          onClick={() => setShowLogoutModal(false)}
        >
          <div
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '12px',
              width: '100%',
              maxWidth: '400px',
              boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>
              Log out of Nova Bank?
            </h3>
            <p
              style={{
                color: '#64748b',
                fontSize: '14px',
                margin: '0 0 24px 0',
                lineHeight: 1.5,
              }}
            >
              Are you sure you want to securely log out of your account? You will need to sign
              in again to continue.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button
                onClick={() => setShowLogoutModal(false)}
                style={{
                  padding: '8px 16px',
                  background: 'transparent',
                  border: '1px solid #cbd5e1',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600,
                  color: '#475569',
                }}
              >
                Cancel
              </button>
              <button
                onClick={confirmLogout}
                style={{
                  padding: '8px 16px',
                  background: '#e11d48',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600,
                  color: 'white',
                }}
              >
                Yes, log out
              </button>
            </div>
          </div>
        </div>
      )}

      {showIdleWarning && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10000,
          }}
        >
          <div
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '12px',
              width: '100%',
              maxWidth: '400px',
              textAlign: 'center',
              boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
            }}
          >
            <div style={{ fontSize: '40px', marginBottom: '16px' }}>⏳</div>
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>
              Are you still there?
            </h3>
            <p
              style={{
                color: '#64748b',
                fontSize: '14px',
                margin: '0 0 24px 0',
                lineHeight: 1.5,
              }}
            >
              For your security, you will be logged out automatically in{' '}
              <b>{idleCountdown}</b> seconds due to inactivity.
            </p>
            <button
              onClick={handleStayActive}
              style={{
                width: '100%',
                padding: '12px',
                background: '#1769e0',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: 600,
                fontSize: '14px',
              }}
            >
              I'm still here, continue session
            </button>
          </div>
        </div>
      )}

      {showPasswordModal && (
        <ChangePasswordModal onClose={() => setShowPasswordModal(false)} />
      )}

      {selectedTx && (
        <TransactionModal transaction={selectedTx} onClose={() => setSelectedTx(null)} />
      )}
    </div>
  );
}

/* =========================================================
   Small Presentational Helpers
   ========================================================= */

function KpiCard({ icon, label, value, tone = 'blue', loading }) {
  return (
    <article className={`bm-kpi bm-kpi-${tone}`}>
      <span className="bm-kpi-icon">{icon}</span>
      <div className="bm-kpi-body">
        <span className="bm-kpi-label" style={{ fontSize: '12px' }}>
          {label}
        </span>
        <strong className="bm-kpi-value" style={{ fontSize: '20px' }}>
          {loading ? '—' : value}
        </strong>
      </div>
    </article>
  );
}

function StatusPill({ tone = 'neutral', children }) {
  return <span className={`bm-status bm-status-${tone}`}>{children}</span>;
}

function EmptyState({ icon = '', title = 'Nothing here yet', message = '' }) {
  return (
    <div style={{ padding: '48px 24px', textAlign: 'center', color: '#64748b' }}>
      <div style={{ fontSize: '40px', marginBottom: '12px' }}>{icon}</div>
      <h3 style={{ margin: '0 0 6px', fontSize: '15px', color: '#0f172a' }}>{title}</h3>
      {message && <p style={{ margin: 0, fontSize: '13px' }}>{message}</p>}
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import branchManagerService from '../../../../services/branchManagerService';
import './BankManagerDashboard.css';
import ChangePasswordModal from '../../../profile/ChangePasswordModal';
import KycApplicationDetail from '../kycOfficer/KycApplicationDetail';

import BranchCustomersPage from './BranchCustomersPage';
import BranchAccountsPage from './BranchAccountsPage';
import BranchTransactionsPage from './BranchTransactionsPage';
import BranchKycPage from './BranchKycPage';
import BranchEmployeesPage from './BranchEmployeesPage';
import BranchReportsPage from './BranchReportsPage';
import BranchSettingsPage from './BranchSettingsPage';
import BankLoanManagerPage from './loan/BankLoanManagerPage'

const { normalizeList } = branchManagerService;

const initials = (name) =>
  String(name || '')
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase() ?? '')
    .join('') || 'BM';

const formatMoney = (v) => {
  if (v == null || v === '') return '—';
  const n = Number(v);
  return Number.isNaN(n)
    ? String(v)
    : new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 0,
      }).format(n);
};

const formatDate = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime())
    ? String(v)
    : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
};

const formatTime = (v) => {
  if (!v) return '—';
  const d = new Date(v);
  return Number.isNaN(d.getTime())
    ? String(v)
    : d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' });
};

const statusTone = (status) => {
  const s = String(status || '').toUpperCase();
  if (['SUCCESS', 'COMPLETED', 'APPROVED', 'ACTIVE'].includes(s)) return 'ok';
  if (['PENDING', 'IN_PROGRESS', 'UNDER_REVIEW', 'PROCESSING'].includes(s)) return 'warn';
  if (['FAILED', 'REJECTED', 'CLOSED', 'DECLINED'].includes(s)) return 'bad';
  return 'neutral';
};

const shortId = (id) => (id ? String(id).slice(0, 14) : '—');

const NAV_ITEMS = [
  { label: 'Dashboard', icon: '▦', id: 'Dashboard' },
  { label: 'Customers', icon: '', id: 'Customers' },
  { label: 'Accounts', icon: '▣', id: 'Accounts' },
  { label: 'KYC Oversight', icon: '', id: 'KYC' },
  { label: 'Transactions', icon: '⇄', id: 'Transactions' },
  { label: 'Loans', icon: '', id: 'Loans' },  
  { label: 'Employees', icon: '♧', id: 'Employees' },
  { label: 'Reports', icon: '▤', id: 'Reports' },
  { label: 'Settings', icon: '⚙', id: 'Settings' },
];

/* =========================================================
   Inline Modal Components (To avoid creating extra files)
   ========================================================= */

function DetailBlock({ label, value }) {
  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
      <span
        style={{
          fontSize: '10px',
          color: '#64748b',
          fontWeight: 700,
          textTransform: 'uppercase',
          letterSpacing: '0.5px',
        }}
      >
        {label}
      </span>
      <span style={{ fontSize: '13px', color: '#0f172a', fontWeight: 600, wordBreak: 'break-word' }}>
        {value}
      </span>
    </div>
  );
}

function TransactionModal({ transaction, onClose }) {
  if (!transaction) return null;
  return (
    <div className="kyc-modal-backdrop" onClick={onClose}>
      <div
        className="kyc-modal"
        onClick={(e) => e.stopPropagation()}
        style={{
          maxWidth: '720px',
          width: '100%',
          padding: '0',
          overflow: 'hidden',
          borderRadius: '14px',
        }}
      >
        <div
          style={{
            padding: '20px 24px',
            borderBottom: '1px solid #e2e8f0',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: '#f8fafc',
          }}
        >
          <div>
            <h2 style={{ margin: 0, fontSize: '16px', fontWeight: 800, color: '#0f172a' }}>
              {transaction.transactionType} Transaction
            </h2>
            <p style={{ margin: '4px 0 0', fontSize: '12px', color: '#64748b', fontWeight: 500 }}>
              ID: {transaction.transactionId}
            </p>
          </div>
          <button
            onClick={onClose}
            style={{
              background: '#fff',
              border: '1px solid #e2e8f0',
              borderRadius: '50%',
              width: '32px',
              height: '32px',
              display: 'grid',
              placeItems: 'center',
              cursor: 'pointer',
              boxShadow: '0 1px 2px rgba(0,0,0,0.05)',
            }}
          >
            ✕
          </button>
        </div>
        <div style={{ padding: '24px' }}>
          <div style={{ textAlign: 'center', marginBottom: '24px' }}>
            <div style={{ fontSize: '28px', fontWeight: 800, color: '#158456', letterSpacing: '-1px' }}>
              {formatMoney(transaction.amount)}
            </div>
            <span
              className={`bm-status bm-status-${statusTone(transaction.transactionStatus)}`}
              style={{
                marginTop: '8px',
                fontSize: '11px',
                padding: '4px 12px',
                borderRadius: '20px',
                textTransform: 'uppercase',
                display: 'inline-block',
              }}
            >
              {transaction.transactionStatus}
            </span>
          </div>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, 1fr)',
              gap: '16px',
              background: '#f8fafc',
              padding: '20px',
              borderRadius: '12px',
              border: '1px solid #e2e8f0',
            }}
          >
            <DetailBlock label="Transaction Type" value={transaction.transactionType} />
            <DetailBlock label="Reference ID" value={transaction.reference || '—'} />
            <DetailBlock label="Description" value={transaction.description || '—'} />
            <div
              style={{
                gridColumn: '1 / -1',
                borderTop: '1px dashed #cbd5e1',
                margin: '4px 0',
              }}
            />
            {transaction.fromAccountNumber && (
              <DetailBlock label="From Account" value={transaction.fromAccountNumber} />
            )}
            {transaction.toAccountNumber && (
              <DetailBlock label="To Account" value={transaction.toAccountNumber} />
            )}
            {transaction.accountNumber && (
              <DetailBlock label="Account" value={transaction.accountNumber} />
            )}
            <DetailBlock label="Customer ID" value={transaction.customerId || '—'} />
            <div
              style={{
                gridColumn: '1 / -1',
                borderTop: '1px dashed #cbd5e1',
                margin: '4px 0',
              }}
            />
            <DetailBlock
              label="Created At"
              value={`${formatDate(transaction.createdAt)} · ${formatTime(transaction.createdAt)}`}
            />
            <DetailBlock
              label="Performed By"
              value={
                transaction.performedBy
                  ? `${transaction.performedBy} (${transaction.performedByRole})`
                  : 'System'
              }
            />
          </div>
        </div>
        <div style={{ padding: '0 24px 24px 24px' }}>
          <button
            type="button"
            className="bt-btn-secondary"
            onClick={onClose}
            style={{ width: '100%', padding: '12px', fontSize: '13px', fontWeight: 700 }}
          >
            Close Details
          </button>
        </div>
      </div>
    </div>
  );
}

/* =========================================================
   Main Dashboard Component
   ========================================================= */

export default function BankManagerDashboardPage({ user, onSignOut }) {
  const navigate = useNavigate();
  const [activePage, setActivePage] = useState('Dashboard');

  const [branch, setBranch] = useState(null);
  const [customers, setCustomers] = useState([]);
  const [accounts, setAccounts] = useState([]);
  const [transactions, setTransactions] = useState([]);
  const [kyc, setKyc] = useState([]);
  const [employees, setEmployees] = useState([]);

  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');

  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [showIdleWarning, setShowIdleWarning] = useState(false);
  const [idleCountdown, setIdleCountdown] = useState(60);

  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  // State for Dashboard Modals
  const [selectedTx, setSelectedTx] = useState(null);
  const [selectedKycId, setSelectedKycId] = useState(null); // Stores ID to open the full page

  const identity = useMemo(() => {
    const fromService = branchManagerService.getManagerIdentity?.();
    if (fromService && (fromService.name || fromService.email)) return fromService;
    return { name: user?.name || user?.fullName || 'Branch Manager', email: user?.email || '' };
  }, [user]);

  const idleTimerRef = useRef(null);
  const countdownTimerRef = useRef(null);
  const profileMenuRef = useRef(null);

  const load = useCallback(async (isRefresh = false) => {
    isRefresh ? setRefreshing(true) : setLoading(true);
    setError('');

    const tasks = [
      {
        label: 'Branch',
        run: () => branchManagerService.getMyBranch(),
        apply: (v) => setBranch(v?.data ?? v ?? null),
      },
      {
        label: 'Customers',
        run: () => branchManagerService.getCustomers({ page: 0, size: 100 }),
        apply: (v) => setCustomers(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Accounts',
        run: () => branchManagerService.getAccounts({ page: 0, size: 100 }),
        apply: (v) => setAccounts(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Transactions',
        run: () => branchManagerService.getTransactions({ page: 0, size: 100 }),
        apply: (v) => setTransactions(normalizeList(v?.data ?? v)),
      },
      {
        label: 'KYC',
        run: () => branchManagerService.getKycRequests(),
        apply: (v) => setKyc(normalizeList(v?.data ?? v)),
      },
      {
        label: 'Employees',
        run: () => branchManagerService.getBranchEmployees(),
        apply: (v) => setEmployees(normalizeList(v?.data ?? v)),
      },
    ];

    const results = await Promise.allSettled(tasks.map((t) => t.run()));
    const failures = [];
    results.forEach((r, i) => {
      if (r.status === 'fulfilled') tasks[i].apply(r.value);
      else failures.push(`${tasks[i].label}: ${r.reason?.message || 'failed'}`);
    });

    if (failures.length === tasks.length)
      setError(`Could not load any data. ${failures.join(' · ')}`);
    else if (failures.length) setError(`Some sections failed: ${failures.join(' · ')}`);

    setLoading(false);
    setRefreshing(false);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  useEffect(() => {
    function handleClickOutside(event) {
      if (profileMenuRef.current && !profileMenuRef.current.contains(event.target)) {
        setShowProfileMenu(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const IDLE_TIME = 10 * 60 * 1000;

    const resetTimer = () => {
      if (showIdleWarning) return;
      clearTimeout(idleTimerRef.current);
      idleTimerRef.current = setTimeout(() => {
        setShowIdleWarning(true);
        startCountdown();
      }, IDLE_TIME);
    };

    const startCountdown = () => {
      setIdleCountdown(60);
      countdownTimerRef.current = setInterval(() => {
        setIdleCountdown((prev) => {
          if (prev <= 1) {
            clearInterval(countdownTimerRef.current);
            if (typeof onSignOut === 'function') onSignOut();
            else navigate('/login', { replace: true });
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    };

    const handleActivity = () => resetTimer();
    const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];
    events.forEach((e) => window.addEventListener(e, handleActivity));
    resetTimer();

    return () => {
      events.forEach((e) => window.removeEventListener(e, handleActivity));
      clearTimeout(idleTimerRef.current);
      clearInterval(countdownTimerRef.current);
    };
  }, [navigate, onSignOut, showIdleWarning]);

  const handleStayActive = () => {
    setShowIdleWarning(false);
    setIdleCountdown(60);
    clearInterval(countdownTimerRef.current);
  };

  const stats = useMemo(() => {
    const activeAccounts = accounts.filter(
      (a) => String(a.accountStatus || a.status || '').toUpperCase() === 'ACTIVE'
    ).length;
    const pendingKyc = kyc.filter((k) =>
      ['PENDING', 'UNDER_REVIEW'].includes(
        String(k.verificationStatus || k.kycVerificationStatus || '').toUpperCase()
      )
    ).length;
    const today = new Date().toDateString();
    const todayTxns = transactions.filter(
      (t) => new Date(t.createdAt || t.transactionDate).toDateString() === today
    ).length;

    return {
      customers: customers.length,
      accounts: activeAccounts || accounts.length,
      pendingKyc,
      todayTxns,
      totalEmployees: employees.length,
    };
  }, [customers, accounts, kyc, transactions, employees]);

  const recentActivity = useMemo(() => {
    const txnRows = transactions.slice(0, 8).map((t) => ({
      id: t.transactionId ?? t.id,
      time: t.createdAt ?? t.transactionDate,
      type: t.transactionType ?? t.type ?? 'Transaction',
      ref: t.accountNumber ?? t.fromAccountNumber ?? t.toAccountNumber ?? '—',
      detail: t.description ?? `${formatMoney(t.amount)}`,
      status: t.transactionStatus ?? t.status ?? '—',
      isKyc: false,
      originalData: t,
    }));

    const kycRows = kyc.slice(0, 4).map((k) => ({
      id: k.kycId ?? k.id,
      time: k.createdAt ?? k.updatedAt,
      type: 'KYC',
      ref: shortId(k.customerId),
      detail: `${k.kycType ?? 'KYC'} review`,
      status: k.verificationStatus ?? k.kycVerificationStatus ?? '—',
      isKyc: true,
      originalData: k,
    }));

    return [...txnRows, ...kycRows]
      .sort((a, b) => new Date(b.time ?? 0) - new Date(a.time ?? 0))
      .slice(0, 8);
  }, [transactions, kyc]);

  const confirmLogout = () => {
    setShowLogoutModal(false);
    if (typeof onSignOut === 'function') onSignOut();
    else navigate('/login', { replace: true });
  };

  // Helper to handle sidebar navigation and clear KYC view
  const handleNavClick = (pageId) => {
    setActivePage(pageId);
    setSelectedKycId(null);
  };

  return (
    <div className="bm-shell">
      <aside className="bm-sidebar">
        <a className="bm-brand" href="#dashboard" onClick={(e) => e.preventDefault()}>
          <span className="bm-brand-mark">N</span>
          <span className="bm-brand-text">
            <strong>NOVA BANK</strong>
            <small>Your Trust. Our Priority.</small>
          </span>
        </a>

        <div className="bm-user">
          <span className="bm-avatar">{initials(identity.name)}</span>
          <div className="bm-user-info">
            <b>{identity.name}</b>
            <small>Branch Manager</small>
            <span className="bm-online">
              <i />
              Online
            </span>
          </div>
        </div>

        <div className="bm-nav-label">Workspace</div>
        <nav className="bm-nav">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.id}
              className={activePage === item.id && !selectedKycId ? 'active' : ''}
              onClick={() => handleNavClick(item.id)}
            >
              <span className="bm-nav-icon">{item.icon}</span>
              <span className="bm-nav-label-text">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="bm-sidebar-bottom">
          <button className="bm-logout" onClick={() => setShowLogoutModal(true)}>
            <span className="bm-nav-icon">⏻</span>
            <span>Logout</span>
          </button>
          <div className="bm-secure">
            <span className="bm-secure-dot" />
            Signed in securely
          </div>
        </div>
      </aside>

      <div className="bm-main">
        <header className="bm-topbar">
          <div className="bm-topbar-left">
            <div className="bm-topbar-title">
              <strong>Branch Manager Dashboard</strong>
              <span>Branch operations &amp; team management</span>
            </div>
          </div>
          <div className="bm-topbar-right">
            <button className="bm-icon-btn" aria-label="Notifications">
              <span className="bm-badge">{stats.pendingKyc}</span>
            </button>

            <div style={{ position: 'relative' }} ref={profileMenuRef}>
              <button
                className="bm-profile"
                onClick={() => setShowProfileMenu(!showProfileMenu)}
                style={{ cursor: 'pointer' }}
              >
                <span className="bm-avatar-sm">{initials(identity.name)}</span>
                <span className="bm-profile-name">{identity.name}</span>
              </button>

              {showProfileMenu && (
                <div
                  style={{
                    position: 'absolute',
                    top: '100%',
                    right: 0,
                    marginTop: '8px',
                    background: '#fff',
                    border: '1px solid #e2e8f0',
                    borderRadius: '8px',
                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                    minWidth: '200px',
                    zIndex: 50,
                    overflow: 'hidden',
                  }}
                >
                  <button
                    onClick={() => {
                      setShowProfileMenu(false);
                      navigate('/profile');
                    }}
                    style={{
                      width: '100%',
                      textAlign: 'left',
                      padding: '12px 16px',
                      background: 'transparent',
                      border: 'none',
                      borderBottom: '1px solid #f1f5f9',
                      cursor: 'pointer',
                      fontSize: '13px',
                      color: '#1e293b',
                    }}
                  >
                     View Profile
                  </button>
                  <button
                    onClick={() => {
                      setShowProfileMenu(false);
                      setShowPasswordModal(true);
                    }}
                    style={{
                      width: '100%',
                      textAlign: 'left',
                      padding: '12px 16px',
                      background: 'transparent',
                      border: 'none',
                      cursor: 'pointer',
                      fontSize: '13px',
                      color: '#1e293b',
                    }}
                  >
                     Change Password
                  </button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="bm-content">
          
          {/* IF A KYC ID IS SELECTED, SHOW THE KYC DETAIL PAGE INSIDE THE MAIN CONTENT */}
          {selectedKycId ? (
             <div style={{ background: '#fff', borderRadius: '14px', border: '1px solid #e1e7f0', padding: '20px', minHeight: '500px' }}>
                <KycApplicationDetail
                  kycId={selectedKycId}
                  onBack={() => setSelectedKycId(null)}
                  onUpdate={load}
                />
             </div>
          ) : (
            /* OTHERWISE, SHOW THE NORMAL DASHBOARD PAGES */
            <>
              {activePage === 'Customers' && (
                <BranchCustomersPage customers={customers} loading={loading} />
              )}
              {activePage === 'Accounts' && (
                <BranchAccountsPage
                  accounts={accounts}
                  customers={customers}
                  loading={loading}
                  onRefresh={load}
                />
              )}
              {activePage === 'Transactions' && (
                <BranchTransactionsPage
                  transactions={transactions}
                  loading={loading}
                  onRefresh={load}
                />
              )}
              {activePage === 'KYC' && (
                <BranchKycPage kycList={kyc} loading={loading} onRefresh={load} />
              )}
              {activePage === 'Loans' && (
               <BankLoanManagerPage
                 onBack={() => setActivePage('Dashboard')}
                 isBranchManager
                 canManageProducts
                 canProcessApplications
                 currentUser={user}
                 onSignOut={onSignOut}
               />
              )}

              {activePage === 'Employees' && (
                <BranchEmployeesPage
                  employees={employees}
                  loading={loading}
                  onRefresh={() => load(true)}
                  currentBranchId={branch?.branchCode}
                />
              )}

              {activePage === 'Reports' && (
                <BranchReportsPage
                  accounts={accounts}
                  transactions={transactions}
                  customers={customers}
                />
              )}
              {activePage === 'Settings' && (
                <BranchSettingsPage branch={branch} identity={identity} />
              )}

              {activePage === 'Dashboard' && (
                <>
                  <div className="bm-welcome">
                    <div>
                      <h1>Welcome back, {identity.name.split(' ')[0] || 'Manager'}!</h1>
                      <p>
                        Manage your branch operations, monitor customers, and keep the team on track.
                      </p>
                    </div>
                    <div className="bm-welcome-side">
                      <div className="bm-branch-chip">
                        <span className="bm-branch-icon"></span>
                        <div>
                          <b>{branch?.branchName || 'Assigned branch'}</b>
                          <small>
                            {branch?.branchCode
                              ? `Branch Code · ${branch.branchCode}`
                              : 'Branch Code · —'}
                            {branch?.city ? ` · ${branch.city}` : ''}
                          </small>
                        </div>
                      </div>
                      <div className="bm-date-chip">
                        <span></span>
                        <div>
                          <b>
                            {new Intl.DateTimeFormat('en-IN', {
                              weekday: 'short',
                              day: '2-digit',
                              month: 'short',
                              year: 'numeric',
                            }).format(new Date())}
                          </b>
                          <small>
                            {new Intl.DateTimeFormat('en-IN', {
                              hour: '2-digit',
                              minute: '2-digit',
                            }).format(new Date())}
                          </small>
                        </div>
                      </div>
                    </div>
                  </div>

                  {error && (
                    <div className="bm-alert" role="alert">
                      {error}
                      <button onClick={load} disabled={refreshing}>
                        {refreshing ? 'Retrying…' : 'Retry'}
                      </button>
                    </div>
                  )}

                  <section
                    className="bm-kpis"
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
                      gap: '16px',
                      marginBottom: '24px',
                    }}
                  >
                    <KpiCard icon="" label="Total customers" value={stats.customers} tone="blue" loading={loading} />
                    <KpiCard icon="▣" label="Active accounts" value={stats.accounts} tone="violet" loading={loading} />
                    <KpiCard icon="" label="Pending KYC" value={stats.pendingKyc} tone="amber" loading={loading} />
                    <KpiCard icon="⇄" label="Today's transactions" value={stats.todayTxns} tone="green" loading={loading} />
                    <KpiCard icon="" label="Total employees" value={stats.totalEmployees} tone="blue" loading={loading} />
                  </section>

                  <section
                    className="bm-grid"
                    style={{
                      display: 'grid',
                      gridTemplateColumns: '1fr',
                      gap: '24px',
                      alignItems: 'start',
                    }}
                  >
                    <div className="bm-panel" style={{ overflow: 'visible' }}>
                      <div className="bm-panel-head">
                        <div>
                          <h2>Recent branch activity</h2>
                          <p>Latest transactions and KYC actions</p>
                        </div>
                        <button className="bm-ghost" onClick={() => setActivePage('Transactions')}>
                          View all →
                        </button>
                      </div>
                      <div className="bm-table-wrap" style={{ overflowX: 'auto' }}>
                        <table className="bm-table" style={{ width: '100%', tableLayout: 'auto' }}>
                          <thead>
                            <tr>
                              <th style={{ width: '20%' }}>Time</th>
                              <th style={{ width: '15%' }}>Type</th>
                              <th style={{ width: '25%' }}>Reference</th>
                              <th style={{ width: '25%' }}>Details</th>
                              <th style={{ width: '15%' }}>Status</th>
                            </tr>
                          </thead>
                          <tbody>
                            {loading ? (
                              <tr>
                                <td colSpan="5" className="bm-empty">
                                  Loading activity…
                                </td>
                              </tr>
                            ) : recentActivity.length === 0 ? (
                              <tr>
                                <td colSpan="5" className="bm-empty">
                                  No recent activity.
                                </td>
                              </tr>
                            ) : (
                              recentActivity.map((row, i) => (
                                <tr
                                  key={`${row.id || i}`}
                                  onClick={() => {
                                    if (row.isKyc) {
                                      setSelectedKycId(row.id);
                                    } else {
                                      setSelectedTx(row.originalData);
                                    }
                                  }}
                                  style={{ cursor: 'pointer' }}
                                  className="bm-row-hover"
                                >
                                  <td className="bm-cell-time">
                                    {formatDate(row.time)} · {formatTime(row.time)}
                                  </td>
                                  <td>{row.type}</td>
                                  <td className="bm-cell-ref">{row.ref}</td>
                                  <td>{row.detail}</td>
                                  <td>
                                    <StatusPill tone={statusTone(row.status)}>
                                      {String(row.status).replaceAll('_', ' ')}
                                    </StatusPill>
                                  </td>
                                </tr>
                              ))
                            )}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </section>

                  <footer className="bm-footer">
                    © 2026 Nova Bank · Branch Operations
                    <span>{refreshing ? 'Refreshing…' : 'Live data'}</span>
                  </footer>
                </>
              )}
            </>
          )}
        </div>
      </div>

      {showLogoutModal && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.5)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 9999,
          }}
          onClick={() => setShowLogoutModal(false)}
        >
          <div
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '12px',
              width: '100%',
              maxWidth: '400px',
              boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>
              Log out of Nova Bank?
            </h3>
            <p
              style={{
                color: '#64748b',
                fontSize: '14px',
                margin: '0 0 24px 0',
                lineHeight: 1.5,
              }}
            >
              Are you sure you want to securely log out of your account? You will need to sign
              in again to continue.
            </p>
            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
              <button
                onClick={() => setShowLogoutModal(false)}
                style={{
                  padding: '8px 16px',
                  background: 'transparent',
                  border: '1px solid #cbd5e1',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600,
                  color: '#475569',
                }}
              >
                Cancel
              </button>
              <button
                onClick={confirmLogout}
                style={{
                  padding: '8px 16px',
                  background: '#e11d48',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontWeight: 600,
                  color: 'white',
                }}
              >
                Yes, log out
              </button>
            </div>
          </div>
        </div>
      )}

      {showIdleWarning && (
        <div
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(15, 23, 42, 0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10000,
          }}
        >
          <div
            style={{
              background: '#fff',
              padding: '24px',
              borderRadius: '12px',
              width: '100%',
              maxWidth: '400px',
              textAlign: 'center',
              boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)',
            }}
          >
            <div style={{ fontSize: '40px', marginBottom: '16px' }}>⏳</div>
            <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#0f172a' }}>
              Are you still there?
            </h3>
            <p
              style={{
                color: '#64748b',
                fontSize: '14px',
                margin: '0 0 24px 0',
                lineHeight: 1.5,
              }}
            >
              For your security, you will be logged out automatically in{' '}
              <b>{idleCountdown}</b> seconds due to inactivity.
            </p>
            <button
              onClick={handleStayActive}
              style={{
                width: '100%',
                padding: '12px',
                background: '#1769e0',
                color: 'white',
                border: 'none',
                borderRadius: '8px',
                cursor: 'pointer',
                fontWeight: 600,
                fontSize: '14px',
              }}
            >
              I'm still here, continue session
            </button>
          </div>
        </div>
      )}

      {showPasswordModal && (
        <ChangePasswordModal onClose={() => setShowPasswordModal(false)} />
      )}

      {selectedTx && (
        <TransactionModal transaction={selectedTx} onClose={() => setSelectedTx(null)} />
      )}
    </div>
  );
}

/* =========================================================
   Small Presentational Helpers
   ========================================================= */

function KpiCard({ icon, label, value, tone = 'blue', loading }) {
  return (
    <article className={`bm-kpi bm-kpi-${tone}`}>
      <span className="bm-kpi-icon">{icon}</span>
      <div className="bm-kpi-body">
        <span className="bm-kpi-label" style={{ fontSize: '12px' }}>
          {label}
        </span>
        <strong className="bm-kpi-value" style={{ fontSize: '20px' }}>
          {loading ? '—' : value}
        </strong>
      </div>
    </article>
  );
}

function StatusPill({ tone = 'neutral', children }) {
  return <span className={`bm-status bm-status-${tone}`}>{children}</span>;
}

function EmptyState({ icon = '', title = 'Nothing here yet', message = '' }) {
  return (
    <div style={{ padding: '48px 24px', textAlign: 'center', color: '#64748b' }}>
      <div style={{ fontSize: '40px', marginBottom: '12px' }}>{icon}</div>
      <h3 style={{ margin: '0 0 6px', fontSize: '15px', color: '#0f172a' }}>{title}</h3>
      {message && <p style={{ margin: 0, fontSize: '13px' }}>{message}</p>}
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react'
import {
  assignLoanApplication,
  assessLoanCredit,
  createLoanProduct,
  decideLoanApplication,
  disburseLoan,
  getApplicationLoanAccount,
  getAssignedLoanApplications,
  getLoanApplications,
  getLoanApplicationReviewDetails,
  getLoanProducts,
  previewLoanDocument,
  recommendLoanApplication,
  deleteLoanDocument,
  requestAdditionalLoanDocuments,
  prepareLoanDisbursement,
  verifyLoanDocument,
} from '../../../../../services/loanApi'
import './BankLoanManagerPage.css'

function DocumentPreview({ file, onClose }) {
  const url = useMemo(() => (file ? URL.createObjectURL(file) : ''), [file])

  useEffect(() => {
    if (!url) return undefined
    return () => URL.revokeObjectURL(url)
  }, [url])

  if (!file) return null
  return (
    <div className="blm-preview-backdrop" role="presentation" onClick={onClose}>
      <section className="blm-preview-modal" role="dialog" aria-modal="true" aria-label="Loan document preview" onClick={(event) => event.stopPropagation()}>
        <div className="blm-preview-heading"><b>Document preview</b><button className="blm-button blm-button-light" onClick={onClose}>Close</button></div>
        {file.type.startsWith('image/') ? <img src={url} alt="Customer loan document" /> : <iframe title="Customer loan document" src={url} />}
      </section>
    </div>
  )
}

const money = (value) =>
  value == null
    ? '—'
    : new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 2,
      }).format(Number(value))

const statusLabel = (value) => ({
  SUBMITTED: 'Submitted',
  DETAILS_SUBMITTED: 'Submitted',
  DOCUMENTS_VERIFIED: 'Under review',
  CREDIT_PASSED: 'Under review',
  CREDIT_FAILED: 'Credit assessment failed',
  RECOMMENDED: 'Pending manager approval',
  RETURNED_FOR_REVIEW: 'Returned for review',
  ADDITIONAL_DOCUMENTS_REQUIRED: 'Documents required',
  REJECTED: 'Rejected',
  OFFERED: 'Offer sent',
  OFFER_REJECTED: 'Offer declined',
  OFFER_ACCEPTED: 'Agreement pending',
  AGREEMENT_ACCEPTED: 'Disbursement pending',
  DISBURSEMENT_AUTHORIZED: 'Disbursement processing',
  DISBURSEMENT_PENDING: 'Transfer ready',
  DISBURSED: 'Disbursed',
  CLOSED: 'Closed',
}[value] || String(value || '').replace(/_/g, ' '))
const profileValue = (value) => {
  if (value == null || value === '') return '—'
  if (typeof value === 'object') return new Date(value).toLocaleDateString('en-IN')
  return String(value)
}

const daysWaiting = (createdAt) => {
  const submittedAt = createdAt ? new Date(createdAt).getTime() : NaN
  return Number.isFinite(submittedAt)
    ? Math.max(0, Math.floor((Date.now() - submittedAt) / 86_400_000))
    : null
}

const reviewableStatuses = [
  'SUBMITTED',
  'DETAILS_SUBMITTED',
  'ADDITIONAL_DOCUMENTS_REQUIRED',
  'RETURNED_FOR_REVIEW',
]
const actionableStatuses = [
  ...reviewableStatuses,
  'DOCUMENTS_VERIFIED',
  'CREDIT_PASSED',
  'AGREEMENT_ACCEPTED',
  'DISBURSEMENT_AUTHORIZED',
  'DISBURSEMENT_PENDING',
]

function ProfileCard({ title, subtitle, icon, fields }) {
  const visibleFields = fields.filter(([, value]) => value != null && value !== '')
  if (!visibleFields.length) return null
  return (
    <section className="lo-profile-card">
      <header>
        <span className="lo-profile-icon" aria-hidden="true">{icon}</span>
        <div><h3>{title}</h3><p>{subtitle}</p></div>
      </header>
      <div className="lo-profile-grid">
        {visibleFields.map(([label, value]) => (
          <div className="lo-profile-field" key={label}>
            <span>{label}</span>
            <b>{profileValue(value)}</b>
          </div>
        ))}
      </div>
    </section>
  )
}

export default function BankLoanManagerPage({
  onBack,
  standalone = false,
  canManageProducts = false,
  canProcessApplications = false,
  isBranchManager = false,
  currentUser,
  onSignOut,
}) {
  const [tab, setTab] = useState('applications')
  const [workspaceView, setWorkspaceView] = useState('dashboard')
  const [applicationFilter, setApplicationFilter] = useState('ALL')
  const [applicationSort, setApplicationSort] = useState('OLDEST')
  const [search, setSearch] = useState('')
  const [applications, setApplications] = useState([])
  const [products, setProducts] = useState([])
  const [selected, setSelected] = useState(null)
  const [documents, setDocuments] = useState([])
  const [customerProfile, setCustomerProfile] = useState(null)
  const [history, setHistory] = useState([])
  const [loanAccount, setLoanAccount] = useState(null)
  const [beneficiaryConfirmed, setBeneficiaryConfirmed] = useState(false)
  const [previewFile, setPreviewFile] = useState(null)
  const [recommendation, setRecommendation] = useState({
    recommendation: 'APPROVE',
    remarks: '',
    amount: '',
    annualInterestRate: '',
    tenureMonths: '',
  })
  const [managerDecision, setManagerDecision] = useState({
    decision: 'APPROVE',
    reason: '',
    amount: '',
    annualInterestRate: '',
    tenureMonths: '',
  })
  const [officerId, setOfficerId] = useState('')
  const [requestedDocuments, setRequestedDocuments] = useState('')
  const [productForm, setProductForm] = useState({
    name: '',
    description: '',
    minimumAmount: '50000',
    maximumAmount: '1000000',
    annualInterestRate: '12',
    minimumTenureMonths: '12',
    maximumTenureMonths: '60',
    maximumFoirPercent: '50',
    minimumCreditScore: '650',
  })
  const [creditScore, setCreditScore] = useState('700')
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState('')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')

  const loadApplications = async () => {
    const data = isBranchManager ? await getLoanApplications() : await getAssignedLoanApplications()
    setApplications(Array.isArray(data) ? data : [])
  }

  const loadProducts = async () => {
    const data = await getLoanProducts()
    setProducts(Array.isArray(data) ? data : [])
  }

  const refresh = async () => {
    setError('')
    const tasks = [loadApplications()]
    if (canManageProducts) tasks.push(loadProducts())
    await Promise.all(tasks)
  }

  useEffect(() => {
    let active = true
    const requests = [isBranchManager ? getLoanApplications() : getAssignedLoanApplications()]
    if (canManageProducts) requests.push(getLoanProducts())
    Promise.all(requests)
      .then(([applicationData, productData]) => {
        if (!active) return
        setApplications(Array.isArray(applicationData) ? applicationData : [])
        if (canManageProducts) {
          setProducts(Array.isArray(productData) ? productData : [])
        }
      })
      .catch((loadError) => {
        if (active) setError(loadError.message)
      })
      .finally(() => {
        if (active) setLoading(false)
      })
    return () => {
      active = false
    }
  }, [canManageProducts, isBranchManager])

  const openApplication = async (application) => {
    setBusy('details')
    setError('')
    setSelected(application)
    setCustomerProfile(null)
    setHistory([])
    setDocuments([])
    setLoanAccount(null)
    setBeneficiaryConfirmed(false)
    try {
      const [details, account] = await Promise.all([
        getLoanApplicationReviewDetails(application.id),
        getApplicationLoanAccount(application.id),
      ])
      setSelected(details.application)
      setCustomerProfile(details.customer)
      setDocuments(Array.isArray(details.documents) ? details.documents : [])
      setHistory(Array.isArray(details.history) ? details.history : [])
      setLoanAccount(account)
      const product = products.find((item) => item.id === details.application.productId)
      setRecommendation({
        recommendation: 'APPROVE',
        remarks: '',
        amount: String(details.application.requestedAmount ?? ''),
        annualInterestRate: String(product?.annualInterestRate ?? ''),
        tenureMonths: String(details.application.tenureMonths ?? ''),
      })
      setManagerDecision({
        decision: details.application.recommendation === 'REJECT' ? 'REJECT' : 'APPROVE',
        reason: '',
        amount: String(details.application.recommendedAmount ?? details.application.requestedAmount ?? ''),
        annualInterestRate: String(details.application.recommendedInterestRate ?? product?.annualInterestRate ?? ''),
        tenureMonths: String(details.application.recommendedTenureMonths ?? details.application.tenureMonths ?? ''),
      })
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const refreshSelected = async () => {
    if (!selected) return
    const [details, applicationData] = await Promise.all([
      getLoanApplicationReviewDetails(selected.id),
      isBranchManager ? getLoanApplications() : getAssignedLoanApplications(),
    ])
    const account = await getApplicationLoanAccount(selected.id)
    setSelected(details.application)
    setCustomerProfile(details.customer)
    setDocuments(Array.isArray(details.documents) ? details.documents : [])
    setHistory(Array.isArray(details.history) ? details.history : [])
    setApplications(Array.isArray(applicationData) ? applicationData : [])
    setLoanAccount(account)
    setBeneficiaryConfirmed(false)
  }

  const runAction = async (key, action, successMessage) => {
    if (!selected) return
    setBusy(key)
    setError('')
    setNotice('')
    try {
      await action()
      await refreshSelected()
      setNotice(successMessage)
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const reviewDocument = async (documentId, verified) => {
    await runAction(
      `document-${documentId}`,
      () => verifyLoanDocument(documentId, verified),
      verified ? 'Document marked as verified.' : 'Document verification rejected.'
    )
  }

  const removeRejectedDocument = (documentId) =>
    runAction(`remove-document-${documentId}`, () => deleteLoanDocument(documentId),
      'Rejected document removed. The customer can upload a corrected file.')

  const runCreditAssessment = () =>
    runAction(
      'assessment',
      () => assessLoanCredit(selected.id, Number(creditScore)),
      'Credit assessment completed.'
    )

  const submitRecommendation = () =>
    runAction('recommendation', () => recommendLoanApplication(selected.id, {
      recommendation: recommendation.recommendation,
      remarks: recommendation.remarks,
      ...(recommendation.recommendation === 'APPROVE' ? {
        amount: Number(recommendation.amount),
        annualInterestRate: Number(recommendation.annualInterestRate),
        tenureMonths: Number(recommendation.tenureMonths),
      } : {}),
    }), recommendation.recommendation === 'APPROVE'
      ? 'Approval recommendation sent to the branch manager.'
      : 'Rejection recommendation sent to the branch manager for final decision.')

  const submitManagerDecision = () =>
    runAction('manager-decision', () => decideLoanApplication(selected.id, {
      decision: managerDecision.decision,
      reason: managerDecision.reason,
      ...(managerDecision.decision === 'APPROVE' ? {
        amount: managerDecision.amount ? Number(managerDecision.amount) : null,
        annualInterestRate: managerDecision.annualInterestRate ? Number(managerDecision.annualInterestRate) : null,
        tenureMonths: managerDecision.tenureMonths ? Number(managerDecision.tenureMonths) : null,
      } : {}),
    }), 'Branch manager decision saved.')

  const assignApplication = () =>
    runAction('assignment', () => assignLoanApplication(selected.id, officerId), 'Application assigned.')

  const requestDocuments = () =>
    runAction('additional-documents', () => requestAdditionalLoanDocuments(selected.id, requestedDocuments),
      'Additional document request sent to the customer.')


  const prepareDisbursement = async () => {
    if (!selected) return
    setBusy('disbursement')
    setError('')
    setNotice('')
    try {
      await prepareLoanDisbursement(selected.id)
      await refreshSelected()
      setNotice('Agreement and beneficiary account verified. The loan account and repayment schedule are ready for transfer.')
    } catch (requestError) {
      setError(requestError.message)
      try {
        await refreshSelected()
      } catch {
        // Keep the original disbursement error visible.
      }
    } finally {
      setBusy('')
    }
  }

  const completeDisbursement = async () => {
    if (!selected || !beneficiaryConfirmed) return
    setBusy('disbursement')
    setError('')
    setNotice('')
    try {
      await disburseLoan(selected.id)
      await refreshSelected()
      setNotice('Transfer confirmed. The loan account is now active.')
    } catch (requestError) {
      setError(requestError.message)
      try {
        await refreshSelected()
      } catch {
        // Keep the original disbursement error visible.
      }
    } finally {
      setBusy('')
    }
  }

  const downloadDocument = async (document) => {
    setBusy(`download-${document.id}`)
    setError('')
    try {
      setPreviewFile(await previewLoanDocument(document.id))
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const createProduct = async (event) => {
    event.preventDefault()
    setBusy('product')
    setError('')
    setNotice('')
    try {
      await createLoanProduct({
        ...productForm,
        minimumAmount: Number(productForm.minimumAmount),
        maximumAmount: Number(productForm.maximumAmount),
        annualInterestRate: Number(productForm.annualInterestRate),
        minimumTenureMonths: Number(productForm.minimumTenureMonths),
        maximumTenureMonths: Number(productForm.maximumTenureMonths),
        maximumFoirPercent: Number(productForm.maximumFoirPercent),
        minimumCreditScore: Number(productForm.minimumCreditScore),
      })
      setProductForm((current) => ({ ...current, name: '', description: '' }))
      await loadProducts()
      setNotice('Loan product created. Customers can now view it.')
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const visibleApplications = applications.filter((application) => {
    const query = search.trim().toLowerCase()
    if (query && ![
      application.customerName,
      application.customerId,
      application.customerEmail,
      application.customerPhone,
      application.id,
      application.status,
      application.purpose,
    ].some((value) => String(value || '').toLowerCase().includes(query))) return false
    if (applicationFilter === 'PENDING_APPROVALS') return application.status === 'RECOMMENDED'
    if (applicationFilter === 'PENDING_REVIEW') return actionableStatuses.includes(application.status)
    if (applicationFilter === 'DOCUMENTS_PENDING') return reviewableStatuses.includes(application.status)
    if (applicationFilter === 'CREDIT_PENDING') return application.status === 'DOCUMENTS_VERIFIED'
    if (applicationFilter === 'RECOMMENDED') return application.status === 'RECOMMENDED'
    if (applicationFilter === 'DISBURSEMENT') return ['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING'].includes(application.status)
    return true
  }).sort((left, right) => {
    if (applicationSort === 'NEWEST') {
      return new Date(right.createdAt || 0) - new Date(left.createdAt || 0)
    }
    if (applicationSort === 'AMOUNT') {
      return Number(right.requestedAmount || 0) - Number(left.requestedAmount || 0)
    }
    return new Date(left.createdAt || 0) - new Date(right.createdAt || 0)
  })

  const dashboardMetrics = useMemo(() => {
    const count = (statuses) => applications.filter((application) => statuses.includes(application.status)).length
    if (!isBranchManager) {
      const oldest = applications
        .filter((application) => actionableStatuses.includes(application.status))
        .map((application) => daysWaiting(application.createdAt))
        .filter((days) => days != null)
      return [
        ['Assigned applications', applications.length, 'ALL'],
        ['Submitted applications', count(['SUBMITTED', 'DETAILS_SUBMITTED']), 'DOCUMENTS_PENDING'],
        ['Pending review', count(actionableStatuses), 'PENDING_REVIEW'],
        ['Documents pending', count(reviewableStatuses), 'DOCUMENTS_PENDING'],
        ['Credit assessment pending', count(['DOCUMENTS_VERIFIED']), 'CREDIT_PENDING'],
        ['Recommended for approval', applications.filter((application) => application.status === 'RECOMMENDED' && application.recommendation === 'APPROVE').length, 'RECOMMENDED'],
        ['Recommended for rejection', applications.filter((application) => application.status === 'RECOMMENDED' && application.recommendation === 'REJECT').length, 'RECOMMENDED'],
        ['Disbursement queue', count(['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING']), 'DISBURSEMENT'],
        ['Oldest open case', oldest.length ? `${Math.max(...oldest)} days` : '—', 'PENDING_REVIEW'],
      ]
    }

    const approvedStatuses = ['OFFERED', 'OFFER_ACCEPTED', 'AGREEMENT_ACCEPTED', 'DISBURSEMENT_PENDING', 'DISBURSED', 'CLOSED']
    const sanctionedAmount = applications
      .filter((application) => approvedStatuses.includes(application.status))
      .reduce((total, application) => total + Number(application.recommendedAmount ?? application.requestedAmount ?? 0), 0)
    return [
      ['Total applications', applications.length, 'ALL'],
      ['Pending approvals', count(['RECOMMENDED']), 'PENDING_APPROVALS'],
      ['Approved loans', count(approvedStatuses), 'ALL'],
      ['Rejected', count(['REJECTED', 'OFFER_REJECTED']), 'ALL'],
      ['Returned for review', count(['RETURNED_FOR_REVIEW']), 'PENDING_REVIEW'],
      ['Disbursement pending', count(['AGREEMENT_ACCEPTED', 'DISBURSEMENT_PENDING']), 'DISBURSEMENT'],
      ['Disbursed', count(['DISBURSED', 'CLOSED']), 'ALL'],
      ['Sanctioned amount', money(sanctionedAmount), 'ALL'],
    ]
  }, [applications, isBranchManager])

  const staffName = currentUser?.name || currentUser?.fullName || currentUser?.email || 'Loan Officer'
  const initials = String(staffName).split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join('') || 'LO'
  const canReviewApplications = canProcessApplications || isBranchManager

  if (loading) return <div className="blm-state">Loading loan workspace…</div>

  return (
    <div className={`blm-page ${isBranchManager ? 'blm-manager' : ''} ${standalone ? `blm-standalone lo-shell ${selected ? 'lo-has-selection' : ''}` : ''}`}>
      {standalone && (
        <aside className="lo-sidebar">
          <div className="lo-brand">
            <span className="lo-brand-mark">N</span>
            <span><b>NOVA BANK</b><small>Your Trust. Our Priority.</small></span>
          </div>
          <div className="lo-staff">
            <span className="lo-avatar">{initials}</span>
            <div><b>{staffName}</b><small>Loan Officer</small><span><i />Online</span></div>
          </div>
          <div className="lo-nav-label">Workspace</div>
          <nav className="lo-nav" aria-label="Loan officer workspace">
            <button className={tab === 'applications' && workspaceView === 'dashboard' && !selected ? 'active' : ''} onClick={() => { setTab('applications'); setWorkspaceView('dashboard'); setApplicationFilter('ALL'); setSelected(null) }}><span>▦</span>Dashboard</button>
            <button className={tab === 'applications' && workspaceView === 'assigned' && !selected ? 'active' : ''} onClick={() => { setTab('applications'); setWorkspaceView('assigned'); setApplicationFilter('PENDING_REVIEW'); setSelected(null) }}><span>▤</span>Assigned Applications</button>
            {canManageProducts && <button className={tab === 'products' ? 'active' : ''} onClick={() => { setTab('products'); setSelected(null) }}><span>＋</span>Loan Products</button>}
          </nav>
          <div className="lo-sidebar-bottom">
            <button onClick={onSignOut}><span>⏻</span>Sign out</button>
            <small><i />Signed in securely</small>
          </div>
        </aside>
      )}

      <div className={standalone ? 'lo-main' : ''}>
      {standalone && (
        <header className="lo-topbar">
          <div><b>{selected ? 'Application details' : tab === 'products' ? 'Loan products' : 'Loan Officer Dashboard'}</b><span>{selected ? `Reviewing ${selected.id}` : 'Application processing & customer verification'}</span></div>
          <div className="lo-topbar-actions"><button className="blm-button blm-button-light" onClick={() => refresh().catch((requestError) => setError(requestError.message))}>Refresh</button><div className="lo-account"><span>{initials}</span><b>{staffName}</b></div></div>
        </header>
      )}
      <div className={standalone ? 'lo-content' : ''}>
      <header className="blm-hero">
        <div>
          <span className="blm-eyebrow">LOAN OPERATIONS</span>
          <h2>{tab === 'products' ? 'Loan products' : isBranchManager ? 'Branch loan approvals' : 'Loan officer workspace'}</h2>
          <p>{isBranchManager ? 'Review recommendations, make authorized decisions, and monitor branch loan processing.' : 'Verify applicant details and documents, assess credit, and recommend a decision.'}</p>
        </div>
        <div className="blm-hero-actions">
          {onBack && <button className="blm-button blm-button-light" onClick={onBack}>Back to dashboard</button>}
          <button className="blm-button blm-button-light" onClick={() => refresh().catch((e) => setError(e.message))}>Refresh</button>
        </div>
      </header>

      {error && <div className="blm-alert blm-alert-error" role="alert">{error}</div>}
      {notice && <div className="blm-alert blm-alert-success" role="status">{notice}</div>}

      <section className="blm-stat-grid" aria-label={isBranchManager ? 'Branch loan statistics' : 'Assigned loan statistics'}>
        {dashboardMetrics.map(([label, value, filter]) => (
          <button
            type="button"
            className={`blm-stat-card ${applicationFilter === filter && tab === 'applications' ? 'active' : ''}`}
            key={label}
            onClick={() => {
              setTab('applications')
              setApplicationFilter(filter)
              setWorkspaceView('assigned')
              setSelected(null)
            }}
          >
            <span>{label}</span><b>{value}</b><small>Open queue →</small>
          </button>
        ))}
      </section>

      <nav className="blm-tabs" aria-label="Loan workspace">
        <button className={tab === 'applications' ? 'active' : ''} onClick={() => setTab('applications')}>
          Applications <span>{applications.length}</span>
        </button>
        {canManageProducts && (
          <button className={tab === 'products' ? 'active' : ''} onClick={() => setTab('products')}>
            Products
          </button>
        )}
      </nav>

      {tab === 'applications' && (
        <div className={`blm-workspace ${selected ? 'blm-has-selection' : ''} ${standalone ? 'lo-workspace' : ''}`}>
          <section className="blm-panel blm-queue-panel">
            <div className="blm-panel-heading">
              <div className="blm-queue-title"><span className="blm-eyebrow">WORK QUEUE · {visibleApplications.length} CASES</span><h3>{applicationFilter === 'PENDING_APPROVALS' ? 'Pending approvals' : applicationFilter === 'DOCUMENTS_PENDING' ? 'Document verification' : applicationFilter === 'CREDIT_PENDING' ? 'Ready for credit assessment' : applicationFilter === 'RECOMMENDED' ? 'Manager recommendations' : applicationFilter === 'DISBURSEMENT' ? 'Disbursement queue' : applicationFilter === 'PENDING_REVIEW' ? 'Cases needing action' : standalone ? 'Assigned applications' : 'Loan applications'}</h3><p>{standalone ? 'Prioritized by oldest case first. Open an application to complete verification and review.' : 'Select an application to review customer and loan information.'}</p></div>
              <input className="lo-search" aria-label="Search applications" placeholder="Search customer or application" value={search} onChange={(event) => setSearch(event.target.value)} />
              <select aria-label="Filter loan applications" value={applicationFilter} onChange={(event) => setApplicationFilter(event.target.value)}>
                <option value="ALL">All applications</option>
                <option value="PENDING_REVIEW">Pending review</option>
                <option value="DOCUMENTS_PENDING">Documents pending</option>
                <option value="CREDIT_PENDING">Credit assessment</option>
                <option value="RECOMMENDED">Recommendations</option>
                <option value="DISBURSEMENT">Disbursement queue</option>
                {isBranchManager && <option value="PENDING_APPROVALS">Pending approvals</option>}
              </select>
              <select aria-label="Sort applications" value={applicationSort} onChange={(event) => setApplicationSort(event.target.value)}>
                <option value="OLDEST">Oldest first</option>
                <option value="NEWEST">Newest first</option>
                <option value="AMOUNT">Highest amount</option>
              </select>
            </div>
            {visibleApplications.length === 0 ? (
              <div className="blm-state">
                <span>{search ? 'No applications match your search.' : applicationFilter === 'ALL' ? 'No applications are available.' : 'There are no applications in this queue right now.'}</span>
                {(search || applicationFilter !== 'ALL') && (
                  <button
                    className="blm-button blm-button-light"
                    onClick={() => { setSearch(''); setApplicationFilter('ALL') }}
                  >
                    Show all applications
                  </button>
                )}
              </div>
            ) : (
              <div className="blm-application-list">
                {visibleApplications.map((application) => (
                  <button className={`blm-application-row ${selected?.id === application.id ? 'selected' : ''}`} key={application.id} onClick={() => openApplication(application)}>
                    <span className="blm-row-main">
                      <b>{application.customerName || application.customerId}</b>
                      <small>{money(application.requestedAmount)} · {application.tenureMonths} months · {application.purpose || 'Purpose not specified'}</small>
                      <small>{application.customerPhone || application.customerEmail || application.customerId}</small>
                    </span>
                    <span className="blm-row-secondary">
                      <b className={`blm-queue-status blm-queue-status-${String(application.status).toLowerCase()}`}>{statusLabel(application.status)}</b>
                      <small>{application.id}</small>
                      <small className={daysWaiting(application.createdAt) >= 3 && actionableStatuses.includes(application.status) ? 'blm-case-aged' : ''}>
                        {daysWaiting(application.createdAt) == null ? 'Date unavailable' : daysWaiting(application.createdAt) === 0 ? 'Received today' : `Waiting ${daysWaiting(application.createdAt)}d`}
                        {daysWaiting(application.createdAt) >= 3 && actionableStatuses.includes(application.status) ? ' · Review due' : ''}
                      </small>
                    </span>
                  </button>
                ))}
              </div>
            )}
          </section>

          <section className="blm-panel blm-detail-panel">
            {!selected ? <div className="blm-state">Select an application to see the review steps.</div> : busy === 'details' ? <div className="blm-state">Loading application details…</div> : (
              <>
                <div className="blm-panel-heading blm-detail-heading">
                  <button className="blm-button blm-button-light" onClick={() => setSelected(null)}>← Back to applications</button>
                  <div><span className="blm-eyebrow">APPLICATION · {selected.productId ? `PRODUCT #${selected.productId}` : ''}</span><h3>{selected.customerName || customerProfile?.name || selected.customerId}</h3><p>Customer ID: <b>{selected.customerId || '—'}</b> · Application: {selected.id}</p></div>
                  <span className={`lo-status lo-status-${String(selected.status).toLowerCase()}`}>{statusLabel(selected.status)}</span>
                </div>
                <div className="lo-customer-strip">
                  <div><span></span><section><small>CUSTOMER NAME</small><b>{customerProfile?.name || selected.customerName || '—'}</b></section></div>
                  <div><span>✉</span><section><small>EMAIL ADDRESS</small><b>{customerProfile?.email || selected.customerEmail || '—'}</b></section></div>
                  <div><span>▦</span><section><small>MOBILE NUMBER</small><b>{customerProfile?.mobileNumber || selected.customerPhone || '—'}</b></section></div>
                  <div><span>◈</span><section><small>KYC STATUS</small><b>{selected.kycStatus || '—'}</b></section></div>
                </div>
                <div className="blm-facts">
                  <div><span>Application ID</span><b>{selected.id}</b></div>
                  <div><span>Customer ID</span><b>{selected.customerId || '—'}</b></div>
                  <div><span>Email</span><b>{selected.customerEmail || customerProfile?.email || '—'}</b></div>
                  <div><span>Phone</span><b>{selected.customerPhone || customerProfile?.mobileNumber || '—'}</b></div>
                  <div><span>KYC status</span><b>{selected.kycStatus || '—'}</b></div>
                  <div><span>Requested amount</span><b>{money(selected.requestedAmount)}</b></div>
                  <div><span>Loan purpose</span><b>{selected.purpose || '—'}</b></div>
                  <div><span>Tenure</span><b>{selected.tenureMonths} months</b></div>
                  <div><span>Employment</span><b>{selected.employmentType || 'Not submitted'}</b></div>
                  <div><span>Monthly income</span><b>{money(selected.monthlyIncome)}</b></div>
                  <div><span>Existing EMI</span><b>{money(selected.existingMonthlyEmi)}</b></div>
                  <div><span>Employer / business</span><b>{selected.employerName || selected.businessName || '—'}</b></div>
                  {selected.designation && <div><span>Designation</span><b>{selected.designation}</b></div>}
                  {selected.workExperienceYears != null && <div><span>Work experience</span><b>{selected.workExperienceYears} years</b></div>}
                  {selected.businessType && <div><span>Business type</span><b>{selected.businessType}</b></div>}
                  {selected.businessVintageYears != null && <div><span>Business vintage</span><b>{selected.businessVintageYears} years</b></div>}
                  {selected.businessAddress && <div><span>Business address</span><b>{selected.businessAddress}</b></div>}
                  {selected.businessRegistrationNumber && <div><span>Registration number</span><b>{selected.businessRegistrationNumber}</b></div>}
                  {selected.annualTurnover != null && <div><span>Annual turnover</span><b>{money(selected.annualTurnover)}</b></div>}
                  <div><span>Credit score</span><b>{selected.creditScore || 'Not assessed'}</b></div>
                  {selected.assessedFoirPercent != null && <div><span>FOIR</span><b>{selected.assessedFoirPercent}%</b></div>}
                  {selected.recommendation && <div><span>Officer recommendation</span><b>{selected.recommendation}</b></div>}
                  {selected.recommendationRemarks && <div><span>Officer remarks</span><b>{selected.recommendationRemarks}</b></div>}
                  {selected.recommendedAmount != null && <div><span>Proposed amount</span><b>{money(selected.recommendedAmount)}</b></div>}
                  {selected.recommendedInterestRate != null && <div><span>Proposed rate</span><b>{selected.recommendedInterestRate}%</b></div>}
                  {selected.recommendedTenureMonths != null && <div><span>Proposed tenure</span><b>{selected.recommendedTenureMonths} months</b></div>}
                  {selected.managerDecisionReason && <div><span>Manager decision reason</span><b>{selected.managerDecisionReason}</b></div>}
                </div>

                <section className="blm-subsection lo-profile-section">
                  <h4>Customer profile</h4>
                  {customerProfile ? <div className="lo-profile-layout">
                    <div className="lo-profile-main">
                      <ProfileCard title="Personal Information" subtitle="Basic demographic details" icon="▤" fields={[
                        ['Full name', customerProfile.name], ['Title', customerProfile.title], ['Date of birth', customerProfile.dateOfBirth],
                        ['Gender', customerProfile.gender], ['Marital status', customerProfile.maritalStatus],
                        ['Nationality', customerProfile.nationality], ['Language', customerProfile.language],
                      ]} />
                      <ProfileCard title="Contact Information" subtitle="Registered contact and addresses" icon="✉" fields={[
                        ['Email address', customerProfile.email], ['Mobile number', customerProfile.mobileNumber],
                        ['Alternate mobile', customerProfile.alternateMobileNumber], ['Permanent address', customerProfile.permanentAddress],
                        ['Permanent city', customerProfile.permanentCity], ['Permanent state', customerProfile.permanentState],
                        ['Permanent country', customerProfile.permanentCountry], ['Permanent PIN code', customerProfile.permanentPinCode],
                        ['Communication address', customerProfile.communicationAddress], ['Communication city', customerProfile.communicationCity],
                        ['Communication state', customerProfile.communicationState], ['Communication country', customerProfile.communicationCountry],
                        ['Communication PIN code', customerProfile.communicationPinCode],
                      ]} />
                      <ProfileCard title="Branch Information" subtitle="Customer home branch" icon="▣" fields={[
                        ['Branch name', customerProfile.branchName], ['Branch code', customerProfile.branchCode], ['IFSC code', customerProfile.ifscCode],
                      ]} />
                    </div>
                    <div className="lo-profile-side">
                      <ProfileCard title="Financial Details" subtitle="Income and employment" icon="▣" fields={[
                        ['Occupation', customerProfile.occupation], ['Annual income', customerProfile.annualIncome == null ? null : money(customerProfile.annualIncome)],
                        ['Source of income', customerProfile.sourceOfIncome], ['Opening balance', customerProfile.openingBalance == null ? null : money(customerProfile.openingBalance)],
                        ['Customer status', customerProfile.status], ['Created', customerProfile.createdAt],
                      ]} />
                      <ProfileCard title="Loan Application" subtitle="Requested credit and assessment" icon="₹" fields={[
                        ['Product ID', selected.productId], ['Requested amount', money(selected.requestedAmount)],
                        ['Loan purpose', selected.purpose],
                        ['Requested tenure', `${selected.tenureMonths} months`], ['Employment type', selected.employmentType],
                        ['Employer / business', selected.employerName || selected.businessName], ['Designation', selected.designation],
                        ['Work experience', selected.workExperienceYears == null ? null : `${selected.workExperienceYears} years`],
                        ['Business type', selected.businessType],
                        ['Business vintage', selected.businessVintageYears == null ? null : `${selected.businessVintageYears} years`],
                        ['Business address', selected.businessAddress], ['Registration number', selected.businessRegistrationNumber],
                        ['Annual turnover', selected.annualTurnover == null ? null : money(selected.annualTurnover)],
                        ['Monthly income', money(selected.monthlyIncome)], ['Existing monthly EMI', money(selected.existingMonthlyEmi)],
                        ['Credit score', selected.creditScore], ['Assessment FOIR', selected.assessedFoirPercent == null ? null : `${selected.assessedFoirPercent}%`],
                        ['Credit result', selected.creditPassed == null ? null : selected.creditPassed ? 'Passed' : 'Failed'],
                        ['Assigned officer', selected.assignedOfficerId], ['Recommendation', selected.recommendation],
                        ['Recommendation remarks', selected.recommendationRemarks], ['Proposed amount', selected.recommendedAmount == null ? null : money(selected.recommendedAmount)],
                        ['Proposed rate', selected.recommendedInterestRate == null ? null : `${selected.recommendedInterestRate}%`],
                        ['Proposed tenure', selected.recommendedTenureMonths == null ? null : `${selected.recommendedTenureMonths} months`],
                        ['Additional documents requested', selected.additionalDocumentsRequested],
                        ['Manager decision reason', selected.managerDecisionReason],
                        ['Application submitted', selected.createdAt],
                      ]} />
                    </div>
                  </div> : <p className="blm-muted">Customer profile is not available.</p>}
                </section>

                <section className="blm-subsection">
                  <h4>Document checklist</h4>
                  {(() => {
                    const uploadedTypes = new Set(documents.map((document) =>
                      String(document.documentType || '').toUpperCase().replace(/-/g, '_')))
                    const verifiedTypes = new Set(documents
                      .filter((document) => document.verified)
                      .map((document) => String(document.documentType || '').toUpperCase().replace(/-/g, '_')))
                    const checklist = [
                      ['Aadhaar', 'AADHAAR'],
                      ['PAN', 'PAN'],
                      ['Income proof', 'INCOME_PROOF'],
                    ]
                    const incomeProofUploaded = uploadedTypes.has('SALARY_SLIP')
                      || uploadedTypes.has('BANK_STATEMENT')
                    const incomeProofVerified = verifiedTypes.has('SALARY_SLIP')
                      || verifiedTypes.has('BANK_STATEMENT')
                    return (
                      <div className="blm-document-checklist">
                        {checklist.map(([label, type]) => {
                          const uploaded = type === 'INCOME_PROOF'
                            ? incomeProofUploaded
                            : uploadedTypes.has(type)
                          const verified = type === 'INCOME_PROOF'
                            ? incomeProofVerified
                            : verifiedTypes.has(type)
                          return (
                            <div className={verified ? 'verified' : uploaded ? 'uploaded' : 'missing'} key={type}>
                              <span>{verified ? '✓' : uploaded ? '•' : '!'}</span>
                              <b>{label}</b>
                              <small>{verified ? 'Verified' : uploaded ? 'Review required' : 'Missing'}</small>
                            </div>
                          )
                        })}
                      </div>
                    )
                  })()}
                  <h4 className="blm-supporting-heading">Supporting documents</h4>
                  {documents.length === 0 ? <p className="blm-muted">No documents uploaded yet.</p> : documents.map((document) => (
                    <div className="blm-document-row" key={document.id}>
                      <div><b>{statusLabel(document.documentType)}</b><small>{document.originalFileName || 'Uploaded document'} · {document.verified ? 'Verified' : 'Needs review'}</small></div>
                      <div className="blm-document-actions">
                        <button className="blm-button blm-button-light" disabled={busy === `download-${document.id}`} onClick={() => downloadDocument(document)}>{busy === `download-${document.id}` ? 'Loading…' : 'Preview document'}</button>
                        {canReviewApplications && !document.verified && ['SUBMITTED', 'DETAILS_SUBMITTED', 'ADDITIONAL_DOCUMENTS_REQUIRED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                          <>
                            <button className="blm-button blm-button-primary" disabled={busy === `document-${document.id}`} onClick={() => reviewDocument(document.id, true)}>Verify</button>
                            <button className="blm-button blm-button-danger" disabled={busy === `document-${document.id}`} onClick={() => reviewDocument(document.id, false)}>Reject</button>
                          </>
                        )}
                        {canReviewApplications && !document.verified && ['SUBMITTED', 'DETAILS_SUBMITTED', 'ADDITIONAL_DOCUMENTS_REQUIRED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                          <button className="blm-button blm-button-light" disabled={busy === `remove-document-${document.id}`} onClick={() => removeRejectedDocument(document.id)}>Remove rejected file</button>
                        )}
                      </div>
                    </div>
                  ))}
                </section>

                {canReviewApplications && ['DOCUMENTS_VERIFIED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Credit assessment</h4>
                    <p>Enter the credit score returned by the credit check, then run the assessment.</p>
                    <div className="blm-inline-form">
                      <label>Credit score<input type="number" min="300" max="900" value={creditScore} onChange={(e) => setCreditScore(e.target.value)} /></label>
                      <button className="blm-button blm-button-primary" disabled={busy === 'assessment'} onClick={runCreditAssessment}>{busy === 'assessment' ? 'Assessing…' : 'Run assessment'}</button>
                    </div>
                  </section>
                )}

                {canReviewApplications && selected.status === 'CREDIT_PASSED' && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Loan recommendation</h4>
                    <p>Recommend approval or rejection. Final approval is reserved for an authorized branch manager.</p>
                    <div className="blm-decision-grid">
                      <label>Recommendation<select value={recommendation.recommendation} onChange={(event) => setRecommendation({ ...recommendation, recommendation: event.target.value })}><option value="APPROVE">Recommend approval</option><option value="REJECT">Recommend rejection</option></select></label>
                      {recommendation.recommendation === 'APPROVE' && <>
                        <label>Proposed amount (₹)<input type="number" min="1" required value={recommendation.amount} onChange={(event) => setRecommendation({ ...recommendation, amount: event.target.value })} /></label>
                        <label>Annual rate (%)<input type="number" min="0.01" step="0.01" required value={recommendation.annualInterestRate} onChange={(event) => setRecommendation({ ...recommendation, annualInterestRate: event.target.value })} /></label>
                        <label>Tenure (months)<input type="number" min="1" required value={recommendation.tenureMonths} onChange={(event) => setRecommendation({ ...recommendation, tenureMonths: event.target.value })} /></label>
                      </>}
                      <label className="blm-field-wide">Review remarks<textarea rows="2" required value={recommendation.remarks} onChange={(event) => setRecommendation({ ...recommendation, remarks: event.target.value })} /></label>
                    </div>
                    <button className="blm-button blm-button-primary" disabled={busy === 'recommendation'} onClick={submitRecommendation}>{busy === 'recommendation' ? 'Sending…' : 'Send recommendation to manager'}</button>
                  </section>
                )}

                {isBranchManager && selected.status === 'RECOMMENDED' && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Branch manager decision</h4>
                    <p>Review the officer recommendation and record a reason for every decision.</p>
                    <div className="blm-decision-grid">
                      <label>Decision<select value={managerDecision.decision} onChange={(event) => setManagerDecision({ ...managerDecision, decision: event.target.value })}><option value="APPROVE" disabled={selected.recommendation === 'REJECT'}>Approve</option><option value="REJECT">Reject</option><option value="RETURN">Return for review</option></select></label>
                      {managerDecision.decision === 'APPROVE' && <>
                        <label>Approved amount (₹)<input type="number" min="1" value={managerDecision.amount} onChange={(event) => setManagerDecision({ ...managerDecision, amount: event.target.value })} /></label>
                        <label>Annual rate (%)<input type="number" min="0.01" step="0.01" value={managerDecision.annualInterestRate} onChange={(event) => setManagerDecision({ ...managerDecision, annualInterestRate: event.target.value })} /></label>
                        <label>Tenure (months)<input type="number" min="1" value={managerDecision.tenureMonths} onChange={(event) => setManagerDecision({ ...managerDecision, tenureMonths: event.target.value })} /></label>
                      </>}
                      <label className="blm-field-wide">Decision reason<textarea rows="2" required value={managerDecision.reason} onChange={(event) => setManagerDecision({ ...managerDecision, reason: event.target.value })} /></label>
                    </div>
                    <button className="blm-button blm-button-primary" disabled={busy === 'manager-decision'} onClick={submitManagerDecision}>Save manager decision</button>
                  </section>
                )}

                {canReviewApplications && !['OFFERED', 'OFFER_ACCEPTED', 'AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING', 'DISBURSED', 'CLOSED', 'REJECTED'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Application support</h4>
                    {isBranchManager && <div className="blm-inline-form">
                      <label>Assign / reassign officer ID<input value={officerId} onChange={(event) => setOfficerId(event.target.value)} placeholder="Officer user ID" /></label>
                      <button className="blm-button blm-button-light" disabled={!officerId || busy === 'assignment'} onClick={assignApplication}>Assign</button>
                    </div>}
                    {['DETAILS_SUBMITTED', 'DOCUMENTS_VERIFIED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                      <div className="blm-inline-form">
                        <label>Request additional documents<input value={requestedDocuments} onChange={(event) => setRequestedDocuments(event.target.value)} placeholder="List missing documents" /></label>
                        <button className="blm-button blm-button-light" disabled={!requestedDocuments || busy === 'additional-documents'} onClick={requestDocuments}>Request documents</button>
                      </div>
                    )}
                  </section>
                )}

                {selected.status === 'CREDIT_FAILED' && <div className="blm-result blm-result-bad">Credit assessment did not pass. The loan cannot be approved.</div>}
                {selected.status === 'OFFERED' && <div className="blm-result">Offer is available for the customer to accept or reject.</div>}
                {selected.status === 'OFFER_ACCEPTED' && <div className="blm-result">Customer accepted the offer. The agreement and KFS are ready in their dashboard.</div>}

                {canReviewApplications && ['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Verify agreement and beneficiary</h4>
                    <p>Confirm the accepted agreement and prepare a pending loan account using the customer's active savings or current account.</p>
                    <button className="blm-button blm-button-primary" disabled={busy === 'disbursement'} onClick={prepareDisbursement}>{busy === 'disbursement' ? 'Verifying…' : 'Verify & prepare disbursement'}</button>
                  </section>
                )}

                {loanAccount && (
                  <section className="blm-subsection">
                    <h4>Loan account and beneficiary</h4>
                    <div className="blm-facts">
                      <div><span>Loan account number</span><b>{loanAccount.id}</b></div>
                      <div><span>Beneficiary bank account</span><b>{loanAccount.bankAccountNumber}</b></div>
                      <div><span>Sanctioned principal</span><b>{money(loanAccount.principal)}</b></div>
                      <div><span>Monthly EMI</span><b>{money(loanAccount.monthlyEmi)}</b></div>
                      <div><span>Account status</span><b>{loanAccount.status || 'PENDING_DISBURSEMENT'}</b></div>
                    </div>
                    {selected.status === 'DISBURSEMENT_PENDING' && (
                      <div className="blm-action-box">
                        <label><input type="checkbox" checked={beneficiaryConfirmed} onChange={(event) => setBeneficiaryConfirmed(event.target.checked)} /> I verified the agreement and beneficiary account above.</label>
                        <button className="blm-button blm-button-primary" disabled={!beneficiaryConfirmed || busy === 'disbursement'} onClick={completeDisbursement}>{busy === 'disbursement' ? 'Transferring…' : 'Initiate fund transfer'}</button>
                      </div>
                    )}
                  </section>
                )}
                {selected.status === 'DISBURSED' && <div className="blm-result blm-result-good">Transfer confirmed. The loan account is active and the repayment schedule is available to the customer.</div>}

                {history.length > 0 && (
                  <section className="blm-subsection">
                    <h4>Application history</h4>
                    <ol className="blm-history">
                      {history.map((entry) => <li key={entry.id}><b>{statusLabel(entry.action)}</b><span>{entry.remarks || entry.currentStatus}</span><small>{entry.createdAt ? new Date(entry.createdAt).toLocaleString('en-IN') : '—'} · {entry.actorId || 'System'}</small></li>)}
                    </ol>
                  </section>
                )}
              </>
            )}
            <DocumentPreview file={previewFile} onClose={() => setPreviewFile(null)} />
          </section>
        </div>
      )}

      {tab === 'products' && canManageProducts && (
        <div className="blm-products-layout">
          <section className="blm-panel">
            <div className="blm-panel-heading"><div><h3>Create a loan product</h3><p>Products become visible to customers after saving.</p></div></div>
            <form className="blm-product-form" onSubmit={createProduct}>
              <label>Product name<input required value={productForm.name} onChange={(e) => setProductForm({ ...productForm, name: e.target.value })} /></label>
              <label className="blm-field-wide">Description<textarea rows="2" value={productForm.description} onChange={(e) => setProductForm({ ...productForm, description: e.target.value })} /></label>
              <label>Minimum amount (₹)<input type="number" min="1" required value={productForm.minimumAmount} onChange={(e) => setProductForm({ ...productForm, minimumAmount: e.target.value })} /></label>
              <label>Maximum amount (₹)<input type="number" min="1" required value={productForm.maximumAmount} onChange={(e) => setProductForm({ ...productForm, maximumAmount: e.target.value })} /></label>
              <label>Annual interest rate (%)<input type="number" min="0.01" max="100" step="0.01" required value={productForm.annualInterestRate} onChange={(e) => setProductForm({ ...productForm, annualInterestRate: e.target.value })} /></label>
              <label>Minimum tenure (months)<input type="number" min="1" max="480" required value={productForm.minimumTenureMonths} onChange={(e) => setProductForm({ ...productForm, minimumTenureMonths: e.target.value })} /></label>
              <label>Maximum tenure (months)<input type="number" min="1" max="480" required value={productForm.maximumTenureMonths} onChange={(e) => setProductForm({ ...productForm, maximumTenureMonths: e.target.value })} /></label>
              <label>Maximum FOIR (%)<input type="number" min="1" max="100" step="0.01" required value={productForm.maximumFoirPercent} onChange={(e) => setProductForm({ ...productForm, maximumFoirPercent: e.target.value })} /></label>
              <label>Minimum credit score<input type="number" min="300" max="900" required value={productForm.minimumCreditScore} onChange={(e) => setProductForm({ ...productForm, minimumCreditScore: e.target.value })} /></label>
              <div className="blm-product-submit"><button className="blm-button blm-button-primary" disabled={busy === 'product'}>{busy === 'product' ? 'Saving…' : 'Create product'}</button></div>
            </form>
          </section>
          <section className="blm-panel">
            <div className="blm-panel-heading"><div><h3>Available products</h3><p>Active offers customers can currently apply for.</p></div></div>
            {products.length === 0 ? <div className="blm-state">No active loan products.</div> : products.map((product) => (
              <article className="blm-product-card" key={product.id}>
                <div><h4>{product.name}</h4><span className="blm-product-rate">{product.annualInterestRate}% p.a.</span></div>
                <p>{product.description || 'No description'}</p>
                <small>{money(product.minimumAmount)}–{money(product.maximumAmount)} · {product.minimumTenureMonths}–{product.maximumTenureMonths} months · FOIR {product.maximumFoirPercent}% · Score {product.minimumCreditScore}+</small>
              </article>
            ))}
          </section>
        </div>
      )}
      </div>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import {
  assignLoanApplication,
  assessLoanCredit,
  createLoanProduct,
  decideLoanApplication,
  disburseLoan,
  getApplicationLoanAccount,
  getAssignedLoanApplications,
  getLoanApplications,
  getLoanApplicationReviewDetails,
  getLoanProducts,
  previewLoanDocument,
  recommendLoanApplication,
  deleteLoanDocument,
  requestAdditionalLoanDocuments,
  prepareLoanDisbursement,
  verifyLoanDocument,
  getStaffLoanPortfolio,
  getStaffLoanSchedule,
  getStaffLoanPayments,
} from '../../../../../services/loanApi'
import './BankLoanManagerPage.css'

function DocumentPreview({ file, onClose }) {
  const url = useMemo(() => (file ? URL.createObjectURL(file) : ''), [file])

  useEffect(() => {
    if (!url) return undefined
    return () => URL.revokeObjectURL(url)
  }, [url])

  if (!file) return null
  return (
    <div className="blm-preview-backdrop" role="presentation" onClick={onClose}>
      <section className="blm-preview-modal" role="dialog" aria-modal="true" aria-label="Loan document preview" onClick={(event) => event.stopPropagation()}>
        <div className="blm-preview-heading"><b>Document preview</b><button className="blm-button blm-button-light" onClick={onClose}>Close</button></div>
        {file.type.startsWith('image/') ? <img src={url} alt="Customer loan document" /> : <iframe title="Customer loan document" src={url} />}
      </section>
    </div>
  )
}

const money = (value) =>
  value == null
    ? '—'
    : new Intl.NumberFormat('en-IN', {
        style: 'currency',
        currency: 'INR',
        maximumFractionDigits: 2,
      }).format(Number(value))

const statusLabel = (value) => ({
  SUBMITTED: 'Submitted',
  DETAILS_SUBMITTED: 'Submitted',
  DOCUMENTS_VERIFIED: 'Under review',
  CREDIT_PASSED: 'Under review',
  CREDIT_FAILED: 'Credit assessment failed',
  RECOMMENDED: 'Pending manager approval',
  RETURNED_FOR_REVIEW: 'Returned for review',
  ADDITIONAL_DOCUMENTS_REQUIRED: 'Documents required',
  REJECTED: 'Rejected',
  OFFERED: 'Offer sent',
  OFFER_REJECTED: 'Offer declined',
  OFFER_ACCEPTED: 'Agreement pending',
  AGREEMENT_ACCEPTED: 'Disbursement pending',
  DISBURSEMENT_AUTHORIZED: 'Disbursement processing',
  DISBURSEMENT_PENDING: 'Transfer ready',
  DISBURSED: 'Disbursed',
  CLOSED: 'Closed',
}[value] || String(value || '').replace(/_/g, ' '))
const profileValue = (value) => {
  if (value == null || value === '') return '—'
  if (typeof value === 'object') return new Date(value).toLocaleDateString('en-IN')
  return String(value)
}

const daysWaiting = (createdAt) => {
  const submittedAt = createdAt ? new Date(createdAt).getTime() : NaN
  return Number.isFinite(submittedAt)
    ? Math.max(0, Math.floor((Date.now() - submittedAt) / 86_400_000))
    : null
}

const reviewableStatuses = [
  'SUBMITTED',
  'DETAILS_SUBMITTED',
  'ADDITIONAL_DOCUMENTS_REQUIRED',
  'RETURNED_FOR_REVIEW',
]
const actionableStatuses = [
  ...reviewableStatuses,
  'DOCUMENTS_VERIFIED',
  'CREDIT_PASSED',
  'AGREEMENT_ACCEPTED',
  'DISBURSEMENT_AUTHORIZED',
  'DISBURSEMENT_PENDING',
]

function ProfileCard({ title, subtitle, icon, fields }) {
  const visibleFields = fields.filter(([, value]) => value != null && value !== '')
  if (!visibleFields.length) return null
  return (
    <section className="lo-profile-card">
      <header>
        <span className="lo-profile-icon" aria-hidden="true">{icon}</span>
        <div><h3>{title}</h3><p>{subtitle}</p></div>
      </header>
      <div className="lo-profile-grid">
        {visibleFields.map(([label, value]) => (
          <div className="lo-profile-field" key={label}>
            <span>{label}</span>
            <b>{profileValue(value)}</b>
          </div>
        ))}
      </div>
    </section>
  )
}

export default function BankLoanManagerPage({
  onBack,
  standalone = false,
  canManageProducts = false,
  canProcessApplications = false,
  isBranchManager = false,
  currentUser,
  onSignOut,
}) {
  const [tab, setTab] = useState('applications')
  const [workspaceView, setWorkspaceView] = useState('dashboard')
  const [applicationFilter, setApplicationFilter] = useState('ALL')
  const [applicationSort, setApplicationSort] = useState('OLDEST')
  const [search, setSearch] = useState('')
  const [applications, setApplications] = useState([])
  const [products, setProducts] = useState([])
  const [selected, setSelected] = useState(null)
  const [documents, setDocuments] = useState([])
  const [customerProfile, setCustomerProfile] = useState(null)
  const [history, setHistory] = useState([])
  const [loanAccount, setLoanAccount] = useState(null)
  const [beneficiaryConfirmed, setBeneficiaryConfirmed] = useState(false)
  const [previewFile, setPreviewFile] = useState(null)
  const [recommendation, setRecommendation] = useState({
    recommendation: 'APPROVE',
    remarks: '',
    amount: '',
    annualInterestRate: '',
    tenureMonths: '',
  })
  const [managerDecision, setManagerDecision] = useState({
    decision: 'APPROVE',
    reason: '',
    amount: '',
    annualInterestRate: '',
    tenureMonths: '',
  })
  const [officerId, setOfficerId] = useState('')
  const [requestedDocuments, setRequestedDocuments] = useState('')
  const [productForm, setProductForm] = useState({
    name: '',
    description: '',
    minimumAmount: '50000',
    maximumAmount: '1000000',
    annualInterestRate: '12',
    minimumTenureMonths: '12',
    maximumTenureMonths: '60',
    maximumFoirPercent: '50',
    minimumCreditScore: '650',
  })
  const [creditScore, setCreditScore] = useState('700')
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState('')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [portfolio, setPortfolio] = useState([])
  const [portfolioSearch, setPortfolioSearch] = useState('')
  const [selectedLoan, setSelectedLoan] = useState(null)
  const [loanSchedule, setLoanSchedule] = useState([])
  const [loanPayments, setLoanPayments] = useState([])

  const loadApplications = async () => {
    const data = isBranchManager ? await getLoanApplications() : await getAssignedLoanApplications()
    setApplications(Array.isArray(data) ? data : [])
  }

  const loadProducts = async () => {
    const data = await getLoanProducts()
    setProducts(Array.isArray(data) ? data : [])
  }

  const loadPortfolio = async () => {
    const data = await getStaffLoanPortfolio()
    setPortfolio(Array.isArray(data) ? data : [])
  }

  const refresh = async () => {
    setError('')
    const tasks = [loadApplications(), loadPortfolio()]
    if (canManageProducts) tasks.push(loadProducts())
    await Promise.all(tasks)
  }

  useEffect(() => {
    let active = true
    const requests = [
      isBranchManager ? getLoanApplications() : getAssignedLoanApplications(),
      getStaffLoanPortfolio(),
    ]
    if (canManageProducts) requests.push(getLoanProducts())
    Promise.all(requests)
      .then(([applicationData, portfolioData, productData]) => {
        if (!active) return
        setApplications(Array.isArray(applicationData) ? applicationData : [])
        setPortfolio(Array.isArray(portfolioData) ? portfolioData : [])
        if (canManageProducts) setProducts(Array.isArray(productData) ? productData : [])
      })
      .catch((loadError) => {
        if (active) setError(loadError.message)
      })
      .finally(() => {
        if (active) setLoading(false)
      })

    const timer = window.setInterval(() => {
      loadPortfolio().catch((loadError) => setError(loadError.message))
    }, 30000)
    return () => {
      active = false
      window.clearInterval(timer)
    }
  }, [canManageProducts, isBranchManager])

  const openApplication = async (application) => {
    setBusy('details')
    setError('')
    setSelected(application)
    setCustomerProfile(null)
    setHistory([])
    setDocuments([])
    setLoanAccount(null)
    setBeneficiaryConfirmed(false)
    try {
      const [details, account] = await Promise.all([
        getLoanApplicationReviewDetails(application.id),
        getApplicationLoanAccount(application.id),
      ])
      setSelected(details.application)
      setCustomerProfile(details.customer)
      setDocuments(Array.isArray(details.documents) ? details.documents : [])
      setHistory(Array.isArray(details.history) ? details.history : [])
      setLoanAccount(account)
      const product = products.find((item) => item.id === details.application.productId)
      setRecommendation({
        recommendation: 'APPROVE',
        remarks: '',
        amount: String(details.application.requestedAmount ?? ''),
        annualInterestRate: String(product?.annualInterestRate ?? ''),
        tenureMonths: String(details.application.tenureMonths ?? ''),
      })
      setManagerDecision({
        decision: details.application.recommendation === 'REJECT' ? 'REJECT' : 'APPROVE',
        reason: '',
        amount: String(details.application.recommendedAmount ?? details.application.requestedAmount ?? ''),
        annualInterestRate: String(details.application.recommendedInterestRate ?? product?.annualInterestRate ?? ''),
        tenureMonths: String(details.application.recommendedTenureMonths ?? details.application.tenureMonths ?? ''),
      })
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const refreshSelected = async () => {
    if (!selected) return
    const [details, applicationData] = await Promise.all([
      getLoanApplicationReviewDetails(selected.id),
      isBranchManager ? getLoanApplications() : getAssignedLoanApplications(),
    ])
    const account = await getApplicationLoanAccount(selected.id)
    setSelected(details.application)
    setCustomerProfile(details.customer)
    setDocuments(Array.isArray(details.documents) ? details.documents : [])
    setHistory(Array.isArray(details.history) ? details.history : [])
    setApplications(Array.isArray(applicationData) ? applicationData : [])
    setLoanAccount(account)
    setBeneficiaryConfirmed(false)
  }

  const runAction = async (key, action, successMessage) => {
    if (!selected) return
    setBusy(key)
    setError('')
    setNotice('')
    try {
      await action()
      await refreshSelected()
      setNotice(successMessage)
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const reviewDocument = async (documentId, verified) => {
    await runAction(
      `document-${documentId}`,
      () => verifyLoanDocument(documentId, verified),
      verified ? 'Document marked as verified.' : 'Document verification rejected.'
    )
  }

  const removeRejectedDocument = (documentId) =>
    runAction(`remove-document-${documentId}`, () => deleteLoanDocument(documentId),
      'Rejected document removed. The customer can upload a corrected file.')

  const runCreditAssessment = () =>
    runAction(
      'assessment',
      () => assessLoanCredit(selected.id, Number(creditScore)),
      'Credit assessment completed.'
    )

  const submitRecommendation = () =>
    runAction('recommendation', () => recommendLoanApplication(selected.id, {
      recommendation: recommendation.recommendation,
      remarks: recommendation.remarks,
      ...(recommendation.recommendation === 'APPROVE' ? {
        amount: Number(recommendation.amount),
        annualInterestRate: Number(recommendation.annualInterestRate),
        tenureMonths: Number(recommendation.tenureMonths),
      } : {}),
    }), recommendation.recommendation === 'APPROVE'
      ? 'Approval recommendation sent to the branch manager.'
      : 'Rejection recommendation sent to the branch manager for final decision.')

  const submitManagerDecision = () =>
    runAction('manager-decision', () => decideLoanApplication(selected.id, {
      decision: managerDecision.decision,
      reason: managerDecision.reason,
      ...(managerDecision.decision === 'APPROVE' ? {
        amount: managerDecision.amount ? Number(managerDecision.amount) : null,
        annualInterestRate: managerDecision.annualInterestRate ? Number(managerDecision.annualInterestRate) : null,
        tenureMonths: managerDecision.tenureMonths ? Number(managerDecision.tenureMonths) : null,
      } : {}),
    }), 'Branch manager decision saved.')

  const assignApplication = () =>
    runAction('assignment', () => assignLoanApplication(selected.id, officerId), 'Application assigned.')

  const requestDocuments = () =>
    runAction('additional-documents', () => requestAdditionalLoanDocuments(selected.id, requestedDocuments),
      'Additional document request sent to the customer.')


  const prepareDisbursement = async () => {
    if (!selected) return
    setBusy('disbursement')
    setError('')
    setNotice('')
    try {
      await prepareLoanDisbursement(selected.id)
      await refreshSelected()
      setNotice('Agreement and beneficiary account verified. The loan account and repayment schedule are ready for transfer.')
    } catch (requestError) {
      setError(requestError.message)
      try {
        await refreshSelected()
      } catch {
        // Keep the original disbursement error visible.
      }
    } finally {
      setBusy('')
    }
  }

  const completeDisbursement = async () => {
    if (!selected || !beneficiaryConfirmed) return
    setBusy('disbursement')
    setError('')
    setNotice('')
    try {
      await disburseLoan(selected.id)
      await refreshSelected()
      setNotice('Transfer confirmed. The loan account is now active.')
    } catch (requestError) {
      setError(requestError.message)
      try {
        await refreshSelected()
      } catch {
        // Keep the original disbursement error visible.
      }
    } finally {
      setBusy('')
    }
  }

  const downloadDocument = async (document) => {
    setBusy(`download-${document.id}`)
    setError('')
    try {
      setPreviewFile(await previewLoanDocument(document.id))
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const createProduct = async (event) => {
    event.preventDefault()
    setBusy('product')
    setError('')
    setNotice('')
    try {
      await createLoanProduct({
        ...productForm,
        minimumAmount: Number(productForm.minimumAmount),
        maximumAmount: Number(productForm.maximumAmount),
        annualInterestRate: Number(productForm.annualInterestRate),
        minimumTenureMonths: Number(productForm.minimumTenureMonths),
        maximumTenureMonths: Number(productForm.maximumTenureMonths),
        maximumFoirPercent: Number(productForm.maximumFoirPercent),
        minimumCreditScore: Number(productForm.minimumCreditScore),
      })
      setProductForm((current) => ({ ...current, name: '', description: '' }))
      await loadProducts()
      setNotice('Loan product created. Customers can now view it.')
    } catch (requestError) {
      setError(requestError.message)
    } finally {
      setBusy('')
    }
  }

  const visibleApplications = applications.filter((application) => {
    const query = search.trim().toLowerCase()
    if (query && ![
      application.customerName,
      application.customerId,
      application.customerEmail,
      application.customerPhone,
      application.id,
      application.status,
      application.purpose,
    ].some((value) => String(value || '').toLowerCase().includes(query))) return false
    if (applicationFilter === 'PENDING_APPROVALS') return application.status === 'RECOMMENDED'
    if (applicationFilter === 'PENDING_REVIEW') return actionableStatuses.includes(application.status)
    if (applicationFilter === 'DOCUMENTS_PENDING') return reviewableStatuses.includes(application.status)
    if (applicationFilter === 'CREDIT_PENDING') return application.status === 'DOCUMENTS_VERIFIED'
    if (applicationFilter === 'RECOMMENDED') return application.status === 'RECOMMENDED'
    if (applicationFilter === 'DISBURSEMENT') return ['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING'].includes(application.status)
    return true
  }).sort((left, right) => {
    if (applicationSort === 'NEWEST') {
      return new Date(right.createdAt || 0) - new Date(left.createdAt || 0)
    }
    if (applicationSort === 'AMOUNT') {
      return Number(right.requestedAmount || 0) - Number(left.requestedAmount || 0)
    }
    return new Date(left.createdAt || 0) - new Date(right.createdAt || 0)
  })

  const dashboardMetrics = useMemo(() => {
    const count = (statuses) => applications.filter((application) => statuses.includes(application.status)).length
    if (!isBranchManager) {
      const oldest = applications
        .filter((application) => actionableStatuses.includes(application.status))
        .map((application) => daysWaiting(application.createdAt))
        .filter((days) => days != null)
      return [
        ['Assigned applications', applications.length, 'ALL'],
        ['Submitted applications', count(['SUBMITTED', 'DETAILS_SUBMITTED']), 'DOCUMENTS_PENDING'],
        ['Pending review', count(actionableStatuses), 'PENDING_REVIEW'],
        ['Documents pending', count(reviewableStatuses), 'DOCUMENTS_PENDING'],
        ['Credit assessment pending', count(['DOCUMENTS_VERIFIED']), 'CREDIT_PENDING'],
        ['Recommended for approval', applications.filter((application) => application.status === 'RECOMMENDED' && application.recommendation === 'APPROVE').length, 'RECOMMENDED'],
        ['Recommended for rejection', applications.filter((application) => application.status === 'RECOMMENDED' && application.recommendation === 'REJECT').length, 'RECOMMENDED'],
        ['Disbursement queue', count(['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING']), 'DISBURSEMENT'],
        ['Oldest open case', oldest.length ? `${Math.max(...oldest)} days` : '—', 'PENDING_REVIEW'],
      ]
    }

    const approvedStatuses = ['OFFERED', 'OFFER_ACCEPTED', 'AGREEMENT_ACCEPTED', 'DISBURSEMENT_PENDING', 'DISBURSED', 'CLOSED']
    const sanctionedAmount = applications
      .filter((application) => approvedStatuses.includes(application.status))
      .reduce((total, application) => total + Number(application.recommendedAmount ?? application.requestedAmount ?? 0), 0)
    return [
      ['Total applications', applications.length, 'ALL'],
      ['Pending approvals', count(['RECOMMENDED']), 'PENDING_APPROVALS'],
      ['Approved loans', count(approvedStatuses), 'ALL'],
      ['Rejected', count(['REJECTED', 'OFFER_REJECTED']), 'ALL'],
      ['Returned for review', count(['RETURNED_FOR_REVIEW']), 'PENDING_REVIEW'],
      ['Disbursement pending', count(['AGREEMENT_ACCEPTED', 'DISBURSEMENT_PENDING']), 'DISBURSEMENT'],
      ['Disbursed', count(['DISBURSED', 'CLOSED']), 'ALL'],
      ['Sanctioned amount', money(sanctionedAmount), 'ALL'],
    ]
  }, [applications, isBranchManager])

  const staffName = currentUser?.name || currentUser?.fullName || currentUser?.email || 'Loan Officer'
  const initials = String(staffName).split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join('') || 'LO'
  const canReviewApplications = canProcessApplications || isBranchManager

  if (loading) return <div className="blm-state">Loading loan workspace…</div>

  return (
    <div className={`blm-page ${isBranchManager ? 'blm-manager' : ''} ${standalone ? `blm-standalone lo-shell ${selected ? 'lo-has-selection' : ''}` : ''}`}>
      {standalone && (
        <aside className="lo-sidebar">
          <div className="lo-brand">
            <span className="lo-brand-mark">N</span>
            <span><b>NOVA BANK</b><small>Your Trust. Our Priority.</small></span>
          </div>
          <div className="lo-staff">
            <span className="lo-avatar">{initials}</span>
            <div><b>{staffName}</b><small>Loan Officer</small><span><i />Online</span></div>
          </div>
          <div className="lo-nav-label">Workspace</div>
          <nav className="lo-nav" aria-label="Loan officer workspace">
            <button className={tab === 'applications' && workspaceView === 'dashboard' && !selected ? 'active' : ''} onClick={() => { setTab('applications'); setWorkspaceView('dashboard'); setApplicationFilter('ALL'); setSelected(null) }}><span>▦</span>Dashboard</button>
            <button className={tab === 'applications' && workspaceView === 'assigned' && !selected ? 'active' : ''} onClick={() => { setTab('applications'); setWorkspaceView('assigned'); setApplicationFilter('PENDING_REVIEW'); setSelected(null) }}><span>▤</span>Assigned Applications</button>
            {canManageProducts && <button className={tab === 'products' ? 'active' : ''} onClick={() => { setTab('products'); setSelected(null) }}><span>＋</span>Loan Products</button>}
          </nav>
          <div className="lo-sidebar-bottom">
            <button onClick={onSignOut}><span>⏻</span>Sign out</button>
            <small><i />Signed in securely</small>
          </div>
        </aside>
      )}

      <div className={standalone ? 'lo-main' : ''}>
      {standalone && (
        <header className="lo-topbar">
          <div><b>{selected ? 'Application details' : tab === 'products' ? 'Loan products' : 'Loan Officer Dashboard'}</b><span>{selected ? `Reviewing ${selected.id}` : 'Application processing & customer verification'}</span></div>
          <div className="lo-topbar-actions"><button className="blm-button blm-button-light" onClick={() => refresh().catch((requestError) => setError(requestError.message))}>Refresh</button><div className="lo-account"><span>{initials}</span><b>{staffName}</b></div></div>
        </header>
      )}
      <div className={standalone ? 'lo-content' : ''}>
      <header className="blm-hero">
        <div>
          <span className="blm-eyebrow">LOAN OPERATIONS</span>
          <h2>{tab === 'products' ? 'Loan products' : isBranchManager ? 'Branch loan approvals' : 'Loan officer workspace'}</h2>
          <p>{isBranchManager ? 'Review recommendations, make authorized decisions, and monitor branch loan processing.' : 'Verify applicant details and documents, assess credit, and recommend a decision.'}</p>
        </div>
        <div className="blm-hero-actions">
          {onBack && <button className="blm-button blm-button-light" onClick={onBack}>Back to dashboard</button>}
          <button className="blm-button blm-button-light" onClick={() => refresh().catch((e) => setError(e.message))}>Refresh</button>
        </div>
      </header>

      {error && <div className="blm-alert blm-alert-error" role="alert">{error}</div>}
      {notice && <div className="blm-alert blm-alert-success" role="status">{notice}</div>}

      <section className="blm-stat-grid" aria-label={isBranchManager ? 'Branch loan statistics' : 'Assigned loan statistics'}>
        {dashboardMetrics.map(([label, value, filter]) => (
          <button
            type="button"
            className={`blm-stat-card ${applicationFilter === filter && tab === 'applications' ? 'active' : ''}`}
            key={label}
            onClick={() => {
              setTab('applications')
              setApplicationFilter(filter)
              setWorkspaceView('assigned')
              setSelected(null)
            }}
          >
            <span>{label}</span><b>{value}</b><small>Open queue →</small>
          </button>
        ))}
      </section>

      <nav className="blm-tabs" aria-label="Loan workspace">
        <button className={tab === 'applications' ? 'active' : ''} onClick={() => setTab('applications')}>
          Applications <span>{applications.length}</span>
        </button>
        {canManageProducts && (
          <button className={tab === 'products' ? 'active' : ''} onClick={() => setTab('products')}>
            Products
          </button>
        )}
      </nav>

      {tab === 'applications' && (
        <div className={`blm-workspace ${selected ? 'blm-has-selection' : ''} ${standalone ? 'lo-workspace' : ''}`}>
          <section className="blm-panel blm-queue-panel">
            <div className="blm-panel-heading">
              <div className="blm-queue-title"><span className="blm-eyebrow">WORK QUEUE · {visibleApplications.length} CASES</span><h3>{applicationFilter === 'PENDING_APPROVALS' ? 'Pending approvals' : applicationFilter === 'DOCUMENTS_PENDING' ? 'Document verification' : applicationFilter === 'CREDIT_PENDING' ? 'Ready for credit assessment' : applicationFilter === 'RECOMMENDED' ? 'Manager recommendations' : applicationFilter === 'DISBURSEMENT' ? 'Disbursement queue' : applicationFilter === 'PENDING_REVIEW' ? 'Cases needing action' : standalone ? 'Assigned applications' : 'Loan applications'}</h3><p>{standalone ? 'Prioritized by oldest case first. Open an application to complete verification and review.' : 'Select an application to review customer and loan information.'}</p></div>
              <input className="lo-search" aria-label="Search applications" placeholder="Search customer or application" value={search} onChange={(event) => setSearch(event.target.value)} />
              <select aria-label="Filter loan applications" value={applicationFilter} onChange={(event) => setApplicationFilter(event.target.value)}>
                <option value="ALL">All applications</option>
                <option value="PENDING_REVIEW">Pending review</option>
                <option value="DOCUMENTS_PENDING">Documents pending</option>
                <option value="CREDIT_PENDING">Credit assessment</option>
                <option value="RECOMMENDED">Recommendations</option>
                <option value="DISBURSEMENT">Disbursement queue</option>
                {isBranchManager && <option value="PENDING_APPROVALS">Pending approvals</option>}
              </select>
              <select aria-label="Sort applications" value={applicationSort} onChange={(event) => setApplicationSort(event.target.value)}>
                <option value="OLDEST">Oldest first</option>
                <option value="NEWEST">Newest first</option>
                <option value="AMOUNT">Highest amount</option>
              </select>
            </div>
            {visibleApplications.length === 0 ? (
              <div className="blm-state">
                <span>{search ? 'No applications match your search.' : applicationFilter === 'ALL' ? 'No applications are available.' : 'There are no applications in this queue right now.'}</span>
                {(search || applicationFilter !== 'ALL') && (
                  <button
                    className="blm-button blm-button-light"
                    onClick={() => { setSearch(''); setApplicationFilter('ALL') }}
                  >
                    Show all applications
                  </button>
                )}
              </div>
            ) : (
              <div className="blm-application-list">
                {visibleApplications.map((application) => (
                  <button className={`blm-application-row ${selected?.id === application.id ? 'selected' : ''}`} key={application.id} onClick={() => openApplication(application)}>
                    <span className="blm-row-main">
                      <b>{application.customerName || application.customerId}</b>
                      <small>{money(application.requestedAmount)} · {application.tenureMonths} months · {application.purpose || 'Purpose not specified'}</small>
                      <small>{application.customerPhone || application.customerEmail || application.customerId}</small>
                    </span>
                    <span className="blm-row-secondary">
                      <b className={`blm-queue-status blm-queue-status-${String(application.status).toLowerCase()}`}>{statusLabel(application.status)}</b>
                      <small>{application.id}</small>
                      <small className={daysWaiting(application.createdAt) >= 3 && actionableStatuses.includes(application.status) ? 'blm-case-aged' : ''}>
                        {daysWaiting(application.createdAt) == null ? 'Date unavailable' : daysWaiting(application.createdAt) === 0 ? 'Received today' : `Waiting ${daysWaiting(application.createdAt)}d`}
                        {daysWaiting(application.createdAt) >= 3 && actionableStatuses.includes(application.status) ? ' · Review due' : ''}
                      </small>
                    </span>
                  </button>
                ))}
              </div>
            )}
          </section>

          <section className="blm-panel blm-detail-panel">
            {!selected ? <div className="blm-state">Select an application to see the review steps.</div> : busy === 'details' ? <div className="blm-state">Loading application details…</div> : (
              <>
                <div className="blm-panel-heading blm-detail-heading">
                  <button className="blm-button blm-button-light" onClick={() => setSelected(null)}>← Back to applications</button>
                  <div><span className="blm-eyebrow">APPLICATION · {selected.productId ? `PRODUCT #${selected.productId}` : ''}</span><h3>{selected.customerName || customerProfile?.name || selected.customerId}</h3><p>Customer ID: <b>{selected.customerId || '—'}</b> · Application: {selected.id}</p></div>
                  <span className={`lo-status lo-status-${String(selected.status).toLowerCase()}`}>{statusLabel(selected.status)}</span>
                </div>
                <div className="lo-customer-strip">
                  <div><span></span><section><small>CUSTOMER NAME</small><b>{customerProfile?.name || selected.customerName || '—'}</b></section></div>
                  <div><span>✉</span><section><small>EMAIL ADDRESS</small><b>{customerProfile?.email || selected.customerEmail || '—'}</b></section></div>
                  <div><span>▦</span><section><small>MOBILE NUMBER</small><b>{customerProfile?.mobileNumber || selected.customerPhone || '—'}</b></section></div>
                  <div><span>◈</span><section><small>KYC STATUS</small><b>{selected.kycStatus || '—'}</b></section></div>
                </div>
                <div className="blm-facts">
                  <div><span>Application ID</span><b>{selected.id}</b></div>
                  <div><span>Customer ID</span><b>{selected.customerId || '—'}</b></div>
                  <div><span>Email</span><b>{selected.customerEmail || customerProfile?.email || '—'}</b></div>
                  <div><span>Phone</span><b>{selected.customerPhone || customerProfile?.mobileNumber || '—'}</b></div>
                  <div><span>KYC status</span><b>{selected.kycStatus || '—'}</b></div>
                  <div><span>Requested amount</span><b>{money(selected.requestedAmount)}</b></div>
                  <div><span>Loan purpose</span><b>{selected.purpose || '—'}</b></div>
                  <div><span>Tenure</span><b>{selected.tenureMonths} months</b></div>
                  <div><span>Employment</span><b>{selected.employmentType || 'Not submitted'}</b></div>
                  <div><span>Monthly income</span><b>{money(selected.monthlyIncome)}</b></div>
                  <div><span>Existing EMI</span><b>{money(selected.existingMonthlyEmi)}</b></div>
                  <div><span>Employer / business</span><b>{selected.employerName || selected.businessName || '—'}</b></div>
                  {selected.designation && <div><span>Designation</span><b>{selected.designation}</b></div>}
                  {selected.workExperienceYears != null && <div><span>Work experience</span><b>{selected.workExperienceYears} years</b></div>}
                  {selected.businessType && <div><span>Business type</span><b>{selected.businessType}</b></div>}
                  {selected.businessVintageYears != null && <div><span>Business vintage</span><b>{selected.businessVintageYears} years</b></div>}
                  {selected.businessAddress && <div><span>Business address</span><b>{selected.businessAddress}</b></div>}
                  {selected.businessRegistrationNumber && <div><span>Registration number</span><b>{selected.businessRegistrationNumber}</b></div>}
                  {selected.annualTurnover != null && <div><span>Annual turnover</span><b>{money(selected.annualTurnover)}</b></div>}
                  <div><span>Credit score</span><b>{selected.creditScore || 'Not assessed'}</b></div>
                  {selected.assessedFoirPercent != null && <div><span>FOIR</span><b>{selected.assessedFoirPercent}%</b></div>}
                  {selected.recommendation && <div><span>Officer recommendation</span><b>{selected.recommendation}</b></div>}
                  {selected.recommendationRemarks && <div><span>Officer remarks</span><b>{selected.recommendationRemarks}</b></div>}
                  {selected.recommendedAmount != null && <div><span>Proposed amount</span><b>{money(selected.recommendedAmount)}</b></div>}
                  {selected.recommendedInterestRate != null && <div><span>Proposed rate</span><b>{selected.recommendedInterestRate}%</b></div>}
                  {selected.recommendedTenureMonths != null && <div><span>Proposed tenure</span><b>{selected.recommendedTenureMonths} months</b></div>}
                  {selected.managerDecisionReason && <div><span>Manager decision reason</span><b>{selected.managerDecisionReason}</b></div>}
                </div>

                <section className="blm-subsection lo-profile-section">
                  <h4>Customer profile</h4>
                  {customerProfile ? <div className="lo-profile-layout">
                    <div className="lo-profile-main">
                      <ProfileCard title="Personal Information" subtitle="Basic demographic details" icon="▤" fields={[
                        ['Full name', customerProfile.name], ['Title', customerProfile.title], ['Date of birth', customerProfile.dateOfBirth],
                        ['Gender', customerProfile.gender], ['Marital status', customerProfile.maritalStatus],
                        ['Nationality', customerProfile.nationality], ['Language', customerProfile.language],
                      ]} />
                      <ProfileCard title="Contact Information" subtitle="Registered contact and addresses" icon="✉" fields={[
                        ['Email address', customerProfile.email], ['Mobile number', customerProfile.mobileNumber],
                        ['Alternate mobile', customerProfile.alternateMobileNumber], ['Permanent address', customerProfile.permanentAddress],
                        ['Permanent city', customerProfile.permanentCity], ['Permanent state', customerProfile.permanentState],
                        ['Permanent country', customerProfile.permanentCountry], ['Permanent PIN code', customerProfile.permanentPinCode],
                        ['Communication address', customerProfile.communicationAddress], ['Communication city', customerProfile.communicationCity],
                        ['Communication state', customerProfile.communicationState], ['Communication country', customerProfile.communicationCountry],
                        ['Communication PIN code', customerProfile.communicationPinCode],
                      ]} />
                      <ProfileCard title="Branch Information" subtitle="Customer home branch" icon="▣" fields={[
                        ['Branch name', customerProfile.branchName], ['Branch code', customerProfile.branchCode], ['IFSC code', customerProfile.ifscCode],
                      ]} />
                    </div>
                    <div className="lo-profile-side">
                      <ProfileCard title="Financial Details" subtitle="Income and employment" icon="▣" fields={[
                        ['Occupation', customerProfile.occupation], ['Annual income', customerProfile.annualIncome == null ? null : money(customerProfile.annualIncome)],
                        ['Source of income', customerProfile.sourceOfIncome], ['Opening balance', customerProfile.openingBalance == null ? null : money(customerProfile.openingBalance)],
                        ['Customer status', customerProfile.status], ['Created', customerProfile.createdAt],
                      ]} />
                      <ProfileCard title="Loan Application" subtitle="Requested credit and assessment" icon="₹" fields={[
                        ['Product ID', selected.productId], ['Requested amount', money(selected.requestedAmount)],
                        ['Loan purpose', selected.purpose],
                        ['Requested tenure', `${selected.tenureMonths} months`], ['Employment type', selected.employmentType],
                        ['Employer / business', selected.employerName || selected.businessName], ['Designation', selected.designation],
                        ['Work experience', selected.workExperienceYears == null ? null : `${selected.workExperienceYears} years`],
                        ['Business type', selected.businessType],
                        ['Business vintage', selected.businessVintageYears == null ? null : `${selected.businessVintageYears} years`],
                        ['Business address', selected.businessAddress], ['Registration number', selected.businessRegistrationNumber],
                        ['Annual turnover', selected.annualTurnover == null ? null : money(selected.annualTurnover)],
                        ['Monthly income', money(selected.monthlyIncome)], ['Existing monthly EMI', money(selected.existingMonthlyEmi)],
                        ['Credit score', selected.creditScore], ['Assessment FOIR', selected.assessedFoirPercent == null ? null : `${selected.assessedFoirPercent}%`],
                        ['Credit result', selected.creditPassed == null ? null : selected.creditPassed ? 'Passed' : 'Failed'],
                        ['Assigned officer', selected.assignedOfficerId], ['Recommendation', selected.recommendation],
                        ['Recommendation remarks', selected.recommendationRemarks], ['Proposed amount', selected.recommendedAmount == null ? null : money(selected.recommendedAmount)],
                        ['Proposed rate', selected.recommendedInterestRate == null ? null : `${selected.recommendedInterestRate}%`],
                        ['Proposed tenure', selected.recommendedTenureMonths == null ? null : `${selected.recommendedTenureMonths} months`],
                        ['Additional documents requested', selected.additionalDocumentsRequested],
                        ['Manager decision reason', selected.managerDecisionReason],
                        ['Application submitted', selected.createdAt],
                      ]} />
                    </div>
                  </div> : <p className="blm-muted">Customer profile is not available.</p>}
                </section>

                <section className="blm-subsection">
                  <h4>Document checklist</h4>
                  {(() => {
                    const uploadedTypes = new Set(documents.map((document) =>
                      String(document.documentType || '').toUpperCase().replace(/-/g, '_')))
                    const verifiedTypes = new Set(documents
                      .filter((document) => document.verified)
                      .map((document) => String(document.documentType || '').toUpperCase().replace(/-/g, '_')))
                    const checklist = [
                      ['Aadhaar', 'AADHAAR'],
                      ['PAN', 'PAN'],
                      ['Income proof', 'INCOME_PROOF'],
                    ]
                    const incomeProofUploaded = uploadedTypes.has('SALARY_SLIP')
                      || uploadedTypes.has('BANK_STATEMENT')
                    const incomeProofVerified = verifiedTypes.has('SALARY_SLIP')
                      || verifiedTypes.has('BANK_STATEMENT')
                    return (
                      <div className="blm-document-checklist">
                        {checklist.map(([label, type]) => {
                          const uploaded = type === 'INCOME_PROOF'
                            ? incomeProofUploaded
                            : uploadedTypes.has(type)
                          const verified = type === 'INCOME_PROOF'
                            ? incomeProofVerified
                            : verifiedTypes.has(type)
                          return (
                            <div className={verified ? 'verified' : uploaded ? 'uploaded' : 'missing'} key={type}>
                              <span>{verified ? '✓' : uploaded ? '•' : '!'}</span>
                              <b>{label}</b>
                              <small>{verified ? 'Verified' : uploaded ? 'Review required' : 'Missing'}</small>
                            </div>
                          )
                        })}
                      </div>
                    )
                  })()}
                  <h4 className="blm-supporting-heading">Supporting documents</h4>
                  {documents.length === 0 ? <p className="blm-muted">No documents uploaded yet.</p> : documents.map((document) => (
                    <div className="blm-document-row" key={document.id}>
                      <div><b>{statusLabel(document.documentType)}</b><small>{document.originalFileName || 'Uploaded document'} · {document.verified ? 'Verified' : 'Needs review'}</small></div>
                      <div className="blm-document-actions">
                        <button className="blm-button blm-button-light" disabled={busy === `download-${document.id}`} onClick={() => downloadDocument(document)}>{busy === `download-${document.id}` ? 'Loading…' : 'Preview document'}</button>
                        {canReviewApplications && !document.verified && ['SUBMITTED', 'DETAILS_SUBMITTED', 'ADDITIONAL_DOCUMENTS_REQUIRED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                          <>
                            <button className="blm-button blm-button-primary" disabled={busy === `document-${document.id}`} onClick={() => reviewDocument(document.id, true)}>Verify</button>
                            <button className="blm-button blm-button-danger" disabled={busy === `document-${document.id}`} onClick={() => reviewDocument(document.id, false)}>Reject</button>
                          </>
                        )}
                        {canReviewApplications && !document.verified && ['SUBMITTED', 'DETAILS_SUBMITTED', 'ADDITIONAL_DOCUMENTS_REQUIRED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                          <button className="blm-button blm-button-light" disabled={busy === `remove-document-${document.id}`} onClick={() => removeRejectedDocument(document.id)}>Remove rejected file</button>
                        )}
                      </div>
                    </div>
                  ))}
                </section>

                {canReviewApplications && ['DOCUMENTS_VERIFIED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Credit assessment</h4>
                    <p>Enter the credit score returned by the credit check, then run the assessment.</p>
                    <div className="blm-inline-form">
                      <label>Credit score<input type="number" min="300" max="900" value={creditScore} onChange={(e) => setCreditScore(e.target.value)} /></label>
                      <button className="blm-button blm-button-primary" disabled={busy === 'assessment'} onClick={runCreditAssessment}>{busy === 'assessment' ? 'Assessing…' : 'Run assessment'}</button>
                    </div>
                  </section>
                )}

                {canReviewApplications && selected.status === 'CREDIT_PASSED' && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Loan recommendation</h4>
                    <p>Recommend approval or rejection. Final approval is reserved for an authorized branch manager.</p>
                    <div className="blm-decision-grid">
                      <label>Recommendation<select value={recommendation.recommendation} onChange={(event) => setRecommendation({ ...recommendation, recommendation: event.target.value })}><option value="APPROVE">Recommend approval</option><option value="REJECT">Recommend rejection</option></select></label>
                      {recommendation.recommendation === 'APPROVE' && <>
                        <label>Proposed amount (₹)<input type="number" min="1" required value={recommendation.amount} onChange={(event) => setRecommendation({ ...recommendation, amount: event.target.value })} /></label>
                        <label>Annual rate (%)<input type="number" min="0.01" step="0.01" required value={recommendation.annualInterestRate} onChange={(event) => setRecommendation({ ...recommendation, annualInterestRate: event.target.value })} /></label>
                        <label>Tenure (months)<input type="number" min="1" required value={recommendation.tenureMonths} onChange={(event) => setRecommendation({ ...recommendation, tenureMonths: event.target.value })} /></label>
                      </>}
                      <label className="blm-field-wide">Review remarks<textarea rows="2" required value={recommendation.remarks} onChange={(event) => setRecommendation({ ...recommendation, remarks: event.target.value })} /></label>
                    </div>
                    <button className="blm-button blm-button-primary" disabled={busy === 'recommendation'} onClick={submitRecommendation}>{busy === 'recommendation' ? 'Sending…' : 'Send recommendation to manager'}</button>
                  </section>
                )}

                {isBranchManager && selected.status === 'RECOMMENDED' && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Branch manager decision</h4>
                    <p>Review the officer recommendation and record a reason for every decision.</p>
                    <div className="blm-decision-grid">
                      <label>Decision<select value={managerDecision.decision} onChange={(event) => setManagerDecision({ ...managerDecision, decision: event.target.value })}><option value="APPROVE" disabled={selected.recommendation === 'REJECT'}>Approve</option><option value="REJECT">Reject</option><option value="RETURN">Return for review</option></select></label>
                      {managerDecision.decision === 'APPROVE' && <>
                        <label>Approved amount (₹)<input type="number" min="1" value={managerDecision.amount} onChange={(event) => setManagerDecision({ ...managerDecision, amount: event.target.value })} /></label>
                        <label>Annual rate (%)<input type="number" min="0.01" step="0.01" value={managerDecision.annualInterestRate} onChange={(event) => setManagerDecision({ ...managerDecision, annualInterestRate: event.target.value })} /></label>
                        <label>Tenure (months)<input type="number" min="1" value={managerDecision.tenureMonths} onChange={(event) => setManagerDecision({ ...managerDecision, tenureMonths: event.target.value })} /></label>
                      </>}
                      <label className="blm-field-wide">Decision reason<textarea rows="2" required value={managerDecision.reason} onChange={(event) => setManagerDecision({ ...managerDecision, reason: event.target.value })} /></label>
                    </div>
                    <button className="blm-button blm-button-primary" disabled={busy === 'manager-decision'} onClick={submitManagerDecision}>Save manager decision</button>
                  </section>
                )}

                {canReviewApplications && !['OFFERED', 'OFFER_ACCEPTED', 'AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED', 'DISBURSEMENT_PENDING', 'DISBURSED', 'CLOSED', 'REJECTED'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Application support</h4>
                    {isBranchManager && <div className="blm-inline-form">
                      <label>Assign / reassign officer ID<input value={officerId} onChange={(event) => setOfficerId(event.target.value)} placeholder="Officer user ID" /></label>
                      <button className="blm-button blm-button-light" disabled={!officerId || busy === 'assignment'} onClick={assignApplication}>Assign</button>
                    </div>}
                    {['DETAILS_SUBMITTED', 'DOCUMENTS_VERIFIED', 'RETURNED_FOR_REVIEW'].includes(selected.status) && (
                      <div className="blm-inline-form">
                        <label>Request additional documents<input value={requestedDocuments} onChange={(event) => setRequestedDocuments(event.target.value)} placeholder="List missing documents" /></label>
                        <button className="blm-button blm-button-light" disabled={!requestedDocuments || busy === 'additional-documents'} onClick={requestDocuments}>Request documents</button>
                      </div>
                    )}
                  </section>
                )}

                {selected.status === 'CREDIT_FAILED' && <div className="blm-result blm-result-bad">Credit assessment did not pass. The loan cannot be approved.</div>}
                {selected.status === 'OFFERED' && <div className="blm-result">Offer is available for the customer to accept or reject.</div>}
                {selected.status === 'OFFER_ACCEPTED' && <div className="blm-result">Customer accepted the offer. The agreement and KFS are ready in their dashboard.</div>}

                {canReviewApplications && ['AGREEMENT_ACCEPTED', 'DISBURSEMENT_AUTHORIZED'].includes(selected.status) && (
                  <section className="blm-subsection blm-action-box">
                    <h4>Verify agreement and beneficiary</h4>
                    <p>Confirm the accepted agreement and prepare a pending loan account using the customer's active savings or current account.</p>
                    <button className="blm-button blm-button-primary" disabled={busy === 'disbursement'} onClick={prepareDisbursement}>{busy === 'disbursement' ? 'Verifying…' : 'Verify & prepare disbursement'}</button>
                  </section>
                )}

                {loanAccount && (
                  <section className="blm-subsection">
                    <h4>Loan account and beneficiary</h4>
                    <div className="blm-facts">
                      <div><span>Loan account number</span><b>{loanAccount.id}</b></div>
                      <div><span>Beneficiary bank account</span><b>{loanAccount.bankAccountNumber}</b></div>
                      <div><span>Sanctioned principal</span><b>{money(loanAccount.principal)}</b></div>
                      <div><span>Monthly EMI</span><b>{money(loanAccount.monthlyEmi)}</b></div>
                      <div><span>Account status</span><b>{loanAccount.status || 'PENDING_DISBURSEMENT'}</b></div>
                    </div>
                    {selected.status === 'DISBURSEMENT_PENDING' && (
                      <div className="blm-action-box">
                        <label><input type="checkbox" checked={beneficiaryConfirmed} onChange={(event) => setBeneficiaryConfirmed(event.target.checked)} /> I verified the agreement and beneficiary account above.</label>
                        <button className="blm-button blm-button-primary" disabled={!beneficiaryConfirmed || busy === 'disbursement'} onClick={completeDisbursement}>{busy === 'disbursement' ? 'Transferring…' : 'Initiate fund transfer'}</button>
                      </div>
                    )}
                  </section>
                )}
                {selected.status === 'DISBURSED' && <div className="blm-result blm-result-good">Transfer confirmed. The loan account is active and the repayment schedule is available to the customer.</div>}

                {history.length > 0 && (
                  <section className="blm-subsection">
                    <h4>Application history</h4>
                    <ol className="blm-history">
                      {history.map((entry) => <li key={entry.id}><b>{statusLabel(entry.action)}</b><span>{entry.remarks || entry.currentStatus}</span><small>{entry.createdAt ? new Date(entry.createdAt).toLocaleString('en-IN') : '—'} · {entry.actorId || 'System'}</small></li>)}
                    </ol>
                  </section>
                )}
              </>
            )}
            <DocumentPreview file={previewFile} onClose={() => setPreviewFile(null)} />
          </section>
        </div>
      )}

      {tab === 'products' && canManageProducts && (
        <div className="blm-products-layout">
          <section className="blm-panel">
            <div className="blm-panel-heading"><div><h3>Create a loan product</h3><p>Products become visible to customers after saving.</p></div></div>
            <form className="blm-product-form" onSubmit={createProduct}>
              <label>Product name<input required value={productForm.name} onChange={(e) => setProductForm({ ...productForm, name: e.target.value })} /></label>
              <label className="blm-field-wide">Description<textarea rows="2" value={productForm.description} onChange={(e) => setProductForm({ ...productForm, description: e.target.value })} /></label>
              <label>Minimum amount (₹)<input type="number" min="1" required value={productForm.minimumAmount} onChange={(e) => setProductForm({ ...productForm, minimumAmount: e.target.value })} /></label>
              <label>Maximum amount (₹)<input type="number" min="1" required value={productForm.maximumAmount} onChange={(e) => setProductForm({ ...productForm, maximumAmount: e.target.value })} /></label>
              <label>Annual interest rate (%)<input type="number" min="0.01" max="100" step="0.01" required value={productForm.annualInterestRate} onChange={(e) => setProductForm({ ...productForm, annualInterestRate: e.target.value })} /></label>
              <label>Minimum tenure (months)<input type="number" min="1" max="480" required value={productForm.minimumTenureMonths} onChange={(e) => setProductForm({ ...productForm, minimumTenureMonths: e.target.value })} /></label>
              <label>Maximum tenure (months)<input type="number" min="1" max="480" required value={productForm.maximumTenureMonths} onChange={(e) => setProductForm({ ...productForm, maximumTenureMonths: e.target.value })} /></label>
              <label>Maximum FOIR (%)<input type="number" min="1" max="100" step="0.01" required value={productForm.maximumFoirPercent} onChange={(e) => setProductForm({ ...productForm, maximumFoirPercent: e.target.value })} /></label>
              <label>Minimum credit score<input type="number" min="300" max="900" required value={productForm.minimumCreditScore} onChange={(e) => setProductForm({ ...productForm, minimumCreditScore: e.target.value })} /></label>
              <div className="blm-product-submit"><button className="blm-button blm-button-primary" disabled={busy === 'product'}>{busy === 'product' ? 'Saving…' : 'Create product'}</button></div>
            </form>
          </section>
          <section className="blm-panel">
            <div className="blm-panel-heading"><div><h3>Available products</h3><p>Active offers customers can currently apply for.</p></div></div>
            {products.length === 0 ? <div className="blm-state">No active loan products.</div> : products.map((product) => (
              <article className="blm-product-card" key={product.id}>
                <div><h4>{product.name}</h4><span className="blm-product-rate">{product.annualInterestRate}% p.a.</span></div>
                <p>{product.description || 'No description'}</p>
                <small>{money(product.minimumAmount)}–{money(product.maximumAmount)} · {product.minimumTenureMonths}–{product.maximumTenureMonths} months · FOIR {product.maximumFoirPercent}% · Score {product.minimumCreditScore}+</small>
              </article>
            ))}
          </section>
        </div>
      )}
      </div>
      </div>
    </div>
  )
}

