  background: #176bd1;
}

.loan-wizard-panel {
  display: grid;
  gap: 16px;
}

.loan-wizard-panel > h3 {
  margin: 0;
  color: #18395f;
  font-size: 16px;
}

.loan-wizard-actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  flex-wrap: wrap;
}

.loan-document-step {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.loan-document-step > label {
  display: grid;
  gap: 7px;
  padding: 14px;
  border: 1px solid #e2eaf3;
  border-radius: 9px;
  color: #40546f;
  background: #fbfdff;
  font-size: 12px;
