}

.loan-document-step small {
  color: #64748b;
  font-size: 11px;
  font-weight: 500;
}

.loan-submit-review {
  grid-column: 1 / -1;
  display: grid;
  gap: 12px;
  padding: 15px;
  border-radius: 10px;
  background: #f5f9fe;
}

.loan-submit-review h4 {
  margin: 0;
  color: #18395f;
}

.loan-document-step .loan-wizard-actions {
  grid-column: 1 / -1;
}

.loan-form-grid label,
.loan-upload-form label,
.loan-repayment label {
  display: grid;
  gap: 6px;
  color: #40546f;
  font-size: 12px;
  font-weight: 700;
}

.loan-form-grid input,
.loan-form-grid select,
.loan-upload-form input,
.loan-upload-form select,
.loan-repayment input {
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid #d5dfeb;
  border-radius: 8px;
  color: #1d314d;
  background: #fff;
  font: inherit;
}

.loan-form-actions {
  grid-column: 1 / -1;
}

.loan-button {
  min-height: 38px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: 8px;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}

.loan-button:disabled {
  opacity: .6;
  cursor: not-allowed;
}

.loan-button-primary {
  color: #fff;
  background: #176bd1;
}

.loan-button-primary:hover:not(:disabled) {
  background: #0e57b0;
}

.loan-button-light {
  border-color: #d7e2ee;
  color: #29415e;
  background: #fff;
}

.loan-text-button {
  border: 0;
  color: #2169b6;
  background: none;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.loan-estimate {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  margin-top: 17px;
  padding: 15px;
  border-radius: 10px;
  background: #f0f7ff;
}

.loan-estimate > div {
  display: grid;
  gap: 5px;
}

.loan-estimate span {
  color: #64748b;
  font-size: 11px;
}

.loan-estimate strong {
  color: #12355f;
  font-size: 14px;
}

.loan-hint {
  margin-top: 13px;
}

.loan-list {
  display: grid;
  gap: 8px;
}

.loan-list-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
