}

.loan-customer-documents {
  display: grid;
  gap: 8px;
}

.loan-customer-documents > div {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid #e5ecf4;
  border-radius: 8px;
