}

.loan-doc-status.verified {
  color: #17623d;
  background: #eaf8f0;
}

.loan-detail-heading h3,
.loan-table-section h3 {
  margin: 0 0 4px;
  color: #18395f;
  font-size: 14px;
}

.loan-detail-heading span {
  color: #708198;
  font-size: 11px;
}

.loan-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}

.loan-summary-grid > div {
  padding: 11px 12px;
  border: 1px solid #e8eef5;
  border-radius: 8px;
}

.loan-summary-grid b {
  color: #213b5b;
  font-size: 12px;
  text-align: right;
}

.loan-upload-form {
  display: flex;
  align-items: end;
  gap: 12px;
  flex-wrap: wrap;
}

.loan-upload-form label {
