}

.loan-documents {
  display: grid;
  gap: 8px;
  color: #2a4160;
  font-size: 12px;
}

.loan-documents > div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 11px;
  border-radius: 8px;
  background: #f7f9fc;
}

.loan-offer,
.loan-agreement {
  padding: 15px;
  border: 1px solid #dce9f7;
  border-radius: 10px;
  background: #f7fbff;
}

.loan-offer h4,
