  background: #f8fafc;
}

.loan-alert {
  padding: 12px 15px;
  border-radius: 8px;
  font-size: 12px;
}

.loan-alert-error,
.loan-note-error {
  color: #a32929;
  background: #fff0ef;
}

.loan-alert-success {
  color: #17623d;
  background: #eaf8f0;
}

.loan-note-error {
  margin: 0;
  padding: 12px;
  border-radius: 8px;
  font-size: 12px;
}

.loan-summary-section {
  display: grid;
  gap: 10px;
}

.loan-summary-section h4,
.loan-employment-form h4 {
  grid-column: 1 / -1;
  margin: 0;
  color: #18395f;
  font-size: 14px;
}

.loan-employment-form {
  padding: 15px;
  border: 1px solid #e2eaf3;
  border-radius: 10px;
  background: #fbfdff;
}

.loan-employment-form > button {
  justify-self: start;
}

.loan-timeline {
  display: grid;
  gap: 12px;
  margin: 0;
  padding: 0 0 0 20px;
}

.loan-timeline li {
  display: grid;
  gap: 4px;
  padding-left: 4px;
  color: #29415e;
  font-size: 12px;
}

.loan-timeline li::marker {
  color: #176bd1;
}

.loan-timeline span,
.loan-timeline small {
  color: #64748b;
}

.loan-preview-backdrop {
  position: fixed;
  z-index: 1000;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 20px;
  background: rgba(8, 24, 45, .68);
}

.loan-preview-panel {
  display: grid;
  gap: 12px;
  width: min(900px, 100%);
  height: min(85vh, 760px);
  padding: 15px;
  border-radius: 12px;
  background: #fff;
}

.loan-preview-panel > button {
  justify-self: end;
}

.loan-preview-panel img,
.loan-preview-panel iframe {
  width: 100%;
  height: 100%;
  min-height: 0;
  border: 0;
  object-fit: contain;
}

.loan-state {
  padding: 38px 20px;
  color: #64748b;
  text-align: center;
}

@media (max-width: 680px) {
  .loan-section-nav {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .loan-portal-heading,
  .loan-section-heading,
  .loan-detail-heading {
    align-items: flex-start;
  }

  .loan-portal-heading {
    padding: 17px;
  }

  .loan-card {
    padding: 16px;
  }

  .loan-form-grid {
    grid-template-columns: 1fr;
  }

  .loan-field-wide {
    grid-column: auto;
  }

  .loan-stepper {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .loan-stepper li {
    padding: 7px 4px;
    font-size: 11px;
  }

  .loan-document-step {
    grid-template-columns: 1fr;
  }

  .loan-submit-review,
  .loan-document-step .loan-wizard-actions {
    grid-column: auto;
  }

  .loan-form-actions {
    grid-column: auto;
  }

  .loan-list-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .loan-customer-detail {
    padding: 14px;
  }

  .loan-customer-detail .loan-detail-heading {
    flex-direction: column;
  }

  .loan-customer-progress {
    grid-template-columns: 1fr;
  }

  .loan-customer-documents > div {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .loan-customer-documents > div .loan-text-button {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .loan-preview-backdrop {
    padding: 8px;
  }
}

