}

import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Brand from '../../../shared/components/Brand'
import Icon from '../../../shared/components/Icon'
import {
  getActiveBranches,
  submitPublicApplication,
}
 from '../../../services/bankingService'
import { isApiConfigured } from '../../../services/apiClient'
import './PublicApplyPage.css'

const maxDocumentSize = 10 * 1024 * 1024
const acceptedDocumentTypes = new Set([
  'application/pdf',
  'image/png',
  'image/jpeg',
])

const OPENING_BALANCE_BY_TYPE = {
  SAVINGS: 1000,
  CURRENT: 10000,
}

const defaultForm = {
  title: 'MR',
  name: '',
  email: '',
  phone: '',
  alternateMobileNumber: '',
  dateOfBirth: '',
  gender: 'MALE',
  nationality: 'Indian',
  maritalStatus: 'SINGLE',
  language: '',
  accountType: 'SAVINGS',
  currency: 'INR',
  openingBalance: OPENING_BALANCE_BY_TYPE.SAVINGS,
  preferredBranchCode: '',
  permanentAddress: '',
  permanentCity: '',
  permanentState: '',
  permanentCountry: 'India',
  permanentPinCode: '',
  communicationAddress: '',
  communicationCity: '',
  communicationState: '',
  communicationCountry: '',
  communicationPinCode: '',
  occupation: '',
  annualIncome: '',
  sourceOfIncome: '',
  aadhaarNumber: '',
  panNumber: '',
}

export default function PublicApplyPage() {
  const navigate = useNavigate()
  const [form, setForm] = useState(defaultForm)
  const [sameAddress, setSameAddress] = useState(false)
  const [step, setStep] = useState(1)
  const [aadhaarFile, setAadhaarFile] = useState(null)
  const [panFile, setPanFile] = useState(null)
  const [profileImage, setProfileImage] = useState(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [branches, setBranches] = useState([])
  const [branchesLoading, setBranchesLoading] = useState(true)
  const [result, setResult] = useState(null)

  const [fieldErrors, setFieldErrors] = useState({})

  const formRef = useRef(null)
  const topRef = useRef(null)

  useEffect(() => {
    let active = true
    setBranchesLoading(true)
    getActiveBranches()
      .then((list) => {
        if (!active) return
        setBranches(list || [])
        setForm((current) => ({
          ...current,
          preferredBranchCode:
            current.preferredBranchCode || list?.[0]?.branchCode || '',
        }))
      })
      .catch((err) => {
        if (active) setError(err.message || 'Could not load branches.')
      })
      .finally(() => {
        if (active) setBranchesLoading(false)
      })
    return () => {
      active = false
    }
  }, [])

  const validateField = (name, value) => {
    let errorMsg = ''

    if (name === 'phone' || name === 'alternateMobileNumber') {
      if (value.length > 0 && value.length < 10) {
        errorMsg = 'Mobile number must be exactly 10 digits.'
      }
    }

    if (name === 'aadhaarNumber') {
      if (value.length > 0 && value.length < 12) {
        errorMsg = 'Aadhaar number must be exactly 12 digits.'
      }
    }

    if (name === 'panNumber') {
      const panRegex = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/
      if (value.length > 0 && value.length < 10) {
        errorMsg = 'PAN must be 10 characters (e.g. ABCDE1234F).'
      } else if (value.length === 10 && !panRegex.test(value)) {
        errorMsg = 'Invalid PAN format. (e.g. ABCDE1234F).'
      }
    }

    setFieldErrors((prev) => ({ ...prev, [name]: errorMsg }))
    return errorMsg
  }

  const setField = (key, value) => {
    setForm((current) => {
      const newForm = { ...current, [key]: value }

      if (key === 'accountType') {
        newForm.openingBalance =
          OPENING_BALANCE_BY_TYPE[value] ?? OPENING_BALANCE_BY_TYPE.SAVINGS
      }

      if (sameAddress && key.startsWith('permanent')) {
        const commKey = key.replace('permanent', 'communication')
        newForm[commKey] = value
      }
      return newForm
    })

    if (['phone', 'alternateMobileNumber', 'aadhaarNumber', 'panNumber'].includes(key)) {
      validateField(key, value)
    }
  }

  const handleSameAddressToggle = (e) => {
    const checked = e.target.checked
    setSameAddress(checked)
    if (checked) {
      setForm((current) => ({
        ...current,
        communicationAddress: current.permanentAddress,
        communicationCity: current.permanentCity,
        communicationState: current.permanentState,
        communicationCountry: current.permanentCountry,
        communicationPinCode: current.permanentPinCode,
      }))
    } else {
      setForm((current) => ({
        ...current,
        communicationAddress: '',
        communicationCity: '',
        communicationState: '',
        communicationCountry: '',
        communicationPinCode: '',
      }))
    }
  }

  function validateCurrentStep() {
    const formEl = formRef.current
    if (!formEl) return true

    // Native required-field validation for the visible step only
    const stepEl = formEl.querySelector(`[data-step="${step}"]`)
    const fields = stepEl
      ? stepEl.querySelectorAll('input, select, textarea')
      : formEl.querySelectorAll('input, select, textarea')

    const allValid = Array.from(fields).every((field) => {
      if (field.disabled) return true
      if (field.required && !field.checkValidity()) return false
      return true
    })

    if (!allValid) {
      setError('Please fill out all required fields correctly.')
      return false
    }

    const activeErrors = Object.values(fieldErrors).filter(Boolean)
    if (activeErrors.length > 0) {
      setError('Please fix the errors in the form before continuing.')
      return false
    }

    if (step === 3) {
      for (const [label, file] of [
        ['Aadhaar document', aadhaarFile],
        ['PAN document', panFile],
      ]) {
        if (!file) {
          setError(`Please upload your ${label}.`)
          return false
        }
        if (file.size > maxDocumentSize) {
          setError(`${label} must be 10 MB or smaller.`)
          return false
        }
        if (!acceptedDocumentTypes.has(file.type)) {
          setError(`${label} must be a PDF, PNG or JPG file.`)
          return false
        }
      }

      if (form.aadhaarNumber.length !== 12) {
        setError('Please enter a valid 12-digit Aadhaar number.')
        return false
      }
      if (!/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(form.panNumber)) {
        setError('Please enter a valid PAN (e.g. ABCDE1234F).')
        return false
      }
    }
    return true
  }

  function handleContinue(event) {
    event.preventDefault()
    setError('')
    if (!validateCurrentStep()) return
    setStep((s) => s + 1)
    topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  function handleBack() {
    setError('')
    setStep((s) => s - 1)
    topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  async function handleSubmit(event) {
    event.preventDefault()
    setError('')
    if (!validateCurrentStep()) return

    setLoading(true)
    try {
      const payload = new FormData()
      Object.entries(form).forEach(([key, value]) => {
        payload.set(key, value ?? '')
      })
      payload.set('aadhaarFile', aadhaarFile)
      payload.set('panFile', panFile)

      if (profileImage) {
        payload.set('profileImage', profileImage)
      }

      const response = await submitPublicApplication(payload)
      setResult(response)
      topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    } catch (err) {
      setError(err.message || 'Could not submit your application.')
    } finally {
      setLoading(false)
    }
  }

  // ── SUCCESS SCREEN ──────────────────────────────────────────────
  if (result) {
  return (
    <main className="apply-app" style={{ backgroundColor: '#f1f5f9', minHeight: '100vh' }}>
      <div className="apply-topbar">
        <button className="apply-brand" type="button" onClick={() => navigate('/')}>
          <Brand />
        </button>
        <button className="back-home" onClick={() => navigate('/')}>
          <Icon name="arrowRight" size={15} style={{ transform: 'rotate(180deg)' }} /> Back to Nova Bank
        </button>
      </div>

      <div className="apply-layout-wide" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 'calc(100vh - 60px)', padding: '1rem' }}>

        {/* Modern Card Container */}
        <section 
          className="apply-success" 
          style={{ 
            background: '#ffffff', 
            padding: '0', 
            borderRadius: '16px', 
            textAlign: 'center', 
            maxWidth: '480px', 
            width: '100%',
            boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.05), 0 10px 10px -5px rgba(0, 0, 0, 0.02)', 
            border: '1px solid #e2e8f0',
            overflow: 'hidden'
          }}
        >
          {/* Top Colorful Gradient Bar */}
          <div style={{ height: '6px', width: '100%', background: 'linear-gradient(90deg, #6366f1, #a855f7, #ec4899)' }} />

          <div style={{ padding: '2.5rem 2rem' }}>

            {/* Animated Success Icon */}
            <div className="apply-success-icon" style={{ 
              display: 'inline-flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              backgroundColor: '#ecfdf5', 
              color: '#10b981', 
              padding: '1rem', 
              borderRadius: '50%',
              border: '2px solid #d1fae5',
              marginBottom: '1.5rem',
              boxShadow: '0 0 0 8px rgba(16, 185, 129, 0.05)'
            }}>
              <Icon name="check" size={36} strokeWidth={3} />
            </div>

            <h1 style={{ fontSize: '1.5rem', fontWeight: '700', color: '#1e293b', margin: '0 0 0.5rem 0' }}>Application Received</h1>
            <p style={{ color: '#64748b', fontSize: '0.9rem', margin: '0 0 2rem 0', lineHeight: '1.5' }}>
              Thank you. Your Nova Bank account application has been submitted for review.
            </p>

            {/* Styled Details Box */}
            <div className="apply-success-card" style={{ 
              background: '#f8fafc', 
              border: '1px solid #e2e8f0', 
              borderRadius: '12px', 
              padding: '1rem 1.25rem', 
              marginBottom: '1.5rem',
              textAlign: 'left'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingBottom: '0.75rem', borderBottom: '1px dashed #cbd5e1' }}>
                <span style={{ fontSize: '0.85rem', fontWeight: '500', color: '#64748b' }}>Reference ID</span>
                <b style={{ fontSize: '0.85rem', fontWeight: '700', color: '#4f46e5', backgroundColor: '#e0e7ff', padding: '0.25rem 0.5rem', borderRadius: '6px', letterSpacing: '0.5px' }}>
                  {result.id || result.customerId || '—'}
                </b>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '0.75rem' }}>
                <span style={{ fontSize: '0.85rem', fontWeight: '500', color: '#64748b' }}>Status</span>
                <b className="apply-status-pill" style={{ 
                  fontSize: '0.75rem', 
                  fontWeight: '700', 
                  color: '#b45309', 
                  backgroundColor: '#fef3c7', 
                  padding: '0.25rem 0.75rem', 
                  borderRadius: '999px',
                  textTransform: 'uppercase',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.25rem'
                }}>
                  {result.status || 'KYC PENDING'}
                </b>
              </div>
            </div>

            <p className="apply-success-note" style={{ fontSize: '0.8rem', color: '#94a3b8', lineHeight: '1.6', marginBottom: '2rem', padding: '0 0.5rem' }}>
              {isApiConfigured
                ? 'Once our team verifies your KYC and opens your account, we will email your username and password. You can then log in from the Nova Bank home page.'
                : 'Demo preview only — no real data was stored.'}
            </p>

            {/* Modernized Buttons */}
            <div className="apply-success-actions" style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center', flexWrap: 'wrap' }}>
              <button 
                className="button button-primary" 
                onClick={() => navigate('/')}
                style={{ 
                  flex: 1, 
                  minWidth: '140px',
                  padding: '0.75rem 1rem', 
                  borderRadius: '10px', 
                  fontWeight: '600',
                  backgroundColor: '#4f46e5',
                  color: '#ffffff',
                  border: 'none',
                  cursor: 'pointer',
                  boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)',
                  transition: 'all 0.2s'
                }}
              >
                Back to home
              </button>
              <button 
                className="button button-secondary" 
                onClick={() => navigate('/login')}
                style={{ 
                  flex: 1, 
                  minWidth: '140px',
                  padding: '0.75rem 1rem', 
                  borderRadius: '10px', 
                  fontWeight: '600',
                  backgroundColor: '#ffffff',
                  color: '#334155',
                  border: '1px solid #e2e8f0',
                  cursor: 'pointer',
                  transition: 'all 0.2s'
                }}
              >
                Go to login
              </button>
            </div>

          </div>
        </section>
      </div>
    </main>
  )
}

  // ── FORM SCREEN ────────────────────────────────────────────────
  return (
    <main className="apply-app">
      <div className="apply-topbar">
        <button className="apply-brand" type="button" onClick={() => navigate('/')}>
          <Brand />
        </button>
        <button className="back-home" onClick={() => navigate('/')}>
          <Icon name="arrowRight" size={15} style={{ transform: 'rotate(180deg)' }} /> Back to Home
        </button>
      </div>

      <div className="apply-layout-wide" ref={topRef}>
        {/* SIDEBAR */}
        <aside className="apply-sidebar">
          <div className="sidebar-content">
            <h1>Welcome to<br /><span>Nova Bank</span></h1>
            <p className="tagline">Secure. Simple. Smart.</p>

            <div className="sidebar-features">
              <div className="feature">
                <span className="feature-icon">️</span>
                <div>
                  <h4>Bank with Confidence</h4>
                  <p>Your data is protected by bank-grade encryption.</p>
                </div>
              </div>
              <div className="feature">
                <span className="feature-icon">⚡</span>
                <div>
                  <h4>Fast &amp; Easy Onboarding</h4>
                  <p>Open your account in just a few simple steps.</p>
                </div>
              </div>
              <div className="feature">
                <span className="feature-icon"></span>
                <div>
                  <h4>24/7 Support</h4>
                  <p>We're always here to help you with your financial journey.</p>
                </div>
              </div>
            </div>

            <div className="sidebar-footer">
              <p>Your Dreams.<br />Our Commitment.</p>
            </div>
          </div>
        </aside>

        {/* FORM */}
        <form
          ref={formRef}
          className="apply-form-compact"
          onSubmit={step === 3 ? handleSubmit : handleContinue}
          noValidate
        >
          <div className="apply-form-header">
            <h2>Open your Nova Bank Account</h2>
            <span>Please fill all required (*) fields.</span>
          </div>

          <div className="apply-steps-header">
            <div className={`apply-step-title ${step >= 1 ? 'active' : ''}`}>
              <span>1</span> Personal details
            </div>
            <div className={`apply-step-divider ${step >= 2 ? 'active' : ''}`} />
            <div className={`apply-step-title ${step >= 2 ? 'active' : ''}`}>
              <span>2</span> Address &amp; account
            </div>
            <div className={`apply-step-divider ${step >= 3 ? 'active' : ''}`} />
            <div className={`apply-step-title ${step >= 3 ? 'active' : ''}`}>
              <span>3</span> Identity documents
            </div>
          </div>

          {/* STEP 1 */}
          {step === 1 && (
            <div className="apply-section fade-in" data-step="1">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Title <b className="req">*</b></span>
                  <select value={form.title} onChange={(e) => setField('title', e.target.value)} required>
                    <option value="MR">Mr</option>
                    <option value="MS">Ms</option>
                    <option value="MRS">Mrs</option>
                    <option value="DR">Dr</option>
                  </select>
                </label>

                <label className="form-label apply-span-2">
                  <span>Full name (as on ID) <b className="req">*</b></span>
                  <input
                    required
                    value={form.name}
                    onChange={(e) => setField('name', e.target.value)}
                    placeholder="As shown on your ID"
                  />
                </label>

                <label className="form-label">
                  <span>Date of birth <b className="req">*</b></span>
                  <input type="date" required max={new Date().toISOString().slice(0, 10)} value={form.dateOfBirth} onChange={(e) => setField('dateOfBirth', e.target.value)} />
                </label>

                <label className="form-label">
                  <span>Gender <b className="req">*</b></span>
                  <select value={form.gender} onChange={(e) => setField('gender', e.target.value)} required>
                    <option value="MALE">Male</option>
                    <option value="FEMALE">Female</option>
                    <option value="OTHER">Other</option>
                  </select>
                </label>

                <label className="form-label apply-span-2">
                  <span>Email <b className="req">*</b></span>
                  <input type="email" required value={form.email} onChange={(e) => setField('email', e.target.value)} placeholder="you@example.com" />
                </label>

                <label className="form-label">
                  <span>Mobile number <b className="req">*</b></span>
                  <input
                    type="tel"
                    required
                    inputMode="numeric"
                    value={form.phone}
                    onChange={(e) => setField('phone', e.target.value.replace(/\D/g, '').slice(0, 10))}
                    placeholder="10 digits"
                    style={{ borderColor: fieldErrors.phone ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.phone && <small className="field-error-text">{fieldErrors.phone}</small>}
                </label>

                <label className="form-label">
                  <span>Alt mobile</span>
                  <input
                    type="tel"
                    inputMode="numeric"
                    value={form.alternateMobileNumber}
                    onChange={(e) => setField('alternateMobileNumber', e.target.value.replace(/\D/g, '').slice(0, 10))}
                    placeholder="10 digits"
                    style={{ borderColor: fieldErrors.alternateMobileNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.alternateMobileNumber && <small className="field-error-text">{fieldErrors.alternateMobileNumber}</small>}
                </label>

                <label className="form-label">
                  <span>Nationality <b className="req">*</b></span>
                  <input required value={form.nationality} onChange={(e) => setField('nationality', e.target.value)} />
                </label>

                <label className="form-label">
                  <span>Marital status <b className="req">*</b></span>
                  <select value={form.maritalStatus} onChange={(e) => setField('maritalStatus', e.target.value)} required>
                    <option value="SINGLE">Single</option>
                    <option value="MARRIED">Married</option>
                    <option value="DIVORCED">Divorced</option>
                    <option value="WIDOWED">Widowed</option>
                  </select>
                </label>

                <label className="form-label">
                  <span>Language</span>
                  <input value={form.language} onChange={(e) => setField('language', e.target.value)} placeholder="e.g. Hindi" />
                </label>

                <label className="form-label apply-span-3">
                  <span>Profile photo</span>
                  <input
                    type="file"
                    accept="image/png,image/jpeg"
                    onChange={(e) => setProfileImage(e.target.files?.[0] || null)}
                  />
                  <small className="field-help-text" style={{ display: 'block', marginTop: '4px' }}>
                    Optional. JPG or PNG, up to 10 MB.
                  </small>
                </label>
              </div>
            </div>
          )}

          {/* STEP 2 */}
          {step === 2 && (
            <div className="apply-section fade-in" data-step="2">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Account type <b className="req">*</b></span>
                  <select value={form.accountType} onChange={(e) => setField('accountType', e.target.value)} required>
                    <option value="SAVINGS">Savings account</option>
                    <option value="CURRENT">Current account</option>
                  </select>
                </label>
                <label className="form-label">
                  <span>Currency <b className="req">*</b></span>
                  <select value={form.currency} onChange={(e) => setField('currency', e.target.value)} required>
                    <option value="INR">INR</option>
                  </select>
                </label>
                <label className="form-label">
                  <span>Branch <b className="req">*</b></span>
                  <select required value={form.preferredBranchCode} onChange={(e) => setField('preferredBranchCode', e.target.value)} disabled={branchesLoading}>
                    <option value="" disabled>{branchesLoading ? 'Loading…' : 'Select a branch'}</option>
                    {branches.map((b) => (
                      <option key={b.branchCode} value={b.branchCode}>
                        {b.branchName} {b.city ? `— ${b.city}` : ''}
                      </option>
                    ))}
                  </select>
                </label>

                <label className="form-label">
                  <span>Opening balance (INR)</span>
                  <input
                    readOnly
                    value={`₹ ${Number(form.openingBalance).toLocaleString('en-IN')}`}
                  />
                  <small className="field-help-text">
                    Auto-set: Savings = ₹1,000 · Current = ₹10,000
                  </small>
                </label>

                <label className="form-label apply-span-2">
                  <span>Permanent Address <b className="req">*</b></span>
                  <input required value={form.permanentAddress} onChange={(e) => setField('permanentAddress', e.target.value)} placeholder="House number and street" />
                </label>
                <label className="form-label">
                  <span>City <b className="req">*</b></span>
                  <input required value={form.permanentCity} onChange={(e) => setField('permanentCity', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>State <b className="req">*</b></span>
                  <input required value={form.permanentState} onChange={(e) => setField('permanentState', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>Country <b className="req">*</b></span>
                  <input required value={form.permanentCountry} onChange={(e) => setField('permanentCountry', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>PIN code <b className="req">*</b></span>
                  <input required inputMode="numeric" pattern="[0-9]{4,10}" value={form.permanentPinCode} onChange={(e) => setField('permanentPinCode', e.target.value.replace(/\D/g, ''))} />
                </label>

                <div className="apply-checkbox-wrapper apply-span-3">
                  <label className="apply-checkbox-label">
                    <input type="checkbox" checked={sameAddress} onChange={handleSameAddressToggle} />
                    Communication Address is same as Permanent Address
                  </label>
                </div>

                <label className="form-label apply-span-2">
                  <span>Communication Address</span>
                  <input value={form.communicationAddress} onChange={(e) => setField('communicationAddress', e.target.value)} disabled={sameAddress} placeholder="House number and street" />
                </label>
                <label className="form-label">
                  <span>City</span>
                  <input value={form.communicationCity} onChange={(e) => setField('communicationCity', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>State</span>
                  <input value={form.communicationState} onChange={(e) => setField('communicationState', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>Country</span>
                  <input value={form.communicationCountry} onChange={(e) => setField('communicationCountry', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>PIN code</span>
                  <input inputMode="numeric" pattern="[0-9]{4,10}" value={form.communicationPinCode} onChange={(e) => setField('communicationPinCode', e.target.value.replace(/\D/g, ''))} disabled={sameAddress} />
                </label>

                <div className="apply-section-divider apply-span-3" />

                <label className="form-label">
                  <span>Occupation</span>
                  <input value={form.occupation} onChange={(e) => setField('occupation', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>Annual income (INR)</span>
                  <input type="number" min="0" step="0.01" value={form.annualIncome} onChange={(e) => setField('annualIncome', e.target.value)} />
                </label>

                <label className="form-label">
                  <span>Source of income <b className="req">*</b></span>
                  <select value={form.sourceOfIncome} onChange={(e) => setField('sourceOfIncome', e.target.value)} required>
                    <option value="" disabled>Select source</option>
                    <option value="SALARY">Salary</option>
                    <option value="BUSINESS">Business</option>
                    <option value="INVESTMENT">Investment</option>
                    <option value="PENSION">Pension</option>
                    <option value="RENTAL_INCOME">Rental income</option>
                    <option value="OTHER">Other</option>
                  </select>
                </label>
              </div>
            </div>
          )}

          {/* STEP 3 */}
          {step === 3 && (
            <div className="apply-section fade-in" data-step="3">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Aadhaar number <b className="req">*</b></span>
                  <input
                    required
                    inputMode="numeric"
                    value={form.aadhaarNumber}
                    onChange={(e) => setField('aadhaarNumber', e.target.value.replace(/\D/g, '').slice(0, 12))}
                    placeholder="12-digit number"
                    style={{ borderColor: fieldErrors.aadhaarNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.aadhaarNumber && <small className="field-error-text">{fieldErrors.aadhaarNumber}</small>}
                </label>

                <label className="form-label">
                  <span>PAN number <b className="req">*</b></span>
                  <input
                    required
                    maxLength={10}
                    value={form.panNumber}
                    onChange={(e) => setField('panNumber', e.target.value.toUpperCase().slice(0, 10))}
                    placeholder="ABCDE1234F"
                    style={{ borderColor: fieldErrors.panNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.panNumber && <small className="field-error-text">{fieldErrors.panNumber}</small>}
                </label>

                <div className="apply-spacer" />

                <label className="form-label">
                  <span>Aadhaar document <b className="req">*</b></span>
                  <input type="file" required accept=".pdf,.png,.jpg,.jpeg" onChange={(e) => setAadhaarFile(e.target.files?.[0] || null)} />
                  <small className="field-help-text">PDF, PNG or JPG · max 10 MB</small>
                </label>
                <label className="form-label">
                  <span>PAN document <b className="req">*</b></span>
                  <input type="file" required accept=".pdf,.png,.jpg,.jpeg" onChange={(e) => setPanFile(e.target.files?.[0] || null)} />
                  <small className="field-help-text">PDF, PNG or JPG · max 10 MB</small>
                </label>
              </div>

              <p className="apply-hint" style={{ fontSize: '0.8rem', color: '#64748b', marginTop: '1rem' }}>
                Your documents are transmitted securely and used only for KYC verification.
              </p>
            </div>
          )}

          {error && <p className="form-error" role="alert" style={{ marginTop: '12px' }}>{error}</p>}

          {/* ACTIONS */}
          <div className="apply-actions" style={{ display: 'flex', justifyContent: 'space-between', width: '100%', marginTop: '1.5rem' }}>
            <div>
              {step > 1 ? (
                <button type="button" className="button button-secondary" onClick={handleBack} disabled={loading}>
                  Back
                </button>
              ) : (
                <button type="button" className="button button-secondary" onClick={() => navigate('/')}>
                  Cancel
                </button>
              )}
            </div>
            <button type="submit" className="button button-primary" disabled={loading || branchesLoading}>
              {loading ? 'Submitting…' : step === 3 ? 'Submit Application' : 'Continue'}
              <Icon name={step === 3 ? 'check' : 'arrowRight'} size={16} />
            </button>
          </div>
        </form>
      </div>
    </main>
  )
}

import { useEffect, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Brand from '../../../shared/components/Brand'
import Icon from '../../../shared/components/Icon'
import {
  getActiveBranches,
  submitPublicApplication,
}
 from '../../../services/bankingService'
import { isApiConfigured } from '../../../services/apiClient'
import './PublicApplyPage.css'

const maxDocumentSize = 10 * 1024 * 1024
const acceptedDocumentTypes = new Set([
  'application/pdf',
  'image/png',
  'image/jpeg',
])

const OPENING_BALANCE_BY_TYPE = {
  SAVINGS: 1000,
  CURRENT: 10000,
}

const defaultForm = {
  title: 'MR',
  name: '',
  email: '',
  phone: '',
  alternateMobileNumber: '',
  dateOfBirth: '',
  gender: 'MALE',
  nationality: 'Indian',
  maritalStatus: 'SINGLE',
  language: '',
  accountType: 'SAVINGS',
  currency: 'INR',
  openingBalance: OPENING_BALANCE_BY_TYPE.SAVINGS,
  preferredBranchCode: '',
  permanentAddress: '',
  permanentCity: '',
  permanentState: '',
  permanentCountry: 'India',
  permanentPinCode: '',
  communicationAddress: '',
  communicationCity: '',
  communicationState: '',
  communicationCountry: '',
  communicationPinCode: '',
  occupation: '',
  annualIncome: '',
  sourceOfIncome: '',
  aadhaarNumber: '',
  panNumber: '',
}

export default function PublicApplyPage() {
  const navigate = useNavigate()
  const [form, setForm] = useState(defaultForm)
  const [sameAddress, setSameAddress] = useState(false)
  const [step, setStep] = useState(1)
  const [aadhaarFile, setAadhaarFile] = useState(null)
  const [panFile, setPanFile] = useState(null)
  const [profileImage, setProfileImage] = useState(null)
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const [branches, setBranches] = useState([])
  const [branchesLoading, setBranchesLoading] = useState(true)
  const [result, setResult] = useState(null)

  const [fieldErrors, setFieldErrors] = useState({})

  const formRef = useRef(null)
  const topRef = useRef(null)

  useEffect(() => {
    let active = true
    setBranchesLoading(true)
    getActiveBranches()
      .then((list) => {
        if (!active) return
        setBranches(list || [])
        setForm((current) => ({
          ...current,
          preferredBranchCode:
            current.preferredBranchCode || list?.[0]?.branchCode || '',
        }))
      })
      .catch((err) => {
        if (active) setError(err.message || 'Could not load branches.')
      })
      .finally(() => {
        if (active) setBranchesLoading(false)
      })
    return () => {
      active = false
    }
  }, [])

  const validateField = (name, value) => {
    let errorMsg = ''

    if (name === 'phone' || name === 'alternateMobileNumber') {
      if (value.length > 0 && value.length < 10) {
        errorMsg = 'Mobile number must be exactly 10 digits.'
      }
    }

    if (name === 'aadhaarNumber') {
      if (value.length > 0 && value.length < 12) {
        errorMsg = 'Aadhaar number must be exactly 12 digits.'
      }
    }

    if (name === 'panNumber') {
      const panRegex = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/
      if (value.length > 0 && value.length < 10) {
        errorMsg = 'PAN must be 10 characters (e.g. ABCDE1234F).'
      } else if (value.length === 10 && !panRegex.test(value)) {
        errorMsg = 'Invalid PAN format. (e.g. ABCDE1234F).'
      }
    }

    setFieldErrors((prev) => ({ ...prev, [name]: errorMsg }))
    return errorMsg
  }

  const setField = (key, value) => {
    setForm((current) => {
      const newForm = { ...current, [key]: value }

      if (key === 'accountType') {
        newForm.openingBalance =
          OPENING_BALANCE_BY_TYPE[value] ?? OPENING_BALANCE_BY_TYPE.SAVINGS
      }

      if (sameAddress && key.startsWith('permanent')) {
        const commKey = key.replace('permanent', 'communication')
        newForm[commKey] = value
      }
      return newForm
    })

    if (['phone', 'alternateMobileNumber', 'aadhaarNumber', 'panNumber'].includes(key)) {
      validateField(key, value)
    }
  }

  const handleSameAddressToggle = (e) => {
    const checked = e.target.checked
    setSameAddress(checked)
    if (checked) {
      setForm((current) => ({
        ...current,
        communicationAddress: current.permanentAddress,
        communicationCity: current.permanentCity,
        communicationState: current.permanentState,
        communicationCountry: current.permanentCountry,
        communicationPinCode: current.permanentPinCode,
      }))
    } else {
      setForm((current) => ({
        ...current,
        communicationAddress: '',
        communicationCity: '',
        communicationState: '',
        communicationCountry: '',
        communicationPinCode: '',
      }))
    }
  }

  function validateCurrentStep() {
    const formEl = formRef.current
    if (!formEl) return true

    // Native required-field validation for the visible step only
    const stepEl = formEl.querySelector(`[data-step="${step}"]`)
    const fields = stepEl
      ? stepEl.querySelectorAll('input, select, textarea')
      : formEl.querySelectorAll('input, select, textarea')

    const allValid = Array.from(fields).every((field) => {
      if (field.disabled) return true
      if (field.required && !field.checkValidity()) return false
      return true
    })

    if (!allValid) {
      setError('Please fill out all required fields correctly.')
      return false
    }

    const activeErrors = Object.values(fieldErrors).filter(Boolean)
    if (activeErrors.length > 0) {
      setError('Please fix the errors in the form before continuing.')
      return false
    }

    if (step === 3) {
      for (const [label, file] of [
        ['Aadhaar document', aadhaarFile],
        ['PAN document', panFile],
      ]) {
        if (!file) {
          setError(`Please upload your ${label}.`)
          return false
        }
        if (file.size > maxDocumentSize) {
          setError(`${label} must be 10 MB or smaller.`)
          return false
        }
        if (!acceptedDocumentTypes.has(file.type)) {
          setError(`${label} must be a PDF, PNG or JPG file.`)
          return false
        }
      }

      if (form.aadhaarNumber.length !== 12) {
        setError('Please enter a valid 12-digit Aadhaar number.')
        return false
      }
      if (!/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(form.panNumber)) {
        setError('Please enter a valid PAN (e.g. ABCDE1234F).')
        return false
      }
    }
    return true
  }

  function handleContinue(event) {
    event.preventDefault()
    setError('')
    if (!validateCurrentStep()) return
    setStep((s) => s + 1)
    topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  function handleBack() {
    setError('')
    setStep((s) => s - 1)
    topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }

  async function handleSubmit(event) {
    event.preventDefault()
    setError('')
    if (!validateCurrentStep()) return

    setLoading(true)
    try {
      const payload = new FormData()
      Object.entries(form).forEach(([key, value]) => {
        payload.set(key, value ?? '')
      })
      payload.set('aadhaarFile', aadhaarFile)
      payload.set('panFile', panFile)

      if (profileImage) {
        payload.set('profileImage', profileImage)
      }

      const response = await submitPublicApplication(payload)
      setResult(response)
      topRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    } catch (err) {
      setError(err.message || 'Could not submit your application.')
    } finally {
      setLoading(false)
    }
  }

  // ── SUCCESS SCREEN ──────────────────────────────────────────────
  if (result) {
  return (
    <main className="apply-app" style={{ backgroundColor: '#f1f5f9', minHeight: '100vh' }}>
      <div className="apply-topbar">
        <button className="apply-brand" type="button" onClick={() => navigate('/')}>
          <Brand />
        </button>
        <button className="back-home" onClick={() => navigate('/')}>
          <Icon name="arrowRight" size={15} style={{ transform: 'rotate(180deg)' }} /> Back to Nova Bank
        </button>
      </div>

      <div className="apply-layout-wide" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 'calc(100vh - 60px)', padding: '1rem' }}>
        
        {/* Modern Card Container */}
        <section 
          className="apply-success" 
          style={{ 
            background: '#ffffff', 
            padding: '0', 
            borderRadius: '16px', 
            textAlign: 'center', 
            maxWidth: '480px', 
            width: '100%',
            boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.05), 0 10px 10px -5px rgba(0, 0, 0, 0.02)', 
            border: '1px solid #e2e8f0',
            overflow: 'hidden'
          }}
        >
          {/* Top Colorful Gradient Bar */}
          <div style={{ height: '6px', width: '100%', background: 'linear-gradient(90deg, #6366f1, #a855f7, #ec4899)' }} />

          <div style={{ padding: '2.5rem 2rem' }}>
            
            {/* Animated Success Icon */}
            <div className="apply-success-icon" style={{ 
              display: 'inline-flex', 
              alignItems: 'center', 
              justifyContent: 'center',
              backgroundColor: '#ecfdf5', 
              color: '#10b981', 
              padding: '1rem', 
              borderRadius: '50%',
              border: '2px solid #d1fae5',
              marginBottom: '1.5rem',
              boxShadow: '0 0 0 8px rgba(16, 185, 129, 0.05)'
            }}>
              <Icon name="check" size={36} strokeWidth={3} />
            </div>

            <h1 style={{ fontSize: '1.5rem', fontWeight: '700', color: '#1e293b', margin: '0 0 0.5rem 0' }}>Application Received</h1>
            <p style={{ color: '#64748b', fontSize: '0.9rem', margin: '0 0 2rem 0', lineHeight: '1.5' }}>
              Thank you. Your Nova Bank account application has been submitted for review.
            </p>

            {/* Styled Details Box */}
            <div className="apply-success-card" style={{ 
              background: '#f8fafc', 
              border: '1px solid #e2e8f0', 
              borderRadius: '12px', 
              padding: '1rem 1.25rem', 
              marginBottom: '1.5rem',
              textAlign: 'left'
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingBottom: '0.75rem', borderBottom: '1px dashed #cbd5e1' }}>
                <span style={{ fontSize: '0.85rem', fontWeight: '500', color: '#64748b' }}>Reference ID</span>
                <b style={{ fontSize: '0.85rem', fontWeight: '700', color: '#4f46e5', backgroundColor: '#e0e7ff', padding: '0.25rem 0.5rem', borderRadius: '6px', letterSpacing: '0.5px' }}>
                  {result.id || result.customerId || '—'}
                </b>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '0.75rem' }}>
                <span style={{ fontSize: '0.85rem', fontWeight: '500', color: '#64748b' }}>Status</span>
                <b className="apply-status-pill" style={{ 
                  fontSize: '0.75rem', 
                  fontWeight: '700', 
                  color: '#b45309', 
                  backgroundColor: '#fef3c7', 
                  padding: '0.25rem 0.75rem', 
                  borderRadius: '999px',
                  textTransform: 'uppercase',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.25rem'
                }}>
                  {result.status || 'KYC PENDING'}
                </b>
              </div>
            </div>

            <p className="apply-success-note" style={{ fontSize: '0.8rem', color: '#94a3b8', lineHeight: '1.6', marginBottom: '2rem', padding: '0 0.5rem' }}>
              {isApiConfigured
                ? 'Once our team verifies your KYC and opens your account, we will email your username and password. You can then log in from the Nova Bank home page.'
                : 'Demo preview only — no real data was stored.'}
            </p>

            {/* Modernized Buttons */}
            <div className="apply-success-actions" style={{ display: 'flex', gap: '0.75rem', justifyContent: 'center', flexWrap: 'wrap' }}>
              <button 
                className="button button-primary" 
                onClick={() => navigate('/')}
                style={{ 
                  flex: 1, 
                  minWidth: '140px',
                  padding: '0.75rem 1rem', 
                  borderRadius: '10px', 
                  fontWeight: '600',
                  backgroundColor: '#4f46e5',
                  color: '#ffffff',
                  border: 'none',
                  cursor: 'pointer',
                  boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)',
                  transition: 'all 0.2s'
                }}
              >
                Back to home
              </button>
              <button 
                className="button button-secondary" 
                onClick={() => navigate('/login')}
                style={{ 
                  flex: 1, 
                  minWidth: '140px',
                  padding: '0.75rem 1rem', 
                  borderRadius: '10px', 
                  fontWeight: '600',
                  backgroundColor: '#ffffff',
                  color: '#334155',
                  border: '1px solid #e2e8f0',
                  cursor: 'pointer',
                  transition: 'all 0.2s'
                }}
              >
                Go to login
              </button>
            </div>
            
          </div>
        </section>
      </div>
    </main>
  )
}

  // ── FORM SCREEN ────────────────────────────────────────────────
  return (
    <main className="apply-app">
      <div className="apply-topbar">
        <button className="apply-brand" type="button" onClick={() => navigate('/')}>
          <Brand />
        </button>
        <button className="back-home" onClick={() => navigate('/')}>
          <Icon name="arrowRight" size={15} style={{ transform: 'rotate(180deg)' }} /> Back to Home
        </button>
      </div>

      <div className="apply-layout-wide" ref={topRef}>
        {/* SIDEBAR */}
        <aside className="apply-sidebar">
          <div className="sidebar-content">
            <h1>Welcome to<br /><span>Nova Bank</span></h1>
            <p className="tagline">Secure. Simple. Smart.</p>

            <div className="sidebar-features">
              <div className="feature">
                <span className="feature-icon">️</span>
                <div>
                  <h4>Bank with Confidence</h4>
                  <p>Your data is protected by bank-grade encryption.</p>
                </div>
              </div>
              <div className="feature">
                <span className="feature-icon">⚡</span>
                <div>
                  <h4>Fast &amp; Easy Onboarding</h4>
                  <p>Open your account in just a few simple steps.</p>
                </div>
              </div>
              <div className="feature">
                <span className="feature-icon"></span>
                <div>
                  <h4>24/7 Support</h4>
                  <p>We're always here to help you with your financial journey.</p>
                </div>
              </div>
            </div>

            <div className="sidebar-footer">
              <p>Your Dreams.<br />Our Commitment.</p>
            </div>
          </div>
        </aside>

        {/* FORM */}
        <form
          ref={formRef}
          className="apply-form-compact"
          onSubmit={step === 3 ? handleSubmit : handleContinue}
          noValidate
        >
          <div className="apply-form-header">
            <h2>Open your Nova Bank Account</h2>
            <span>Please fill all required (*) fields.</span>
          </div>

          <div className="apply-steps-header">
            <div className={`apply-step-title ${step >= 1 ? 'active' : ''}`}>
              <span>1</span> Personal details
            </div>
            <div className={`apply-step-divider ${step >= 2 ? 'active' : ''}`} />
            <div className={`apply-step-title ${step >= 2 ? 'active' : ''}`}>
              <span>2</span> Address &amp; account
            </div>
            <div className={`apply-step-divider ${step >= 3 ? 'active' : ''}`} />
            <div className={`apply-step-title ${step >= 3 ? 'active' : ''}`}>
              <span>3</span> Identity documents
            </div>
          </div>

          {/* STEP 1 */}
          {step === 1 && (
            <div className="apply-section fade-in" data-step="1">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Title <b className="req">*</b></span>
                  <select value={form.title} onChange={(e) => setField('title', e.target.value)} required>
                    <option value="MR">Mr</option>
                    <option value="MS">Ms</option>
                    <option value="MRS">Mrs</option>
                    <option value="DR">Dr</option>
                  </select>
                </label>

                <label className="form-label apply-span-2">
                  <span>Full name (as on ID) <b className="req">*</b></span>
                  <input
                    required
                    value={form.name}
                    onChange={(e) => setField('name', e.target.value)}
                    placeholder="As shown on your ID"
                  />
                </label>

                <label className="form-label">
                  <span>Date of birth <b className="req">*</b></span>
                  <input type="date" required max={new Date().toISOString().slice(0, 10)} value={form.dateOfBirth} onChange={(e) => setField('dateOfBirth', e.target.value)} />
                </label>

                <label className="form-label">
                  <span>Gender <b className="req">*</b></span>
                  <select value={form.gender} onChange={(e) => setField('gender', e.target.value)} required>
                    <option value="MALE">Male</option>
                    <option value="FEMALE">Female</option>
                    <option value="OTHER">Other</option>
                  </select>
                </label>

                <label className="form-label apply-span-2">
                  <span>Email <b className="req">*</b></span>
                  <input type="email" required value={form.email} onChange={(e) => setField('email', e.target.value)} placeholder="you@example.com" />
                </label>

                <label className="form-label">
                  <span>Mobile number <b className="req">*</b></span>
                  <input
                    type="tel"
                    required
                    inputMode="numeric"
                    value={form.phone}
                    onChange={(e) => setField('phone', e.target.value.replace(/\D/g, '').slice(0, 10))}
                    placeholder="10 digits"
                    style={{ borderColor: fieldErrors.phone ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.phone && <small className="field-error-text">{fieldErrors.phone}</small>}
                </label>

                <label className="form-label">
                  <span>Alt mobile</span>
                  <input
                    type="tel"
                    inputMode="numeric"
                    value={form.alternateMobileNumber}
                    onChange={(e) => setField('alternateMobileNumber', e.target.value.replace(/\D/g, '').slice(0, 10))}
                    placeholder="10 digits"
                    style={{ borderColor: fieldErrors.alternateMobileNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.alternateMobileNumber && <small className="field-error-text">{fieldErrors.alternateMobileNumber}</small>}
                </label>

                <label className="form-label">
                  <span>Nationality <b className="req">*</b></span>
                  <input required value={form.nationality} onChange={(e) => setField('nationality', e.target.value)} />
                </label>

                <label className="form-label">
                  <span>Marital status <b className="req">*</b></span>
                  <select value={form.maritalStatus} onChange={(e) => setField('maritalStatus', e.target.value)} required>
                    <option value="SINGLE">Single</option>
                    <option value="MARRIED">Married</option>
                    <option value="DIVORCED">Divorced</option>
                    <option value="WIDOWED">Widowed</option>
                  </select>
                </label>

                <label className="form-label">
                  <span>Language</span>
                  <input value={form.language} onChange={(e) => setField('language', e.target.value)} placeholder="e.g. Hindi" />
                </label>

                <label className="form-label apply-span-3">
                  <span>Profile photo</span>
                  <input
                    type="file"
                    accept="image/png,image/jpeg"
                    onChange={(e) => setProfileImage(e.target.files?.[0] || null)}
                  />
                  <small className="field-help-text" style={{ display: 'block', marginTop: '4px' }}>
                    Optional. JPG or PNG, up to 10 MB.
                  </small>
                </label>
              </div>
            </div>
          )}

          {/* STEP 2 */}
          {step === 2 && (
            <div className="apply-section fade-in" data-step="2">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Account type <b className="req">*</b></span>
                  <select value={form.accountType} onChange={(e) => setField('accountType', e.target.value)} required>
                    <option value="SAVINGS">Savings account</option>
                    <option value="CURRENT">Current account</option>
                  </select>
                </label>
                <label className="form-label">
                  <span>Currency <b className="req">*</b></span>
                  <select value={form.currency} onChange={(e) => setField('currency', e.target.value)} required>
                    <option value="INR">INR</option>
                  </select>
                </label>
                <label className="form-label">
                  <span>Branch <b className="req">*</b></span>
                  <select required value={form.preferredBranchCode} onChange={(e) => setField('preferredBranchCode', e.target.value)} disabled={branchesLoading}>
                    <option value="" disabled>{branchesLoading ? 'Loading…' : 'Select a branch'}</option>
                    {branches.map((b) => (
                      <option key={b.branchCode} value={b.branchCode}>
                        {b.branchName} {b.city ? `— ${b.city}` : ''}
                      </option>
                    ))}
                  </select>
                </label>

                <label className="form-label">
                  <span>Opening balance (INR)</span>
                  <input
                    readOnly
                    value={`₹ ${Number(form.openingBalance).toLocaleString('en-IN')}`}
                  />
                  <small className="field-help-text">
                    Auto-set: Savings = ₹1,000 · Current = ₹10,000
                  </small>
                </label>

                <label className="form-label apply-span-2">
                  <span>Permanent Address <b className="req">*</b></span>
                  <input required value={form.permanentAddress} onChange={(e) => setField('permanentAddress', e.target.value)} placeholder="House number and street" />
                </label>
                <label className="form-label">
                  <span>City <b className="req">*</b></span>
                  <input required value={form.permanentCity} onChange={(e) => setField('permanentCity', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>State <b className="req">*</b></span>
                  <input required value={form.permanentState} onChange={(e) => setField('permanentState', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>Country <b className="req">*</b></span>
                  <input required value={form.permanentCountry} onChange={(e) => setField('permanentCountry', e.target.value)} />
                </label>
                <label className="form-label">
                  <span>PIN code <b className="req">*</b></span>
                  <input required inputMode="numeric" pattern="[0-9]{4,10}" value={form.permanentPinCode} onChange={(e) => setField('permanentPinCode', e.target.value.replace(/\D/g, ''))} />
                </label>

                <div className="apply-checkbox-wrapper apply-span-3">
                  <label className="apply-checkbox-label">
                    <input type="checkbox" checked={sameAddress} onChange={handleSameAddressToggle} />
                    Communication Address is same as Permanent Address
                  </label>
                </div>

                <label className="form-label apply-span-2">
                  <span>Communication Address</span>
                  <input value={form.communicationAddress} onChange={(e) => setField('communicationAddress', e.target.value)} disabled={sameAddress} placeholder="House number and street" />
                </label>
                <label className="form-label">
                  <span>City</span>
                  <input value={form.communicationCity} onChange={(e) => setField('communicationCity', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>State</span>
                  <input value={form.communicationState} onChange={(e) => setField('communicationState', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>Country</span>
                  <input value={form.communicationCountry} onChange={(e) => setField('communicationCountry', e.target.value)} disabled={sameAddress} />
                </label>
                <label className="form-label">
                  <span>PIN code</span>
                  <input inputMode="numeric" pattern="[0-9]{4,10}" value={form.communicationPinCode} onChange={(e) => setField('communicationPinCode', e.target.value.replace(/\D/g, ''))} disabled={sameAddress} />
                </label>

                <div className="apply-section-divider apply-span-3" />

                <label className="form-label">
                  <span>Occupation <b className="req">*</b></span>
                  <select required value={form.occupation} onChange={(e) => setField('occupation', e.target.value)}>
                    <option value="" disabled>Select occupation</option>
                    <option value="SALARIED">Salaried employee</option>
                    <option value="SELF_EMPLOYED">Self-employed</option>
                    <option value="BUSINESS_OWNER">Business owner</option>
                    <option value="PROFESSIONAL">Professional</option>
                    <option value="STUDENT">Student</option>
                    <option value="RETIRED">Retired</option>
                    <option value="OTHER">Other</option>
                  </select>
                </label>
                <label className="form-label">
                  <span>Annual income (INR) <b className="req">*</b></span>
                  <input required type="number" min="0" step="0.01" value={form.annualIncome} onChange={(e) => setField('annualIncome', e.target.value)} placeholder="Example: 600000" />
                </label>

                <label className="form-label">
                  <span>Source of income <b className="req">*</b></span>
                  <select value={form.sourceOfIncome} onChange={(e) => setField('sourceOfIncome', e.target.value)} required>
                    <option value="" disabled>Select source</option>
                    <option value="SALARY">Salary</option>
                    <option value="BUSINESS">Business</option>
                    <option value="INVESTMENT">Investment</option>
                    <option value="PENSION">Pension</option>
                    <option value="RENTAL_INCOME">Rental income</option>
                    <option value="OTHER">Other</option>
                  </select>
                </label>
              </div>
            </div>
          )}

          {/* STEP 3 */}
          {step === 3 && (
            <div className="apply-section fade-in" data-step="3">
              <div className="apply-grid-3">
                <label className="form-label">
                  <span>Aadhaar number <b className="req">*</b></span>
                  <input
                    required
                    inputMode="numeric"
                    value={form.aadhaarNumber}
                    onChange={(e) => setField('aadhaarNumber', e.target.value.replace(/\D/g, '').slice(0, 12))}
                    placeholder="12-digit number"
                    style={{ borderColor: fieldErrors.aadhaarNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.aadhaarNumber && <small className="field-error-text">{fieldErrors.aadhaarNumber}</small>}
                </label>

                <label className="form-label">
                  <span>PAN number <b className="req">*</b></span>
                  <input
                    required
                    maxLength={10}
                    value={form.panNumber}
                    onChange={(e) => setField('panNumber', e.target.value.toUpperCase().slice(0, 10))}
                    placeholder="ABCDE1234F"
                    style={{ borderColor: fieldErrors.panNumber ? '#ef4444' : undefined }}
                  />
                  {fieldErrors.panNumber && <small className="field-error-text">{fieldErrors.panNumber}</small>}
                </label>

                <div className="apply-spacer" />

                <label className="form-label">
                  <span>Aadhaar document <b className="req">*</b></span>
                  <input type="file" required accept=".pdf,.png,.jpg,.jpeg" onChange={(e) => setAadhaarFile(e.target.files?.[0] || null)} />
                  <small className="field-help-text">PDF, PNG or JPG · max 10 MB</small>
                </label>
                <label className="form-label">
                  <span>PAN document <b className="req">*</b></span>
                  <input type="file" required accept=".pdf,.png,.jpg,.jpeg" onChange={(e) => setPanFile(e.target.files?.[0] || null)} />
                  <small className="field-help-text">PDF, PNG or JPG · max 10 MB</small>
                </label>
              </div>

              <p className="apply-hint" style={{ fontSize: '0.8rem', color: '#64748b', marginTop: '1rem' }}>
                Your documents are transmitted securely and used only for KYC verification.
              </p>
            </div>
          )}

          {error && <p className="form-error" role="alert" style={{ marginTop: '12px' }}>{error}</p>}

          {/* ACTIONS */}
          <div className="apply-actions" style={{ display: 'flex', justifyContent: 'space-between', width: '100%', marginTop: '1.5rem' }}>
            <div>
              {step > 1 ? (
                <button type="button" className="button button-secondary" onClick={handleBack} disabled={loading}>
                  Back
                </button>
              ) : (
                <button type="button" className="button button-secondary" onClick={() => navigate('/')}>
                  Cancel
                </button>
              )}
            </div>
            <button type="submit" className="button button-primary" disabled={loading || branchesLoading}>
              {loading ? 'Submitting…' : step === 3 ? 'Submit Application' : 'Continue'}
              <Icon name={step === 3 ? 'check' : 'arrowRight'} size={16} />
            </button>
          </div>
        </form>
      </div>
    </main>
  )
}

import { ApiError, apiRequest, isApiConfigured } from './apiClient'

const demoApplicationKey = (customer) =>
  `nova.demo.account-application.${encodeURIComponent(
    customer?.id || customer?.email || 'anonymous'
  )}`

const demoOverview = {
  currency: 'INR',
  totalBalance: 0,
  accounts: [],
  transactions: [],
}

const demoBranches = [
  {
    id: 1,
    branchCode: 'NOVA42K',
    branchName: 'Nova Bank Delhi Main Branch',
    ifscCode: 'NOVA0001234',
    city: 'New Ashok Nagar',
    district: 'East Delhi',
    state: 'Delhi',
    status: 'ACTIVE',
  },
]

/* =====================================================
   Shared helpers
===================================================== */
const getField = (payload, key) =>
  payload instanceof FormData ? payload.get(key) : payload?.[key]

const optionalField = (payload, key) => {
  const value = getField(payload, key)
  if (typeof value !== 'string') return value || null
  const trimmed = value.trim()
  return trimmed || null
}

const digitsOnly = (value) =>
  value == null ? '' : String(value).replace(/\D/g, '')

const buildCustomerDetails = (payload) => ({
  accountType: String(getField(payload, 'accountType') || 'SAVINGS').toUpperCase(),
  currency: getField(payload, 'currency') || 'INR',
  title: String(getField(payload, 'title') || 'MR').toUpperCase(),
  name: getField(payload, 'name')?.trim(),
  openingBalance: Number(getField(payload, 'openingBalance') || 0),
  dateOfBirth: getField(payload, 'dateOfBirth')
    ? String(getField(payload, 'dateOfBirth')).split('T')[0]
    : null,
  gender: String(getField(payload, 'gender') || 'MALE').toUpperCase(),
  nationality: getField(payload, 'nationality')?.trim(),
  maritalStatus: String(
    optionalField(payload, 'maritalStatus') || 'SINGLE'
  ).toUpperCase(),
  email: getField(payload, 'email')?.trim(),
  mobileNumber: digitsOnly(getField(payload, 'phone')),
  alternateMobileNumber:
    digitsOnly(optionalField(payload, 'alternateMobileNumber')) || null,
  branchCode: getField(payload, 'preferredBranchCode'),
  branchName: null,
  ifscCode: null,
  permanentAddress: getField(payload, 'permanentAddress')?.trim(),
  permanentCity: getField(payload, 'permanentCity')?.trim(),
  permanentState: getField(payload, 'permanentState')?.trim(),
  permanentCountry: getField(payload, 'permanentCountry')?.trim(),
  permanentPinCode: getField(payload, 'permanentPinCode')?.trim(),
  communicationAddress: optionalField(payload, 'communicationAddress'),
  communicationCity: optionalField(payload, 'communicationCity'),
  communicationState: optionalField(payload, 'communicationState'),
  communicationCountry: optionalField(payload, 'communicationCountry'),
  communicationPinCode: optionalField(payload, 'communicationPinCode'),
  occupation: optionalField(payload, 'occupation'),
  annualIncome: optionalField(payload, 'annualIncome')
    ? Number(optionalField(payload, 'annualIncome'))
    : null,
  sourceOfIncome: String(
    optionalField(payload, 'sourceOfIncome') || 'SALARY'
  ).toUpperCase(),
  language: optionalField(payload, 'language'),
})

const buildCustomerForm = (customerDetails, payload) => {
  const form = new FormData()
  form.set(
    'customer',
    new Blob([JSON.stringify(customerDetails)], { type: 'application/json' })
  )
  const imageFile = getField(payload, 'profileImage')
  if (imageFile instanceof File || imageFile instanceof Blob) {
    form.set('profileImage', imageFile, imageFile.name || 'profileImage.jpg')
  }
  return form
}

const buildKycForm = (fields, payload) => {
  const form = new FormData()
  const appendText = (key, value) => {
    if (value !== undefined && value !== null && String(value).length > 0) {
      form.set(key, String(value))
    }
  }

  appendText('customerId', fields.customerId)
  appendText('kycType', fields.kycType || 'IDENTITY')
  appendText('preferredBranchCode', fields.preferredBranchCode)
  appendText('aadhaarNumber', fields.aadhaarNumber?.trim())
  appendText('panNumber', fields.panNumber?.trim().toUpperCase())
  appendText('name', fields.name?.trim())
  appendText('email', fields.email?.trim())
  appendText('mobileNumber', digitsOnly(fields.mobileNumber))

  for (const key of ['aadhaarFile', 'panFile']) {
    const file = getField(payload, key)
    if (file instanceof File || file instanceof Blob) {
      form.set(key, file, file.name || key)
    }
  }
  return form
}

/* =====================================================
   Fetch Active Branches (branch-service)
===================================================== */
export async function getActiveBranches() {
  if (!isApiConfigured) return demoBranches

  try {
    const response = await apiRequest(
      '/branch-service/api/v1/branches?status=ACTIVE&page=0&size=100'
    )
    if (Array.isArray(response)) return response
    if (response && Array.isArray(response.content)) return response.content
    throw new Error('The branch service returned an invalid branch list.')
  } catch (error) {
    console.error('Failed to fetch branches:', error)
    throw error
  }
}

/* =====================================================
   Customer Direct Deposit (PATCH /deposit/{accountNumber})
===================================================== */
export async function depositToAccount(accountNumber, amount) {
  if (!accountNumber) throw new Error('Account Number is required.')
  if (!amount || amount <= 0) throw new Error('Valid amount is required.')

  if (isApiConfigured) {
    return apiRequest(
      `/account-service/api/v1/accounts/deposit/${encodeURIComponent(accountNumber)}`,
      {
        method: 'PATCH',
        body: JSON.stringify({ amount: Number(amount) }),
      }
    )
  }

  return 'Demo deposit successful'
}

/* =====================================================
   Update Customer Profile (PUT /update-customer-profile)
===================================================== */
export async function updateCustomerProfile(customerId, payload) {
  if (!isApiConfigured) {
    return { message: 'Demo profile updated successfully' }
  }

  return apiRequest(
    `/customer-service/api/v1/customers/update-customer-profile`,
    {
      method: 'PUT',
      body: JSON.stringify(payload),
    }
  )
}

/* =====================================================
   PUBLIC (guest) account application — NO LOGIN REQUIRED
===================================================== */
export async function submitPublicApplication(payload) {
  const customerDetails = buildCustomerDetails(payload)

  if (!isApiConfigured) {
    const application = {
      id: `NVB-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,
      status: 'KYC_PENDING',
      accountType: customerDetails.accountType,
      branchCode: customerDetails.branchCode,
      submittedAt: new Date().toISOString(),
      currentStage: 'KYC_REVIEW',
      message:
        'Demo preview only. With the backend connected, your application would be submitted to Nova Bank for KYC review.',
    }
    try {
      sessionStorage.setItem(
        demoApplicationKey({ email: customerDetails.email }),
        JSON.stringify(application)
      )
    } catch (e) {
      /* ignore storage errors */
    }
    return application
  }

  let profile
  try {
    const customerForm = buildCustomerForm(customerDetails, payload)
    profile = await apiRequest('/customer-service/api/v1/customers/create', {
      method: 'POST',
      body: customerForm,
    })
  } catch (error) {
    throw new Error(
      error?.message ||
        'Could not create your customer profile. Please check your details and try again.'
    )
  }

  if (!profile?.customerId) {
    throw new Error(
      'The customer service did not return a customerId. Please contact Nova Bank support.'
    )
  }

  let kyc
  try {
    const documentData = buildKycForm(
      {
        customerId: profile.customerId,
        kycType: 'IDENTITY',
        preferredBranchCode: customerDetails.branchCode,
        aadhaarNumber: getField(payload, 'aadhaarNumber'),
        panNumber: getField(payload, 'panNumber'),
        name: customerDetails.name,
        email: customerDetails.email,
        mobileNumber: customerDetails.mobileNumber,
      },
      payload
    )

    kyc = await apiRequest('/kyc-service/api/v1/kyc/submit/documents', {
      method: 'POST',
      body: documentData,
    })
  } catch (error) {
    throw new Error(
      error?.message ||
        'Your profile was created, but submitting your KYC documents failed. Please contact Nova Bank support with your email.'
    )
  }

  return {
    id: kyc.kycId || profile.customerId,
    customerId: profile.customerId,
    status: 'KYC_PENDING',
    currentStage: 'KYC_REVIEW',
    submittedAt: kyc.createdAt || new Date().toISOString(),
    branchCode: kyc.branchCode || customerDetails.branchCode,
    branchName: kyc.branchName || null,
    branchIfsc: kyc.branchIfsc || null,
    message:
      'Your application was received. Once our team verifies your KYC and opens your account, we will email your username and password.',
  }
}

/* =====================================================
   Customer Overview
===================================================== */
export async function getCustomerOverview(customer) {
  if (isApiConfigured) {
    let profile
    try {
      profile = await apiRequest('/customer-service/api/v1/customers/me')
    } catch (error) {
      if (error.status === 404) {
        return { ...demoOverview, customer: null, application: null }
      }
      throw error
    }

    const customerId = encodeURIComponent(profile.customerId)
    let [accounts, kycs, transactions] = await Promise.all([
      apiRequest(
        `/account-service/api/v1/accounts/customer/${customerId}`
      ).catch((error) => {
        if (error instanceof ApiError && error.status === 404) return []
        throw error
      }),
      apiRequest(`/kyc-service/api/v1/kyc/customer/${customerId}`).catch(
        (error) => {
          if (error instanceof ApiError && error.status === 404) return []
          throw error
        }
      ),
      apiRequest('/transaction-service/api/v1/transactions/mine').catch(
        (error) => {
          if (error instanceof ApiError && error.status === 404) return []
          throw error
        }
      ),
    ])

    accounts = accounts || []
    kycs = kycs || []
    transactions = transactions || []

    if (accounts.some((account) => !account.debitCard)) {
      accounts = await Promise.all(
        accounts.map((account) =>
          account.debitCard
            ? account
            : apiRequest(
                `/account-service/api/v1/accounts/${encodeURIComponent(
                  account.accountId
                )}/debit-card-preview`,
                { method: 'POST' }
              ).catch((error) => {
                if (error instanceof ApiError && error.status === 404)
                  return account
                throw error
              })
        )
      )
    }

    const latestKyc =
      [...kycs].sort(
        (left, right) =>
          new Date(right.createdAt || 0) - new Date(left.createdAt || 0)
      )[0] || null
    const kycStatus = String(latestKyc?.verificationStatus || '').toUpperCase()
    const application = latestKyc
      ? {
          id: latestKyc.kycId,
          status: accounts.length
            ? 'ACCOUNT_OPENED'
            : kycStatus === 'APPROVED'
            ? 'KYC_APPROVED'
            : kycStatus === 'REJECTED'
            ? 'REJECTED'
            : 'KYC_PENDING',
          currentStage: accounts.length
            ? 'ACCOUNT_OPENED'
            : kycStatus === 'APPROVED'
            ? 'ACCOUNT_OPENING'
            : 'KYC_REVIEW',
          submittedAt: latestKyc.createdAt,
          branchCode: latestKyc.branchCode,
          branchName: latestKyc.branchName,
          branchIfsc: latestKyc.branchIfsc,
          rejectionReason: latestKyc.rejectionReason,
          customerStatus: profile.status || 'PENDING',
        }
      : null

    const mappedAccounts = accounts.map((account) => ({
      id: account.accountId,
      name: `${
        account.accountType === 'CURRENT' ? 'Current' : 'Savings'
      } account`,
      accountNumber: account.accountNumber,
      currency: account.currency || 'INR',
      branchName: account.branchName,
      ifsc: account.ifsc,
      balance: Number(account.balance || 0),
      status: String(account.accountStatus || 'ACTIVE').toUpperCase(),
      createdAt: account.createdAt || null,
      updatedAt: account.updatedAt || null,
      debitCard:
        account.debitCard && typeof account.debitCard === 'object'
          ? {
              debitCardReference:
                account.debitCard.debitCardReference || null,
              cardStatus: String(
                account.debitCard.cardStatus || account.debitCard.status || ''
              ).toUpperCase(),
              lastFourDigits: String(
                account.debitCard.lastFourDigits ||
                  account.debitCard.last4 ||
                  account.debitCard.debitCardReference
                    ?.replace(/\s/g, '')
                    .slice(-4) ||
                  ''
              ).slice(-4),
              cardType: account.debitCard.cardType || 'VIRTUAL',
              issuedAt: account.debitCard.issuedAt || null,
              expiryDate: account.debitCard.expiryDate || null,
            }
          : null,
    }))

    //  UPDATED TRANSACTION MAPPING TO STRIP OUT UNWANTED FIELDS
    const mappedTransactions = transactions
      .map((transaction) => {
        const isCredit = transaction.transactionType === 'DEPOSIT'
        const signedAmount = isCredit
          ? Number(transaction.amount)
          : -Number(transaction.amount)

        const accountNumber =
          transaction.accountNumber ||
          transaction.fromAccountNumber ||
          transaction.toAccountNumber

        return {
          id: transaction.transactionId,
          name: transaction.description?.trim() || transaction.transactionType || 'Transaction',
          amount: signedAmount,
          currency: transaction.currency || 'INR',
          status: String(transaction.transactionStatus || 'UNKNOWN').toUpperCase(),
          transactionType: transaction.transactionType,
          createdAt: transaction.createdAt || null,
          reference: transaction.reference || transaction.transactionId,

          accountNumber: transaction.accountNumber || null,
          fromAccountNumber: transaction.fromAccountNumber || null,
          toAccountNumber: transaction.toAccountNumber || null,
          performedBy: transaction.performedBy || null,
          description: transaction.description || null,

          date: transaction.createdAt
            ? new Date(transaction.createdAt).toLocaleString('en-IN')
            : 'Date unavailable',
        }
      })
      .sort(
        (left, right) =>
          new Date(right.createdAt || 0) - new Date(left.createdAt || 0)
      )

    return {
      ...demoOverview,
      customer: profile,
      accounts: mappedAccounts,
      transactions: mappedTransactions,
      application,
      currency: mappedAccounts[0]?.currency || 'INR',
      totalBalance: mappedAccounts.reduce(
        (total, account) => total + account.balance,
        0
      ),
    }
  }

  let application = null
  try {
    application = JSON.parse(
      sessionStorage.getItem(demoApplicationKey(customer)) || 'null'
    )
  } catch (e) {
    application = null
  }

  return {
    ...demoOverview,
    application,
  }
}

/* =====================================================
   submitBankingAction
===================================================== */
export async function submitBankingAction(
  action,
  payload,
  customer,
  customerProfile,
  customerAccounts = []
) {
  if (isApiConfigured) {
    if (action === 'deposit-request') {
      const deposit = await apiRequest(
        '/transaction-service/api/v1/transactions/mine/deposits',
        {
          method: 'POST',
          body: JSON.stringify({
            accountNumber: payload.accountNumber,
            amount: payload.amount,
            currency: payload.currency,
            description: payload.description?.trim() || null,
          }),
        }
      )
      return {
        id: deposit.transactionId,
        reference: deposit.reference,
        status: deposit.transactionStatus,
        message:
          'Your cash deposit request is pending branch verification. Your account balance will change only after a teller or branch manager confirms receipt of the funds.',
      }
    }

    if (action === 'transfer') {
      const sourceAccount = customerAccounts.find(
        (account) => account.accountNumber === payload.fromAccountNumber
      )
      if (!sourceAccount || sourceAccount.status !== 'ACTIVE') {
        throw new Error('Choose one of your active accounts to send money from.')
      }
      const transfer = await apiRequest(
        '/transaction-service/api/v1/transactions/mine/transfer',
        {
          method: 'POST',
          body: JSON.stringify({
            fromAccountNumber: payload.fromAccountNumber,
            toAccountNumber: payload.toAccountNumber.trim(),
            amount: payload.amount,
            currency: sourceAccount.currency || 'INR',
            description: payload.description?.trim() || null,
          }),
        }
      )
      return {
        id: transfer.transactionId,
        reference: transfer.reference,
        message: `Transfer sent successfully. ${new Intl.NumberFormat('en-IN', {
          style: 'currency',
          currency: transfer.currency || sourceAccount.currency || 'INR',
        }).format(Number(transfer.amount))} sent to account ending ${transfer.toAccountNumber.slice(
          -4
        )}.`,
      }
    }

    if (action === 'account-application' || action === 'kyc-update') {
      const customerDetails =
        action === 'account-application'
          ? buildCustomerDetails(payload)
          : null

      let profile = customerProfile
      if (action === 'account-application') {
        if (!profile?.customerId) {
          try {
            profile = await apiRequest('/customer-service/api/v1/customers/me')
          } catch (error) {
            if (error.status !== 404) throw error
            profile = null
          }

          if (!profile?.customerId) {
            const customerForm = buildCustomerForm(customerDetails, payload)
            profile = await apiRequest(
              '/customer-service/api/v1/customers/create',
              {
                method: 'POST',
                body: customerForm,
              }
            )
          }
        } else {
          const customerForm = buildCustomerForm(customerDetails, payload)
          profile = await apiRequest(
            `/customer-service/api/v1/customers/update/${encodeURIComponent(
              profile.customerId
            )}`,
            {
              method: 'PUT',
              body: customerForm,
            }
          )
        }
      } else if (!profile?.customerId) {
        profile = await apiRequest('/customer-service/api/v1/customers/me')
      }

      const documentData = buildKycForm(
        {
          customerId: profile.customerId,
          kycType: 'IDENTITY',
          preferredBranchCode: getField(payload, 'preferredBranchCode'),
          aadhaarNumber: getField(payload, 'aadhaarNumber'),
          panNumber: getField(payload, 'panNumber'),
          name: getField(payload, 'name') || customer?.name,
          email: getField(payload, 'email') || customer?.email,
          mobileNumber:
            getField(payload, 'phone') || customer?.mobileNumber,
        },
        payload
      )

      const kyc = await apiRequest('/kyc-service/api/v1/kyc/submit/documents', {
        method: 'POST',
        body: documentData,
      })

      return {
        id: kyc.kycId,
        status: 'KYC_PENDING',
        currentStage: 'KYC_REVIEW',
        submittedAt: kyc.createdAt,
        branchCode: kyc.branchCode,
        branchName: kyc.branchName,
        branchIfsc: kyc.branchIfsc,
        customer: profile,
        message:
          action === 'kyc-update'
            ? 'Your updated KYC documents were submitted. Our team will review them shortly.'
            : undefined,
      }
    }

    throw new Error(
      'This action is not available from the connected banking services yet.'
    )
  }

  if (action === 'account-application' || action === 'kyc-update') {
    const application = {
      id: `NVB-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,
      status: 'KYC_PENDING',
      accountType: getField(payload, 'accountType'),
      branchCode: getField(payload, 'preferredBranchCode'),
      submittedAt: new Date().toISOString(),
      currentStage: 'KYC_REVIEW',
    }
    sessionStorage.setItem(
      demoApplicationKey(customer),
      JSON.stringify(application)
    )
    return application
  }

  return {
    status: 'preview',
    message: 'Preview only. Configure the backend API to submit this request.',
  }
}

import { ApiError, apiRequest, isApiConfigured } from './apiClient'

const demoApplicationKey = (customer) =>
  `nova.demo.account-application.${encodeURIComponent(
    customer?.id || customer?.email || 'anonymous'
  )}`

const demoOverview = {
  currency: 'INR',
  totalBalance: 0,
  accounts: [],
  transactions: [],
}

const demoBranches = [
  {
    id: 1,
    branchCode: 'NOVA42K',
    branchName: 'Nova Bank Delhi Main Branch',
    ifscCode: 'NOVA0001234',
    city: 'New Ashok Nagar',
    district: 'East Delhi',
    state: 'Delhi',
    status: 'ACTIVE',
  },
]

/* =====================================================
   Shared helpers
===================================================== */
const getField = (payload, key) =>
  payload instanceof FormData ? payload.get(key) : payload?.[key]

const optionalField = (payload, key) => {
  const value = getField(payload, key)
  if (typeof value !== 'string') return value || null
  const trimmed = value.trim()
  return trimmed || null
}

const digitsOnly = (value) =>
  value == null ? '' : String(value).replace(/\D/g, '')

const buildCustomerDetails = (payload) => ({
  accountType: String(getField(payload, 'accountType') || 'SAVINGS').toUpperCase(),
  currency: getField(payload, 'currency') || 'INR',
  title: String(getField(payload, 'title') || 'MR').toUpperCase(),
  name: getField(payload, 'name')?.trim(),
  openingBalance: Number(getField(payload, 'openingBalance') || 0),
  dateOfBirth: getField(payload, 'dateOfBirth')
    ? String(getField(payload, 'dateOfBirth')).split('T')[0]
    : null,
  gender: String(getField(payload, 'gender') || 'MALE').toUpperCase(),
  nationality: getField(payload, 'nationality')?.trim(),
  maritalStatus: String(
    optionalField(payload, 'maritalStatus') || 'SINGLE'
  ).toUpperCase(),
  email: getField(payload, 'email')?.trim(),
  mobileNumber: digitsOnly(getField(payload, 'phone')),
  alternateMobileNumber:
    digitsOnly(optionalField(payload, 'alternateMobileNumber')) || null,
  branchCode: getField(payload, 'preferredBranchCode'),
  branchName: null,
  ifscCode: null,
  permanentAddress: getField(payload, 'permanentAddress')?.trim(),
  permanentCity: getField(payload, 'permanentCity')?.trim(),
  permanentState: getField(payload, 'permanentState')?.trim(),
  permanentCountry: getField(payload, 'permanentCountry')?.trim(),
  permanentPinCode: getField(payload, 'permanentPinCode')?.trim(),
  communicationAddress: optionalField(payload, 'communicationAddress'),
  communicationCity: optionalField(payload, 'communicationCity'),
  communicationState: optionalField(payload, 'communicationState'),
  communicationCountry: optionalField(payload, 'communicationCountry'),
  communicationPinCode: optionalField(payload, 'communicationPinCode'),
  occupation: optionalField(payload, 'occupation'),
  annualIncome: optionalField(payload, 'annualIncome')
    ? Number(optionalField(payload, 'annualIncome'))
    : null,
  sourceOfIncome: String(
    optionalField(payload, 'sourceOfIncome') || 'SALARY'
  ).toUpperCase(),
  language: optionalField(payload, 'language'),
})

const buildCustomerForm = (customerDetails, payload) => {
  const form = new FormData()
  form.set(
    'customer',
    new Blob([JSON.stringify(customerDetails)], { type: 'application/json' })
  )
  const imageFile = getField(payload, 'profileImage')
  if (imageFile instanceof File || imageFile instanceof Blob) {
    form.set('profileImage', imageFile, imageFile.name || 'profileImage.jpg')
  }
  return form
}

const buildKycForm = (fields, payload) => {
  const form = new FormData()
  const appendText = (key, value) => {
    if (value !== undefined && value !== null && String(value).length > 0) {
      form.set(key, String(value))
    }
  }

  appendText('customerId', fields.customerId)
  appendText('kycType', fields.kycType || 'IDENTITY')
  appendText('preferredBranchCode', fields.preferredBranchCode)
  appendText('aadhaarNumber', fields.aadhaarNumber?.trim())
  appendText('panNumber', fields.panNumber?.trim().toUpperCase())
  appendText('name', fields.name?.trim())
  appendText('email', fields.email?.trim())
  appendText('mobileNumber', digitsOnly(fields.mobileNumber))

  for (const key of ['aadhaarFile', 'panFile']) {
    const file = getField(payload, key)
    if (file instanceof File || file instanceof Blob) {
      form.set(key, file, file.name || key)
    }
  }
  return form
}

/* =====================================================
   Fetch Active Branches (branch-service)
===================================================== */
export async function getActiveBranches() {
  if (!isApiConfigured) return demoBranches

  try {
    const response = await apiRequest(
      '/branch-service/api/v1/branches?status=ACTIVE&page=0&size=100'
    )
    if (Array.isArray(response)) return response
    if (response && Array.isArray(response.content)) return response.content
    throw new Error('The branch service returned an invalid branch list.')
  } catch (error) {
    console.error('Failed to fetch branches:', error)
    throw error
  }
}

/* =====================================================
   Customer Direct Deposit (PATCH /deposit/{accountNumber})
===================================================== */
export async function depositToAccount(accountNumber, amount) {
  if (!accountNumber) throw new Error('Account Number is required.')
  if (!amount || amount <= 0) throw new Error('Valid amount is required.')

  if (isApiConfigured) {
    return apiRequest(
      `/account-service/api/v1/accounts/deposit/${encodeURIComponent(accountNumber)}`,
      {
        method: 'PATCH',
        body: JSON.stringify({ amount: Number(amount) }),
      }
    )
  }

  return 'Demo deposit successful'
}

/* =====================================================
   Update Customer Profile (PUT /update-customer-profile)
===================================================== */
export async function updateCustomerProfile(customerId, payload) {
  if (!isApiConfigured) {
    return { message: 'Demo profile updated successfully' }
  }

  return apiRequest(
    `/customer-service/api/v1/customers/update-customer-profile`,
    {
      method: 'PUT',
      body: JSON.stringify(payload),
    }
  )
}

